// Üretilen dosya: tool/ozgun/uret.py. İstatistik ve Veri Bilimi · Bayes çıkarımı, tanı testleri (duyarlılık, özgüllük, temel oran yanılgısı), karar ağaçları ve beklenen değer hesapları (zor).
const ozStatistics15Zor = <(String, String, List<String>, String)>[
  ('Thomas Bayes\'in vefatından sonra makalesini düzenleyip 1763 yılında Kraliyet Cemiyetine sunarak bilim dünyasına kazandıran düşünür kimdir?', 'Richard Price', ['Abraham de Moivre', 'Francis Galton', 'Karl Pearson'], 'Bayes\'in ters olasılık üzerine yazdığı ünlü deneme, dostu Richard Price tarafından yayına hazırlanıp Kraliyet Cemiyetinde okunmuştur.'),
  ('Dennis Lindley tarafından ortaya atılan Cromwell kuralı, Bayesçi karar vericileri hangi hataya karşı uyarır?', 'Mantıksal açıdan imkânsız olmayan olaylara tam 0 veya 1 önsel olasılık vermekten kaçınılması', ['Örneklem hacmi otuzun altındayken normal dağılım varsayımının kullanılması', 'Bağımlı iki olayın kesişim olasılığının doğrudan çarpılarak hesaplanması', 'Sonsal dağılımın ortalaması yerine her zaman tepe değerinin raporlanması'], 'Önsel olasılık tam 0 seçilirse ne kadar güçlü kanıt gelirse gelsin Bayes çarpımı 0 kalır; bu yüzden aşırı kesin önsellerden kaçınılır.'),
  ('Bir maden mühendisi sondaj yapılacak arazide bakır rezervi bulunma önsel olasılığını 0,30 olarak belirliyor. Manyetik anomali ölçümünün rezerv varken pozitif çıkma olasılığı 0,80, rezerv yokken pozitif çıkma olasılığı 0,10\'dur. Ölçüm negatif çıktığında rezerv bulunma sonsal olasılığı kesir olarak kaçtır?', '2/23', ['6/31', '3/25', '7/34'], 'Negatif kanıt için P(Neg|Var)=0,20 ve P(Neg|Yok)=0,90 olur. Sonsal olasılık = (0,30×0,20) / (0,30×0,20 + 0,70×0,90) = 0,06 / 0,69 = 6/69 = 2/23 bulunur.'),
  ('Önsel dağılım ile sonsal dağılımın aynı matematiksel dağılım ailesine ait olmasını sağlayan (örneğin binom olabilirliği için Beta dağılımı kullanılması gibi) özel önsel seçimine ne ad verilir?', 'Eşlenik (conjugate) önsel', ['Ortogonel (dikgen) önsel', 'Süreksiz basamak önseli', 'Parametrik olmayan çekirdek önseli'], 'Analitik hesaplamayı kolaylaştıran ve güncelleme sonrasında aynı dağılım ailesinde kalmayı sağlayan önsellere eşlenik önsel denir.'),
  ('Bir e-ticaret sitesinde yeni açılan bir satıcı hesabının sahte (dolandırıcı) olma önsel olasılığı %2\'dir. Sahte hesapların %80\'i ilk gün 50\'den fazla ürün yüklerken, gerçek satıcıların yalnızca %1\'i ilk gün 50\'den fazla ürün yüklemektedir. İlk gün 65 ürün yükleyen yeni bir hesabın sahte olma olasılığı hangi kesre eşittir?', '80/129', ['16/25', '40/89', '8/13'], 'Pay = 0,02 × 0,80 = 0,0160. Payda = 0,0160 + 0,98 × 0,01 = 0,0160 + 0,0098 = 0,0258. Oran = 160/258 = 80/129 bulunur.'),
  ('Bir sismoloji istasyonu bölgedeki sarsıntının doğal fay kırılmasından kaynaklanma önsel olasılığını 0,90, taş ocağı patlatmasından kaynaklanma olasılığını 0,10 kabul ediyor. Yüzey dalgası genliğinin sığ karakter gösterme olasılığı taş ocağı patlatmalarında 0,95, doğal sarsıntılarda 0,05\'tir. Sığ karakterli dalga kaydedildiğinde sarsıntının taş ocağı kaynaklı olma olasılığı yüzde kaçtır?', '%67,86 (19/28)', ['%52,63 (10/19)', '%81,25 (13/16)', '%47,50 (19/40)'], 'Pay = 0,10 × 0,95 = 0,095. Payda = 0,095 + 0,90 × 0,05 = 0,095 + 0,045 = 0,140. Oran = 95/140 = 19/28 ≈ %67,86 bulunur.'),
  ('Öznel (subjektif) Bayesçi olasılık yorumunu yirminci yüzyılda \'tutarlı bahis oranları\' (coherence) aksiyomları üzerine kuran önde gelen kuramcılar kimlerdir?', 'Bruno de Finetti ve Leonard Jimmie Savage', ['Jerzy Neyman ve Egon Pearson', 'Ronald Fisher ve Gosset', 'Andrey Kolmogorov ve Aleksandr Hinçin'], 'De Finetti ve Savage, olasılığı rasyonel bir bireyin kesin kayba uğramayacak (Dutch book içermeyen) tutarlı öznel inanç derecesi olarak temellendirmiştir.'),
  ('Bir satranç turnuvasında çevrim içi oynayan bir oyuncunun bilgisayardan hamle yardımı alma önsel olasılığı %1\'dir. Hamlelerin motorun birinci tercihiyle %98 örtüşmesi hile yapanların %90\'ında, dürüst ustaların ise %0,5\'inde görülür. Böyle bir örtüşme yakalandığında oyuncunun gerçekten hile yapıyor olma olasılığı kaçtır?', '180/279 (20/31)', ['90/189 (10/21)', '9/19', '45/94'], 'Pay = 0,01 × 0,90 = 0,0090. Payda = 0,0090 + 0,99 × 0,005 = 0,0090 + 0,00495 = 0,01395. Oran = 900/1395 = 20/31 olur.'),
  ('Üç farklı torbadan birincisinde 3 kırmızı 1 mavi, ikincisinde 2 kırmızı 2 mavi, üçüncüsünde 1 kırmızı 3 mavi bilye vardır. Zar atılarak zar 1 gelirse birinci, 2 veya 3 gelirse ikinci, 4, 5 veya 6 gelirse üçüncü torba seçiliyor. Seçilen torbadan çekilen bir bilye kırmızı çıktığına göre birinci torbanın seçilmiş olma olasılığı kaçtır?', '3/10', ['1/4', '3/8', '2/5'], 'Önseller: 1/6, 2/6, 3/6. Kırmızı olabilirlikleri: 3/4, 2/4, 1/4. Pay = (1/6)(3/4) = 3/24. Payda = (3 + 4 + 3)/24 = 10/24. Oran = 3/10.'),
  ('İkinci Dünya Savaşı sırasında Bletchley Park\'ta Alman Enigma şifrelerini kırarken Bayesçi kanıt ağırlığı (\'banburismus\' ve desiban birimi) yöntemini geliştiren ünlü bilim insanı kimdir?', 'Alan Turing', ['John von Neumann', 'Claude Shannon', 'Norbert Wiener'], 'Alan Turing ve I. J. Good, Enigma ayarlarına ilişkin hipotezlerin olasılıklarını logaritmik Bayes çarpanlarıyla güncelleyen Banburismus tekniğini kullanmıştır.'),
  ('Logaritmik kanıt ağırlığı yaklaşımında olabilirlik oranının 10 tabanında logaritması alınarak kanıt gücü ölçülür. Bir kanıtın olabilirlik oranı 100 olduğunda logaritmik kanıt ağırlığı (Hartley/ban cinsinden) kaç birimdir?', '+2 birim', ['+10 birim', '+0,5 birim', '+20 birim'], 'log10(100) = 2 olduğundan hipotez lehine kanıt ağırlığı tam +2 ban (veya 20 desiban) olarak eklenir.'),
  ('Bayes teoreminde iki ayrık ve tümleyen hipotez (H ve H\') için P(V|H) = 0,60 ve P(V|H\') = 0,20 olarak biliniyor. H hipotezinin sonsal olasılığının tam 0,50 çıkması için başlangıçtaki önsel olasılık P(H) kaç olmalıdır?', '0,25', ['0,33', '0,50', '0,20'], 'Sonsal bahis 1:1 olması için Önsel bahis × (0,60/0,20) = 1 => Önsel bahis × 3 = 1 => P(H)/(1-P(H)) = 1/3 => P(H) = 1/4 = 0,25 olmalıdır.'),
  ('Ampirik Bayes (Empirical Bayes) yaklaşımını saf öznel Bayes yaklaşımından ayıran temel uygulama farkı nedir?', 'Önsel dağılımın hiperparametrelerinin uzman görüşü yerine doğrudan eldeki toplu veriden tahmin edilmesi', ['Sonsal olasılık hesaplanırken olabilirlik fonksiyonunun denklem dışına çıkarılması', 'Hipotez uzayının yalnızca iki elemanlı ikili olaylarla sınırlandırılması', 'Koşullu olasılık yerine yalnızca aritmetik medyan değerlerinin karşılaştırılması'], 'Ampirik Bayes yönteminde önsel dağılım dışarıdan öznel olarak atanmaz; paralel gruplardaki toplu veriden tahmin edilerek kullanılır.'),
  ('Tekdüze (sabit) bir önsel dağılım kullanıldığında, Maksimum Sonsal (MAP) tahmini matematiksel olarak aşağıdaki klasik tahmin edicilerden hangisiyle bire bir aynı sonucu verir?', 'En çok olabilirlik (MLE) tahmin edicisi', ['Ağırlıklı harmonik ortalama tahmin edicisi', 'Budanmış medyan tahmin edicisi', 'En küçük ki-kare tahmin edicisi'], 'Önsel P(θ) sabit olduğunda P(θ|V) doğrudan olabilirlik P(V|θ) ile orantılı hale gelir; dolayısıyla tepe noktası MLE ile çakışır.'),
  ('Modern Bayesçi istatistikte çok boyutlu ve analitik integrali alınamayan karmaşık sonsal dağılımlardan örneklem çekmek için en yaygın kullanılan hesaplamalı algoritma ailesi hangisidir?', 'Markov Zinciri Monte Carlo (MCMC) yöntemleri', ['Hızlı Fourier dönüşümü süzgeçleri', 'Simplex doğrusal programlama çözücüleri', 'Kabarcık sıralama (bubble sort) ağaçları'], 'Metropolis-Hastings ve Gibbs örneklemesi gibi MCMC algoritmaları, normalleştirme integralini hesaplamadan sonsal dağılımdan örnek üretmeyi sağlar.'),
  ('Pierre-Simon Laplace\'ın ünlü \'Güneşin doğuşu problemi\'nde kullanılan Ardışıklık Kuralı (Rule of Succession), tekdüze Beta(1,1) önseli altında n bağımsız denemenin tamamı başarılı olduğunda (n+1)\'inci denemenin başarılı olma tahminini hangi formülle verir?', '(n + 1) / (n + 2)', ['n / (n + 1)', '(n - 1) / n', 'n / (n + 2)'], 'Beta(1,1) önseline n başarı eklendiğinde sonsal dağılım Beta(n+1, 1) olur; bunun beklenen değeri (n+1) / (n+2) formülüyle bulunur.'),
  ('Hiç tanımadığınız yeni bir basketbolcu serbest atış çizgisine geçiyor. Başarı olasılığına tekdüze Beta(1,1) önseli atadığınızda oyuncu ilk 3 atışının 3\'ünü de sayıya çevirirse, Laplace\'ın ardışıklık kuralına göre 4. atışı sayı yapma sonsal beklenen olasılığı kaçtır?', '4/5', ['3/4', '5/6', '1/1'], 'n = 3 ardışık başarı gözlemlendiğinden Laplace ardışıklık kuralı (3 + 1) / (3 + 2) = 4/5 değerini verir; klasik orandaki gibi %100 gibi aşırı bir tahmine sapmaz.'),
  ('Bir zeytinyağı analiz laboratuvarına gelen numunelerin %85\'i saf sızma zeytinyağı, %15\'i ise tohum yağı karıştırılmış tağşişli üründür. UV soğurma testinin uyarı verme olasılığı tağşişli yağlarda %92, saf sızma yağlarda %4\'tür. Testten uyarı almayan (temiz çıkan) bir numunenin gerçekten saf sızma zeytinyağı olma olasılığı hangi kesre eşittir?', '68/69', ['65/69', '17/18', '85/88'], 'Uyarı vermeme olasılıkları saf yağda 0,96 ve tağşişli yağda 0,08\'dir. Pay = 0,85 × 0,96 = 0,816; Payda = 0,816 + 0,15 × 0,08 = 0,828. Oran = 816/828 = 68/69 bulunur.'),
  ('Kuzey Denizi\'nde kaybolan bir balıkçı teknesinin Doğu bölgesinde olma önsel olasılığı 0,40, Batı bölgesinde olma olasılığı 0,60\'tır. Tekne Doğu bölgesindeyse bir günlük helikopter taramasının tekneyi bulma olasılığı 0,50\'dir. Helikopter Doğu bölgesini bir gün tarayıp tekneyi bulamadığına göre, teknenin Batı bölgesinde olma güncellenmiş olasılığı kaçtır?', '0,75', ['0,60', '0,80', '0,70'], 'Kanıt \'Doğu\'da bulunamama\'dır. P(Bulunamadı|Batı) = 1 (çünkü Batı\'da olan tekne Doğu\'da zaten bulunamaz!), P(Bulunamadı|Doğu) = 0,50. Sonsal P(Batı) = (0,60×1) / (0,60×1 + 0,40×0,50) = 0,60 / 0,80 = 0,75.'),
  ('1968 yılında ABD Donanmasına ait USS Scorpion denizaltısının okyanus tabanındaki enkazını bulmak için uzman tahminlerini ve arama sensörü başarısını birleştirerek Bayesçi arama kuramını tarihe geçiren matematikçi kimdir?', 'John Craven', ['George Box', 'Bradley Efron', 'John Tukey'], 'Dr. John Craven, uzmanların farklı senaryolarından bir önsel olasılık haritası oluşturup başarısız aramalarla haritayı Bayesçi biçimde güncelleyerek enkazı bulmuştur.'),
  ('Bir koşuda yalnızca Rüzgâr, Bora ve Fırtına adlı üç at yarışmıştır; arşiv kaydı silindiği için hangisinin birinci geldiği bilinmemekte ancak geçmiş güçlerine göre birinci gelmiş olma önsel olasılıkları sırasıyla 0,50, 0,30 ve 0,20\'dir. Birinci gelen atın galibiyetlerinin çamurlu pistte gerçekleşmiş olma oranı Rüzgâr\'da 0,10, Bora\'da 0,30, Fırtına\'da 0,50\'dir. Kayıtlarda o günkü yarışın çamurlu pistte koşulduğu doğrulandığına göre birinci gelen atın Fırtına olma olasılığı kaçtır?', '5/12', ['1/5', '1/4', '7/12'], 'Pay = 0,20 × 0,50 = 0,10. Payda = 0,50×0,10 + 0,30×0,30 + 0,20×0,50 = 0,05 + 0,09 + 0,10 = 0,24. Sonsal oran = 0,10 / 0,24 = 5/12\'dir.'),
  ('İki rakip bilimsel kuramdan T1 kuramı çok dar ve kesin bir aralıkta öndeyi yaparken, T2 kuramı neredeyse her sonucu açıklayabilecek kadar geniş ve esnek bir dağılım sunmaktadır. Gözlemlenen veri T1\'in öngördüğü dar aralığa tam düştüğünde Bayes çarpanı neden T1\'i ödüllendirir?', 'T2 olasılık kütlesini çok geniş bir alana yaydığı için gözlemlenen noktadaki olabilirlik yoğunluğu düşük kalır', ['Bayes teoremi her zaman daha fazla parametre içeren karmaşık kuramlara öncelik verir', 'Dar öndeyi yapan kuramların önsel olasılığı otomatik olarak 1 değerine sabitlenir', 'Esnek kuramların normalleştirme integrali sıfıra eşit olduğundan hesap dışı bırakılır'], 'Bu olgu \'Bayesçi Ockham usturası\' olarak bilinir: Aşırı esnek modeller olasılık yoğunluğunu incelttiği için veri dar hedefe düştüğünde keskin model kazanır.'),
  ('Bir müzik yarışmasında jüri üyesi perde arkasından çalınan kemanın Stradivarius (%10 önsel) veya modern atölye yapımı (%90 önsel) olduğunu tahmin edecektir. Uzman kulağın Stradivarius tınısını doğru seçme olasılığı %80, modern kemanı yanlışlıkla Stradivarius sanma olasılığı %20\'dir. Jüri \'Bu bir Stradivarius\' dediğinde kemanın modern yapım çıkma olasılığı kaçtır?', '9/13', ['4/13', '4/5', '7/12'], 'Soruda kemanın MODERN yapım çıkma olasılığı sorulmaktadır! Pay = 0,90 × 0,20 = 0,18. Payda = 0,10 × 0,80 + 0,18 = 0,08 + 0,18 = 0,26. Oran = 18/26 = 9/13.'),
  ('İstatistiksel karar kuramında sonsal dağılımın beklenen değerini (aritmetik ortalamasını) nokta tahmini olarak seçmek, aşağıdaki kayıp fonksiyonlarından hangisini minimize eder?', 'Karesel hata kayıp fonksiyonu', ['Sıfır-bir (tam isabet) kayıp fonksiyonu', 'Mutlak sapma kayıp fonksiyonu', 'Üstel basamak kayıp fonksiyonu'], 'Karesel kayıp E[(θ - â)^2] minimize edildiğinde optimal Bayes tahmin edicisi sonsal ortalama olur (mutlak kayıpta sonsal medyan, 0-1 kayıpta MAP).'),
  ('Sonsal dağılımın medyanını (ortancasını) optimal nokta tahmini yapan Bayesçi kayıp fonksiyonu aşağıdakilerden hangisidir?', 'Mutlak hata kayıp fonksiyonu |θ - â|', ['Karesel hata kayıp fonksiyonu (θ - â)^2', 'Logaritmik olabilirlik kayıp fonksiyonu', 'Ters kuadratik sapma fonksiyonu'], 'Beklenen mutlak hatayı E[|θ - â|] en küçükleyen değer, sonsal dağılımı iki eşit olasılıklı parçaya bölen sonsal medyandır.'),
  ('Jeffreys önseli (Jeffreys prior) parametrenin hangi dönüşüm özelliğini korumak amacıyla Fisher bilgi matrisinin karekökü kullanılarak tanımlanmıştır?', 'Yeniden parametrelendirme (ölçek/fonksiyon dönüşümü) altında değişmezlik', ['Örneklem ortalamasının her zaman tam sayı çıkmasını sağlama', 'Sonsal dağılımın standart sapmasını sıfıra sabitleme', 'Negatif olasılık değerlerine simetrik geçiş izni verme'], 'Tekdüze önsel θ için düzken θ^2 için düz kalmaz; Harold Jeffreys bu tutarsızlığı aşmak için dönüşüm altında değişmez (invariant) önseli geliştirmiştir.'),
  ('Bir biyolog mikroskop altında incelediği hücrenin mutasyonlu olma önsel olasılığını 0,05 olarak biliyor. Floresan boyanın parlaması mutasyonlu hücrelerin %96\'sında, normal hücrelerin %8\'inde gerçekleşiyor. Boyası parlayan bir hücrenin normal (mutasyonsuz) olma olasılığı hangi kesre eşittir?', '19/31', ['12/31', '19/25', '15/31'], 'Normal olma olasılığı sorulmuştur! Pay = 0,95 × 0,08 = 0,076. Payda = 0,05 × 0,96 + 0,076 = 0,048 + 0,076 = 0,124. Oran = 76/124 = 19/31\'dir.'),
  ('Bir fidanlıkta elma fidanlarının aşı tutma oranını modelleyen ziraat mühendisi önsel olarak Beta(2, 2) dağılımını seçiyor. Gözlemlediği 10 fidandan 8\'i aşı tuttuğunda (Binom verisi), eşlenik güncelleme kuralına göre elde edilen sonsal Beta dağılımının parametreleri ne olur?', 'Beta(10, 4)', ['Beta(8, 2)', 'Beta(12, 6)', 'Beta(10, 2)'], 'Beta(α, β) önseline s=8 başarı ve f=2 başarısızlık eklendiğinde sonsal dağılım Beta(α+s, β+f) = Beta(2+8, 2+2) = Beta(10, 4) olur.'),
  ('Bir araştırmacı H hipotezine 0,01 gibi çok düşük bir önsel olasılık atamıştır. Hangi koşul altında tek bir deneysel kanıt bu hipotezin sonsal olasılığını 0,90\'ın üzerine taşıyabilir?', 'Kanıtın H doğruyken gerçekleşme olasılığının, H yanlışken gerçekleşme olasılığından en az 900 kat büyük olması', ['Kanıtın H doğruyken gerçekleşme olasılığının 0,91 değerine ulaşması', 'Alternatif hipotezin önsel olasılığının 0,50\'nin altına çekilmesi', 'Deneydeki toplam katılımcı sayısının 100 kişiyi aşması'], 'Önsel bahis 1:99 iken sonsal bahsin >9:1 olması için Bayes çarpanı L > 9 × 99 = 891 (yaklaşık 900 kat) olmalıdır; \'olağanüstü iddialar olağanüstü kanıt gerektirir\' ilkesinin matematiğidir.'),
  ('ROC eğrisi altındaki alanın (AUC = 0,88) sezgisel olasılıksal anlamı aşağıdakilerden hangisinde en doğru biçimde ifade edilmiştir?', 'Rastgele seçilen bir hasta bireyin test skorunun, rastgele seçilen sağlıklı bir bireyin skorundan yüksek gelme olasılığı %88\'dir', ['Toplumda taranan her 100 kişiden tam 88\'inin kesin olarak hasta çıkacağı garanti altındadır', 'Test sonucu pozitif çıkan bir kişinin gerçekte hasta olma olasılığı her prevalansta %88\'dir', 'Testin duyarlılığı ile özgüllüğünün aritmetik toplamı 0,88 sayısına sabitlenmiştir'], 'AUC istatistiği Mann-Whitney U istatistiğiyle eşdeğerdir ve rastgele bir hasta-sağlam çiftinin doğru sıralanma olasılığını verir.'),
  ('Tanı testlerinde en uygun kesim noktasını (cut-off) seçmek için sıklıkla kullanılan Youden J indeksi nasıl tanımlanır?', 'J = Duyarlılık + Özgüllük - 1', ['J = Duyarlılık × Özgüllük + 1', 'J = (PPV + NPV) / 2', 'J = Duyarlılık / Özgüllük'], 'Youden indeksi ROC eğrisinin şans köşegeninden dikey uzaklığını maksimize eder: Duyarlılık - (1 - Özgüllük) = Duyarlılık + Özgüllük - 1.'),
  ('Klinik pratikte hekimlerin kağıt üzerinde cetvelle \'test öncesi olasılık\' ile \'olabilirlik oranını\' birleştirip \'test sonrası olasılığı\' çarpma-bölme yapmadan doğrudan okumalarını sağlayan grafiksel araca ne ad verilir?', 'Fagan nomogramı', ['Venn kesişim diyagramı', 'Kutu-bıyık (boxplot) çizgesi', 'Pareto birikimli çubuk grafiği'], '1975\'te T. J. Fagan tarafından uyarlanan üç paralel log-bahis ölçekli Fagan nomogramı, Bayes teoremini tek bir doğru çizerek çözer.'),
  ('Yeni bir tanı testi değerlendirilirken yalnızca tarama testi pozitif çıkan hastalara altın standart (örneğin biyopsi) uygulanıp negatif çıkanlara uygulanmaması literatürde hangi sistematik hataya yol açar?', 'Doğrulama yanlılığı (verification / workup bias)', ['Hatırlama yanlılığı (recall bias)', 'Ekoloji yanılgısı (ecological fallacy)', 'Ortalamaya gerileme etkisi'], 'Negatif çıkanlar altın standartla kontrol edilmediğinde yanlış negatifler gizli kalır ve testin duyarlılığı yapay biçimde olduğundan yüksek görünür.'),
  ('Bir tanı testinin duyarlılığı 0,70 ve özgüllüğü 0,30 olarak ölçülmüştür (yani Duyarlılık + Özgüllük = 1,00). Bu test hakkında aşağıdaki çıkarımlardan hangisi doğrudur?', 'Testin pozitif çıkma olasılığı hasta ve sağlıklı bireylerde eşittir (%70); test hiçbir bilgi üretmemektedir', ['Test hastaların %70\'ini yakaladığı için yüksek tanısal değere sahiptir ve klinikte kullanılmalıdır', 'Testin pozitif olabilirlik oranı 2,33 olup hastalık olasılığını iki kattan fazla artırmaktadır', 'Test sonuçları ters çevrilirse (pozitife negatif denirse) mükemmel bir tanı aracı elde edilir'], 'Özgüllük 0,30 ise yanlış pozitif oranı 1 - 0,30 = 0,70\'tir! Yani test hastalara da sağlamlara da %70 pozitif der; LR+ = 0,70/0,70 = 1 olup tamamen bilgisizdir.'),
  ('İlginç bir laboratuvar hatası sonucu bir biyobelirteç testinin duyarlılığı %10, özgüllüğü ise %5 çıkmıştır (ROC eğrisinde şans köşegeninin çok altında, AUC = 0,08). Bu test nasıl anlamlı bir tanı aracına dönüştürülebilir?', 'Testin karar etiketi ters çevrilerek', ['Örneklem büyüklüğü on katına çıkarılıp aynı eşik kuralı korunarak', 'Test yalnızca hastalık prevalansının çok düşük olduğu köylerde uygulanarak', 'Test aynı hastaya hiçbir yorum değişikliği yapılmadan iki kez tekrarlanarak'], 'Duyarlılık 0,10 ve özgüllük 0,05 ise etiketler ters çevrildiğinde yeni duyarlılık 1 - 0,10 = %90, yeni özgüllük 1 - 0,05 = %95 (AUC = 0,92) olur!'),
  ('Precision (PPV) ve Recall (Duyarlılık) değerleri arasındaki dengeyi tek bir sayıda özetlemek için bu iki oranın hangi ortalaması alınarak F1 skoru hesaplanır?', 'Harmonik ortalaması: 2 × (PPV × Duyarlılık) /', ['Aritmetik ortalaması: (PPV + Duyarlılık) / 2', 'Geometrik ortalaması: karekök(PPV × Duyarlılık)', 'Karesel ortalaması: karekök((PPV^2 + Duyarlılık^2) / 2)'], 'Harmonik ortalama uçtaki düşük değere karşı hassastır; örneğin duyarlılık 1 iken PPV 0,01 ise aritmetik ortalama 0,505 yanılsaması yaratırken F1 ≈ 0,02 vererek uyarır.'),
  ('İki farklı tanı testi A ve B aynı anda (paralel bağlanarak) uygulanıyor ve \'Testlerden en az biri pozitif çıkarsa hasta pozitif kabul edilir\' (VEYA kuralı) benimseniyor. Tek başına testlere kıyasla bu birleşik stratejinin net etkisi ne olur?', 'Bileşik duyarlılık artarken bileşik özgüllük azalır', ['Bileşik duyarlılık azalırken bileşik özgüllük artar', 'Hem bileşik duyarlılık hem de bileşik özgüllük eşzamanlı artar', 'Yanlış pozitif olasılığı her iki testin yanlış pozitiflerinin çarpımına düşer'], '\'En az biri pozitif\' (VEYA) kuralı gerçek hastanın iki testten de kaçmasını zorlaştırır (duyarlılık artar) ama sağlam kişinin yanlış pozitif alma şansını büyütür (özgüllük düşer).'),
  ('İki bağımsız tanı testi seri (ardışık VE kuralıyla) uygulanıp yalnızca \'Her iki testten de pozitif çıkanlar pozitif sayılır\' kuralı işletildiğinde sistemin duyarlılık ve özgüllüğü nasıl değişir?', 'Bileşik özgüllük yükselirken bileşik duyarlılık tekil testlerin altına düşer', ['Bileşik duyarlılık yükselirken bileşik özgüllük tekil testlerin altına iner', 'Her iki metrik de iki testin aritmetik ortalamasında dengelenir', 'Yanlış negatif oranı sıfırlanırken yanlış pozitif oranı ikiye katlanır'], 'Seri \'VE\' kuralında sağlam birinin iki testte birden yanlış pozitif çıkması çok zorlaşır (özgüllük artar), ancak hasta biri herhangi birinde kaçarsa elenir (duyarlılık P1×P2\'ye düşer).'),
  ('Birbirinden koşullu bağımsız iki testten birincisinin özgüllüğü 0,90, ikincisinin özgüllüğü 0,80\'dir. Yalnızca her iki testten de pozitif çıkanların pozitif sayıldığı seri (VE) protokolde bileşik özgüllük kaçtır?', '0,98', ['0,72', '0,85', '0,96'], 'Sağlam bir bireyin iki testte birden yanlış pozitif çıkma olasılığı (1 - 0,90)×(1 - 0,80) = 0,10×0,20 = 0,02 olur; dolayısıyla bileşik özgüllük 1 - 0,02 = 0,98\'dir.'),
  ('Sürekli ölçüm veren bir hormon testinde sağlıklı grubun değerleri Ortalama = 50, Standart Sapma = 10; hasta grubun değerleri ise Ortalama = 80, Standart Sapma = 10 olan iki çan eğrisi oluşturuyor. İki eğrinin birbirinden hiç kaydırılmadan standart sapmaları 5\'e düşecek kadar daha hassas bir cihaz kullanılırsa ROC eğrisi nasıl değişir?', 'İki dağılımın örtüşmesi azalacağından ROC eğrisi sol üst köşeye yaklaşır ve AUC alanı büyür', ['Ortalamalar değişmediği için ROC eğrisi ve AUC alanı bire bir aynı kalır', 'Eğri şans köşegenine doğru basıklaşır ve duyarlılık her eşikte düşer', 'Yalnızca özgüllük artarken duyarlılık tüm kesim noktalarında yarıya iner'], 'Gürültü (standart sapma) azaldığında sağlıklı ve hasta dağılımlarının kuyruk örtüşmesi küçülür; hem duyarlılık hem özgüllük iyileşir ve AUC 1\'e yaklaşır.'),
  ('Bir tanı testi yalnızca hastalığın çok ileri evresindeki ağır yatan hastalarla tamamen sağlıklı genç sporcular üzerinde denenerek geliştirildiğinde duyarlılığı %98 ölçülmüştür. Ancak test aile hekimliğinde hafif belirtili hastalarda kullanıldığında duyarlılığın %65\'e düştüğü görülmüştür. Bu olguya ne ad verilir?', 'Spektrum yanlılığı (spectrum bias)', ['Kurucu etkisi (founder effect)', 'Hawthorne gözlemci etkisi', 'Çoklu karşılaştırma yanılgısı'], 'Uç vakalardan oluşan yapay çalışma grubu klinikteki gerçek ara/hafif hasta yelpazesini (spektrumunu) yansıtmadığında test performansı abartılı görünür.'),
  ('Biyometrik doğrulama sistemlerinde Yanlış Kabul Oranı (FAR) ile Yanlış Reddetme Oranının (FRR) birbirine tam eşitlendiği kesişim noktasına ne ad verilir?', 'Eşit hata oranı', ['Maksimum marjinal olabilirlik noktası', 'Harmonik prevalans dengesi', 'Sıfır sapma kuantil eşiği'], 'Biyometrik sensörlerin genel doğruluğunu kıyaslamakta kullanılan EER, FAR = FRR koşulunu sağlayan eşikteki ortak hata yüzdesidir.'),
  ('Duyarlılığı %90 ve özgüllüğü %80 olan birinci test ile duyarlılığı %80 ve özgüllüğü %90 olan ikinci test, hastalık prevalansının tam %50 olduğu bir referans grupta karşılaştırılıyor. İki testin Pozitif Öngörü Değerleri (PPV) arasındaki ilişki nasıldır?', 'İkinci testin PPV değeri (8/9 ≈ %88,9), birinci testin PPV değerinden (9/11 ≈ %81,8) daha yüksektir', ['Birinci testin duyarlılığı daha yüksek olduğu için PPV değeri de ikinci testten daha yüksektir', 'Prevalans tam %50 seçildiğinde iki testin PPV değerleri birbirine tam eşit (%85,0) çıkar', 'Her iki testin de PPV değeri %50 başlangıç taban oranında birbirine eşitlenerek sabit kalır'], 'Prevalans %50 iken PPV = Duyarlılık / (Duyarlılık + 1 - Özgüllük). Birinci testte 0,90 / (0,90 + 0,20) = 9/11 ≈ %81,8; ikinci testte 0,80 / (0,80 + 0,10) = 8/9 ≈ %88,9 bulunur.'),
  ('İki tanı testinin ROC eğrileri orta bölgede birbirini kesiyorsa (örneğin A testi sol tarafta daha dik yükselirken B testi sağ üst tarafta daha yukarı çıkıyorsa) klinik seçim nasıl yapılmalıdır?', 'Yanlış pozitiften kaçınmak kritikse sol bölgede üstün olan A testi, hiçbir vakayı kaçırmamak kritikse sağ üstte üstün olan B testi seçilmelidir', ['Eğrileri kesişen iki testin ikisi de geçersiz sayılmalı ve yazı-tura kuralına dönülmelidir', 'Yalnızca toplam AUC alanına bakılmalı, yanlış pozitif ve yanlış negatif maliyetleri göz ardı edilmelidir', 'Kesim noktasındaki duyarlılık değeri her iki testin de prevalansı olarak atanmalıdır'], 'ROC eğrisinin sol ucu yüksek özgüllük (rule-in) bölgesidir, sağ üst kısmı ise yüksek duyarlılık (rule-out/tarama) bölgesidir; seçim hata maliyetlerine bağlıdır.'),
  ('Bir yapay zekâ mamografi okuma modeli 400 pozitif rapor üretmiş ve biyopsi sonucunda bu 400 raporun 100 tanesinin gerçek tümör, 300 tanesinin ise iyi huylu kireçlenme (yanlış pozitif) olduğu anlaşılmıştır. Yalnızca bu veriden aşağıdaki ölçütlerden hangisi kesin olarak hesaplanabilir?', 'Modelin pozitif öngörü değeri (PPV = %25)', ['Modelin duyarlılığı (sensitivitesi)', 'Modelin özgüllüğü (spesifisitesi)', 'Modelin negatif öngörü değeri (NPV)'], 'Negatif rapor alan hastaların sayısı ve içlerindeki kaçırılan tümörler (FN ve TN) bilinmediğinden duyarlılık, özgüllük ve NPV bulunamaz; ancak PPV = 100/400 = %25 kesin hesaplanır!'),
  ('Bir kredi değerlendirme algoritmasında kredi geri ödemesini aksatacak riskli müşterileri \'pozitif sınıf\' kabul edelim. Banka kredi onay eşiğini çok gevşetip neredeyse her başvurana kredi verdiğinde algoritmanın riskli müşterileri yakalama duyarlılığı ve özgüllüğü ne olur?', 'Riskli müşterileri yakalama duyarlılığı 0\'a yaklaşırken dürüst müşterileri onaylama özgüllüğü 1\'e yaklaşır', ['Riskli müşterileri yakalama duyarlılığı 1\'e yaklaşırken özgüllük 0\'a düşer', 'Hem duyarlılık hem de özgüllük eşzamanlı olarak 0,50 noktasında birleşir', 'Yanlış negatif (batık kredi) sayısı sıfırlanırken yanlış pozitif sayısı tavan yapar'], 'Herkese kredi onaylamak kimseye \'riskli (pozitif)\' dememek demektir! Dolayısıyla riskliler yakalanamaz (duyarlılık → 0, batık kredi FN artar), dürüst kimse de reddedilmez (özgüllük → 1).'),
  ('Klinik tanıda bir testin \'Tanısal Bahis Oranı\' (Diagnostic Odds Ratio - DOR) pozitif olabilirlik oranının negatif olabilirlik oranına bölünmesiyle (LR+ / LR-) tanımlanır. Duyarlılığı 0,90 ve özgüllüğü 0,90 olan bir testin DOR değeri kaçtır?', '81', ['9', '18', '90'], 'LR+ = 0,90 / 0,10 = 9 ve LR- = 0,10 / 0,90 = 1/9\'dur. DOR = LR+ / LR- = 9 / (1/9) = 81 olarak hesaplanır.'),
  ('Sinyal algılama kuramında (Signal Detection Theory) alıcının \'gürültü\' ile \'sinyal + gürültü\' dağılımlarını birbirinden ayırt etme kapasitesini karar eşiğinden bağımsız olarak ölçen standartlaştırılmış ortalamalar farkı hangi sembolle gösterilir?', 'd\' (d-üssü / duyarlılık indeksi)', ['χ² (ki-kare uyum istatistiği)', 'ρ (Spearman sıra korelasyonu)', 'α (Cronbach iç tutarlılık katsayısı)'], 'Psikofizik ve radar kuramında d\' (d-prime), sinyal ve gürültü dağılımlarının ortalamaları arasındaki mesafenin standart sapmaya oranıdır; eşik yanlılığından (β) bağımsızdır.'),
  ('Tıpta aşırı tanı (overdiagnosis) kavramı ile yanlış pozitif (false positive) kavramı arasındaki ince fark aşağıdakilerden hangisidir?', 'Yanlış pozitifte hastalık hiç yokken, aşırı tanıda patolojik lezyon gerçekten vardır ancak kişinin ömrü boyunca hiçbir belirti veya zarara yol açmayacaktır', ['Aşırı tanı yalnızca sağlıklı gençlerde görülürken yanlış pozitif yalnızca ileri yaş grubunda görülür', 'Yanlış pozitif testin duyarlılığıyla ilişkiliyken aşırı tanı yalnızca negatif öngörü değeriyle ilişkilidir', 'İki terim tamamen eş anlamlıdır ve biyopsi sonucu temiz çıkan vakaları anlatmak için kullanılır'], 'Çok hassas taramalar (ör. prostat veya tiroit mikrokarsinomları) biyolojik olarak gerçek fakat hiç ilerlemeyecek sessiz lezyonları yakaladığında aşırı tanı oluşur.'),
  ('Yanlış keşif oranı (False Discovery Rate - FDR), binlerce genin aynı anda tarandığı biyoinformatik çalışmalarda sıkça kullanılır ve P(Gerçekte Etkisiz | Test Pozitif) olarak tanımlanır. FDR metriği tanı testi terimleriyle aşağıdakilerden hangisine eşittir?', '1 - Pozitif Öngörü Değeri (1 - PPV)', ['1 - Duyarlılık (Sensitivite)', '1 - Özgüllük (Spesifisite)', '1 - Negatif Öngörü Değeri (1 - NPV)'], 'Pozitif ilan edilen keşiflerin içinde gerçekte boş (yanlış pozitif) olanların oranı FP / (TP + FP) = 1 - TP / (TP + FP) = 1 - PPV\'dir.'),
  ('Dengesiz sınıflarda ROC eğrisine alternatif olarak çizilen Kesinlik-Duyarlılık (Precision-Recall / PR) eğrisi, hastalık veya olay çok nadir olduğunda neden ROC eğrisinden daha bilgilendirici bulunur?', 'ROC eğrisinde çok büyük olan doğru negatif (TN) sayısı yanlış pozitif artışını maskelerken, PR eğrisi doğrudan PPV üzerinden yanlış pozitif yükünü görünür kılar', ['PR eğrisinin altında kalan alan her zaman 1,00 değerine sabitlenerek hesaplama kolaylığı sağlar', 'ROC eğrisi yalnızca doğrusal modellerde çizilebilirken PR eğrisi doğrusal olmayan ağlarda çizilir', 'PR eğrisi örneklemdeki prevalans değişimlerinden hiçbir şekilde etkilenmez'], 'Milyonda bir görülen olaylarda 1000 yanlış pozitif bile (1-Özgüllük) oranını 0,001 tutar ve ROC mükemmel görünür; oysa PPV çakılır ve PR eğrisi bu sorunu anında gösterir.'),
  ('Bir klinik çalışmada yeni bir ultrason tekniği ile biyopsi sonuçları karşılaştırılmış ve ultrasonun duyarlılığı %82 (%95 güven aralığı: %76 - %88) olarak raporlanmıştır. Güven aralığının genişliğini daraltıp duyarlılığı daha hassas tahmin etmek için araştırmacı ne yapmalıdır?', 'Çalışmaya dahil edilen biyopsi ile doğrulanmış gerçek hasta sayısını artırmalıdır', ['Çalışmaya yalnızca daha fazla sağlıklı kontrol gönüllüsü eklemelidir', 'Ultrason cihazının kesim noktasını sıfıra çekerek herkesi pozitif saymalıdır', 'Güven düzeyini %95\'ten %99,9\'a yükselterek aralığı yeniden hesaplamalıdır'], 'Duyarlılık paydasında yalnızca gerçek hastalar (TP + FN) bulunur; sağlıklı kontrol eklemek özgüllüğün güven aralığını daraltır, duyarlılığınkini daraltmak için hasta sayısı artmalıdır!'),
  ('Duyarlılığı %88 ve özgüllüğü %88 olan simetrik bir tanı testinde, hangi prevalans değerinde Genel Doğruluk (Accuracy) prevalanstan etkilenmeksizin tam %88 çıkar?', '0 ile 1 arasındaki tüm prevalans değerlerinde', ['Yalnızca prevalansın %50 olduğu dengeli durumda', 'Yalnızca prevalansın %12 olduğu özel noktada', 'Yalnızca prevalansın %88 olduğu yüksek risk grubunda'], 'Accuracy = p×0,88 + (1-p)×0,88 = 0,88×(p + 1 - p) = 0,88! Duyarlılık ve özgüllük birbirine eşit olduğunda genel doğruluk prevalanstan tamamen bağımsız sabit kalır.'),
  ('Bir solunum fonksiyon testinde astım tanısı için FEV1/FVC oranı kesim noktası %70 yerine %75 olarak alınırsa (yani oranın %75\'in altında çıkması pozitif kabul edilirse) ne olur?', 'Pozitif sayılma bölgesi genişlediği için duyarlılık yükselir, ancak sağlıklı yaşlı bireylerde yanlış pozitiflik artar', ['Pozitif sayılma bölgesi daraldığı için duyarlılık düşer ve özgüllük %100 olur', 'Hem gençlerde hem yaşlılarda yanlış pozitif ve yanlış negatif oranları sıfırlanır', 'Testin negatif olabilirlik oranı sonsuza giderek tanısal değerini yitirir'], 'Düşük oran hastalık göstergesi olduğundan üst sınırı %70\'ten %75\'e çıkarmak pozitif bölgeyi genişletir; daha çok hasta yakalanır (duyarlılık artar) ama özgüllük düşer.'),
  ('Kahneman ve Tversky\'nin taksi deneyinin değiştirilmiş ikinci sürümünde katılımcılara \'Şehirdeki taksi şirketlerinin büyüklüğü farklı olsa da şehirdeki taksi kazalarının %85\'ine yeşil, %15\'ine mavi taksiler karışmaktadır\' denildiğinde insanların Bayesçi tahmine çok daha fazla yaklaştığı görülmüştür. Bunun temel bilişsel nedeni nedir?', 'Temel oranın olayla doğrudan nedensel bir bağ kuracak biçimde sunulması', ['Tanığın doğru görme yüzdesinin ikinci deneyde ortadan kaldırılması', 'Katılımcılara hesap makinesi ve logaritma cetveli dağıtılmış olması', 'Yeşil ve mavi taksi oranlarının birbirine tam eşit hale getirilmesi'], 'İnsan zihni soyut istatistiksel taban oranlarını ihmal etmeye eğilimliyken, kaza eğilimi gibi nedensel şemaya oturan temel oranları hesaba katar.'),
  ('Bir spor federasyonu doping kullanım sıklığının %2 olduğu bir branşta rutin tarama yapmaktadır. İlk idrar testinin duyarlılığı %95, özgüllüğü %95\'tir. İlk testi pozitif çıkan bir sporcuya, ilk testten koşullu bağımsız çalışan ve duyarlılığı %90, özgüllüğü %99 olan kütle spektrometresi doğrulama testi uygulanıyor ve o da pozitif çıkıyor. İki pozitif sonuçtan sonra sporcunun gerçekten dopingli olma olasılığı kaçtır?', '1710/1759 (yaklaşık %97,2)', ['19/68 (yaklaşık %27,9)', '855/904 (yaklaşık %94,6)', '171/220 (yaklaşık %77,7)'], '10.000 sporcudan 200\'ü dopingli: iki testi de geçen 200×0,95×0,90 = 171 kişi. 9.800 temiz sporcu: ikide iki yanlış pozitif alan 9800×0,05×0,01 = 4,9 kişi. Sonsal olasılık = 171 / (171 + 4,9) = 1710/1759 ≈ %97,2 olur.'),
  ('Hastalık prevalansının %10 olduğu bir popülasyonda bir hastaya duyarlılığı %90 ve özgüllüğü %90 olan ilk test uygulanıyor ve sonuç POZİTİF çıkıyor. Hemen ardından aynı duyarlılık (%90) ve özgüllüğe (%90) sahip koşullu bağımsız ikinci bir test yapılıyor ve bu kez sonuç NEGATİF çıkıyor. İki testin ardından hastanın bu hastalığı taşıma sonsal olasılığı yüzde kaç olur?', '%10', ['%50', '%19', '%45'], 'İlk testin LR+ değeri 0,90/0,10 = 9 iken ikinci testin LR- değeri 0,10/0,90 = 1/9\'dur. Net çarpan 9 × (1/9) = 1 olduğundan olasılık başlangıçtaki %10 temel oranına geri döner.'),
  ('Hatasız çalışan bir PCR testiyle, enfeksiyon sıklığının bağımsız olarak %10 olduğu bir grupta ikişer kişilik havuzlama (Dorfman yöntemi) uygulanıyor: İki kişinin sürüntüsü birleştirilip 1 test yapılıyor; sonuç negatifse ikisi de temiz sayılıyor, pozitifse her ikisine ayrı ayrı 1\'er test daha (toplam 3 test) yapılıyor. İki kişilik bir çift için beklenen toplam test sayısı kaçtır?', '1,38', ['1,20', '1,50', '1,81'], 'İkisinin de sağlam çıkma olasılığı 0,90 × 0,90 = 0,81 (1 test harcanır). En az birinin hasta çıkma olasılığı 1 - 0,81 = 0,19 (3 test harcanır). Beklenen test = 0,81×1 + 0,19×3 = 1,38\'dir.'),
  ('Enfeksiyon sıklığının %50 olduğu çok yoğun bir salgın odağında, hatasız bir testle ikişer kişilik Dorfman havuzlaması yapılırsa (havuz negatifse toplam 1 test, pozitifse toplam 3 test) iki kişi için beklenen test sayısı bireysel taramaya (2 test) kıyasla ne olur?', '2,50 teste çıkarak bireysel taramadan daha maliyetli hale gelir', ['1,50 teste inerek %25 oranında kit tasarrufu sağlar', '2,00 test düzeyinde kalarak bireysel taramayla başa baş gelir', '1,75 teste gerileyerek laboratuvar iş yükünü hafifletir'], 'İkisinin de negatif çıkma olasılığı 0,50 × 0,50 = 0,25\'tir. Beklenen test sayısı = 0,25×1 + 0,75×3 = 0,25 + 2,25 = 2,50 olur; yüksek prevalansta havuzlama zarar ettirir!'),
  ('Bir kentte yetişkinlerin %80\'i grip aşısı yaptırmış, %20\'si yaptırmamıştır. Kış boyu grip nedeniyle yoğun bakıma yatan hastaların %50\'sinin aşılı, %50\'sinin aşısız olduğu açıklanmıştır. \'Yatanların yarısı aşılı olduğuna göre aşı hiç korumuyor\' diyen bir yorumcu temel oran yanılgısına düşmektedir; gerçekte aşısız bir bireyin yoğun bakıma yatma olasılığı aşılı bir bireyinkinin kaç katıdır?', '4 katı', ['2 katı', 'Eşit', '8 katı'], 'Nüfusun %20\'sini oluşturan aşısızlar vakaların %50\'sini üretirken, 4 kat kalabalık (%80) aşılı grup da %50 üretmiştir: Göreli risk = (0,50/0,20) / (0,50/0,80) = 2,5 / 0,625 = 4 kat!'),
  ('İngiltere\'de 1999 yılındaki ünlü Sally Clark davasında, iki bebeğini ani bebek ölümü sendromuyla kaybeden bir annenin yargılanması sırasında bilirkişi \'Tek bir bebeğin doğal ölüm olasılığı 1/8500 ise ikisinin ölümü (1/8500)² = 73 milyonda birdir, demek ki anne suçludur\' demiştir. Kraliyet İstatistik Derneği bu ifadeyi hangi iki ağır hata nedeniyle kınamıştır?', 'Genetik/çevresel bağımlılığı yok sayma ve çifte cinayet temel oranıyla kıyaslamadan savcı yanılgısına düşme', ['Olasılıkları toplamak yerine çıkarma ve örneklem medyanını yanlış hesaplama', 'Yalnızca hastanede doğan bebekleri sayma ve ROC eğrisini ters çizme', 'Güven aralığını %95 yerine %99 alma ve serbestlik derecesini düşürme'], 'Aynı ailede ikinci doğal ölüm birinciden bağımsız değildir; üstelik 73 milyonda bir rakamı masumiyet olasılığı değil P(Kanıt|Masum) değeridir ve çifte cinayet de aşırı nadirdir.'),
  ('Hans Reichenbach ve John Venn\'in tartıştığı \'Referans Sınıfı Problemi\', bir birey için önsel temel oran belirlerken hangi temel ikilemi ifade eder?', 'Referans grubu daraltıldıkça bireye uygunluk artarken, gruptaki gözlem sayısı azaldığı için oran tahmininin güvenilirliğinin düşmesi', ['Referans grubu genişletildikçe örneklem hacminin küçülmesi ve aritmetik ortalamanın tanımsızlaşması', 'Her bireyin aynı anda yalnızca tek bir evrensel kümeye üye olabilmesi yüzünden alt küme kurulamaması', 'Temel oranın yalnızca geçmiş yüzyıllardaki nüfus sayımlarından alınabilmesi zorunluluğu'], '\'Tüm 40 yaşındakiler\' çok geniş ama kabadır; \'Aynı mahallede yaşayan solak 40 yaşındaki koşucular\' çok özel ama birkaç kişiden oluştuğu için istatistiksel gürültüsü yüksektir.'),
  ('Joseph Berkson\'ın 1946\'da gösterdiği \'Berkson Yanılgısı\'nda, genel toplumda birbirinden tamamen bağımsız olan iki hastalık (örneğin kolesistit ve diyabet), yalnızca hastanede yatan hastalar incelendiğinde neden aralarında yapay bir negatif ilişki varmış gibi görünür?', 'İki hastalıktan en az birine sahip olmak yatış olasılığını artırdığından, \'hastanede yatma\' ortak sonucuna koşullandırma yapılması', ['Hastanede yatan hastaların tamamına yanlış pozitif tanı konmuş olması', 'Genel toplumdaki hastalık prevalanslarının toplamının birden büyük çıkması', 'İki hastalığın aynı bakteri türünden kaynaklanan tek bir enfeksiyon olması'], 'Çarpıştırıcı (collider) değişkene yani \'hastanede yatmaya\' koşullandırdığınızda, diyabeti olmayan bir yatan hastanın orada bulunmak için diğer hastalığa sahip olma olasılığı yüksek çıkar.'),
  ('Gerçekte kusursuz (%100 duyarlı, %100 özgül) olan yeni bir moleküler test, duyarlılığı %80 ve özgüllüğü %100 olan eski bir kültür yöntemi \'altın standart\' kabul edilerek sınanıyor. Eski yöntemin kaçırdığı %20\'lik gerçek hastaları yeni test pozitif bulduğunda naif değerlendirme tablosunda hangi yanılsama oluşur?', 'Yeni testin yakaladığı ek gerçek hastalar \'yanlış pozitif\' sanılır ve yeni testin özgüllüğü olduğundan düşük görünür', ['Yeni testin duyarlılığı sıfır olarak hesaplanır ve tüm hastalar sağlam görünür', 'Eski kültür yönteminin negatif öngörü değeri %100 düzeyine yükselir', 'Her iki testin ROC eğrileri tam köşegen üzerinde çakışır'], '\'Bakır standart\' (kusurlu referans) yanılsamasında, referanstan daha üstün olan yeni testin doğru pozitifleri hatalı biçimde yanlış pozitif hanesine yazılır.'),
  ('Negatif olmayan tam sayı değerler alan bir X rastgele değişkeni için kuyruk toplamı formülü E[X] = P(X >= 1) + P(X >= 2) + P(X >= 3) + ... şeklindedir. Kiralanan bir iş makinesi en fazla 3 gün arızasız çalışabilmekte; en az 1 gün çalışma olasılığı 0,92, en az 2 gün çalışma olasılığı 0,65 ve tam 3 gün çalışma olasılığı 0,28 olduğuna göre beklenen çalışma süresi kaç gündür?', '1,85 gün', ['1,62 gün', '2,05 gün', '1,45 gün'], 'Kuyruk olasılıkları doğrudan verildiğinden E[X] = P(X>=1) + P(X>=2) + P(X>=3) = 0,92 + 0,65 + 0,28 = 1,85 gün olarak tek adımda bulunur.'),
  ('Bir batarya üreticisi, bataryanın 24 aydan önce bozulması halinde müşteriye \'kalan ay oranında kıstelyevm (orantılı) para iadesi\' garantisi vermektedir: 24.000 TL\'ye satılan batarya t\'nci ayda bozulursa 24.000 × (24 - t)/24 TL iade edilir. Bataryanın 6. ayda bozulma olasılığı %5, 18. ayda bozulma olasılığı %10 ve 24 ayı sağlam tamamlama olasılığı %85 ise üreticinin beklenen garanti iadesi kaç TL\'dir?', '1.500 TL', ['1.800 TL', '2.100 TL', '1.200 TL'], '6. ayda iade = 24.000×(18/24) = 18.000 TL; 18. ayda iade = 24.000×(6/24) = 6.000 TL. Beklenen iade = 0,05×18.000 + 0,10×6.000 = 900 + 600 = 1.500 TL.'),
  ('Fazla rezervasyon kararında kapasite üzerindeki son ek koltuğu satmanın marjinal olarak kârlı olmaya devam etmesi için, ek bilet gelirinin (B) ve yolcuyu uçağa alamama tazminatının (T) \'tüm koltukların dolup taşma olasılığı\' (P_taşma) ile ilişkisi hangi eşitsizliği sağlamalıdır?', 'P_taşma < B / T', ['P_taşma > B / T', 'P_taşma = 1 -', 'P_taşma > T /'], 'Ek bilet geliri B, beklenen tazminat P_taşma × T değerinden büyük olduğu sürece (B > P_taşma × T, yani P_taşma < B / T) bir koltuk daha fazla satmak beklenen geliri artırır.'),
  ('Gazeteci çocuk stok modelinde birim \'eksik stok (yok satma) maliyeti\' Cu ve birim \'fazla stok (elde kalma) maliyeti\' Co bilindiğinde, beklenen kârı maksimize eden sipariş miktarı Q* talep dağılımının hangi kritik oranına (birikimli olasılık değerine) karşılık gelir?', 'Cu / (Cu + Co)', ['Co / (Cu + Co)', 'Cu / Co', '(Cu - Co) / (Cu + Co)'], 'Marjinal analizde F(Q*) = Cu / (Cu + Co) kritik kesri (critical fractile) optimal stok düzeyini verir; yok satma kaybı Cu büyüdükçe daha yüksek stok tutulur.'),
  ('Bir pastane sabahları tanesini 40 TL\'ye mal ettiği özel kruvasanları 100 TL\'ye satmaktadır; akşam satılamayıp kalan kruvasanlar ise bayatladığı için yerel bir barınağa tanesi 10 TL\'den devredilmektedir. Gazeteci çocuk modeline göre bu pastanenin birim eksik stok maliyeti (Cu), birim fazla stok maliyeti (Co) ve kritik oranı sırasıyla nedir?', 'Cu = 60 TL, Co = 30 TL, kritik oran = 2/3', ['Cu = 100 TL, Co = 40 TL, kritik oran = 5/7', 'Cu = 60 TL, Co = 40 TL, kritik oran = 3/5', 'Cu = 50 TL, Co = 30 TL, kritik oran = 5/8'], 'Kaçırılan birim kâr Cu = 100 - 40 = 60 TL\'dir. Elde kalan birim zarar Co = 40 - 10 = 30 TL\'dir. Kritik oran = 60 / (60 + 30) = 60/90 = 2/3 bulunur.'),
  ('Buketini 200 TL\'ye alıp 500 TL\'ye satan ve akşam kalan buketleri sıfır hurda değeriyle çöpe atan bir çiçekçinin günlük talebi %30 olasılıkla 40, %50 olasılıkla 50 ve %20 olasılıkla 60 bukettir. Çiçekçi sabah siparişini 50 buketten 60 bukete çıkarırsa beklenen net kârı nasıl değişir?', '1.000 TL azalarak 12.500 TL\'ye düşer', ['1.000 TL artarak 14.500 TL\'ye yükselir', 'Hiç değişmeyerek 13.500 TL düzeyinde kalır', '600 TL artarak 14.100 TL\'ye yükselir'], '50 bukette beklenen kâr 13.500 TL\'dir. 60 bukette maliyet 12.000 TL, beklenen satış geliri 0,30×20.000 + 0,50×25.000 + 0,20×30.000 = 24.500 TL ve net kâr 12.500 TL olur; yani 1.000 TL azalır.'),
  ('Karar kuramında \'Beklenen Parasal Değer\' (EMV) maksimizasyonu ile \'Beklenen Fırsat Kaybı\' (EOL) minimizasyonu ölçütleri aynı problemdeki eylem alternatiflerine uygulandığında hangi sonuç ortaya çıkar?', 'Her zaman bire bir aynı optimal eylemi seçerler ve en düşük EOL değeri tam olarak EVPI\'ye eşittir', ['Riskli dönemlerde birbirine zıt eylemler seçerler ve toplamları sıfıra eşitlenir', 'EOL ölçütü olasılıkları kullanmadığı için yalnızca kötümser alternatifleri işaret eder', 'En düşük EOL değeri her zaman en yüksek EMV değerinin iki katına karşılık gelir'], 'Matematiksel özdeşlik gereği her alternatif i için EMV(i) + EOL(i) = EVwPI sabittir; dolayısıyla EMV\'yi maksimize eden seçenek EOL\'yi minimize eder ve min(EOL) = EVPI olur.'),
  ('Bir ilaç firması Faz-1 denemesine 2 milyon dolar harcayacaktır. Faz-1\'i geçme olasılığı %50\'dir; geçemezse proje biter. Faz-1 geçilirse firma isterse projeyi başka bir şirkete 6 milyon dolara satabilir, isterse 5 milyon dolar daha harcayarak Faz-2\'ye girebilir (Faz-2\'de %60 olasılıkla 20 milyon dolar gelir, %40 olasılıkla 0 dolar). Geriye katlama ile projenin başlangıçtaki beklenen net değeri kaç milyon dolardır?', '1,5 milyon dolar', ['1,0 milyon dolar', '2,5 milyon dolar', '0,5 milyon dolar'], 'Faz-1 geçildiğinde karar düğümü: Satış = +6M; Faz-2\'ye devam = 0,60×20 - 5 = +7M. Optimal seçim 7M ile Faz-2\'ye devamdır! Başlangıçta: %50×7M + %50×0 - 2M (Faz-1 maliyeti) = 3,5 - 2 = 1,5 milyon dolar.'),
  ('Savage\'ın Minimax Pişmanlık kuralına yöneltilen en ünlü kuramsal eleştiri, karar kümesine hiç seçilmeyecek yeni bir dördüncü alternatif eklendiğinde mevcut A ve B arasındaki tercih sırasının tersine dönebilmesidir. Bu durum hangi rasyonellik aksiyomunun ihlalidir?', 'İlgisiz alternatiflerin bağımsızlığı aksiyomu', ['Tam geçişlilik ve süreklilik aksiyomu', 'Toplam olasılıkların birliği aksiyomu', 'Monoton artan doğrusal getiri aksiyomu'], 'Yeni eklenen seçenek sütun maksimumunu değiştirdiğinde pişmanlık farkları kayabilir ve A > B iken B > A çıkabilir; bu da İlgisiz Alternatiflerin Bağımsızlığı (IIA) aksiyomunu bozar.'),
  ('İçbükey (konkav) bir fayda fonksiyonuna sahip riskten kaçınan bireyler için geçerli olan ve \'faydanın beklenen değeri, beklenen servetin faydasından küçüktür\' (E[u(W)] < u(E[W])) biçiminde yazılan temel matematiksel eşitsizliğin adı nedir?', 'Jensen eşitsizliği', ['Markov kuyruk eşitsizliği', 'Cauchy-Schwarz çarpım eşitsizliği', 'Minkowski üçgen eşitsizliği'], 'Jensen eşitsizliği gereği içbükey bir fonksiyonda kiriş her zaman yayın altında kalır; dolayısıyla riskli oyunun beklenen faydası E[u(W)], kesin E[W] tutarının faydasından düşüktür.'),
  ('Von Neumann-Morgenstern beklenen fayda kuramında bir bireyin u(x) fayda fonksiyonuna pozitif doğrusal (afin) bir dönüşüm uygulandığında, yani v(x) = a × u(x) + b (a > 0) tanımlandığında bireyin riskli seçenekler arasındaki tercih sıralaması nasıl değişir?', 'Tercih sıralaması ve kesinlik eşdeğeri hiçbir şekilde değişmez', ['Riskten kaçınan birey b sabiti negatifse risk seven bireye dönüşür', 'Kesinlik eşdeğeri a katına çıkarken risk primi b kadar artar', 'Tüm şans düğümlerindeki olasılıklar a katsayısıyla çarpılır'], 'vNM faydası aralık ölçeğindedir (Sıcaklığın Celsius\'tan Fahrenheit\'a çevrilmesi gibi); a > 0 olmak üzere doğrusal dönüşüm altında beklenen fayda eşitsizlikleri korunur.'),
  ('Kenneth Arrow ve John Pratt tarafından tanımlanan \'Mutlak Riskten Kaçınma Katsayısı\' A(W), türevlenebilir bir u(W) servet fayda fonksiyonu için hangi formülle hesaplanır?', 'A(W) = - u\'\'(W) / u\'(W)', ['A(W) = u\'(W) / u\'\'(W)', 'A(W) = - W × u\'(W) / u(W)', 'A(W) = [u\'(W)]^2 - u\'\'(W)'], 'Eğriliğin eğime oranı olan -u\'\'(W)/u\'(W), pozitif doğrusal dönüşümlerden etkilenmeyen yerel mutlak riskten kaçınma ölçütüdür.'),
  ('Üstel fayda fonksiyonu u(W) = 1 - e^(-cW) (c > 0) kullanan bir karar vericinin serveti 1 milyon TL\'den 10 milyon TL\'ye çıktığında aynı parasal büyüklükteki bir riske karşı \'Kesinlik Eşdeğeri\' nasıl davranır?', 'Sabit mutlak riskten kaçınma (CARA) özelliği nedeniyle hiç değişmez', ['Servet on katına çıktığı için kesinlik eşdeğeri de on katına yükselir', 'Servet arttıkça birey tamamen risk seven hale geçer', 'Kesinlik eşdeğeri sıfıra doğru üstel biçimde azalır'], 'Üstel faydada A(W) = -u\'\'/u\' = c sabittir (Constant Absolute Risk Aversion); başlangıç servet düzeyi karar ağacındaki risk primini değiştirmez.'),
  ('Gerçek hayatta insanların serveti arttıkça sabit 10.000 TL\'lik bir kumardan kaçınma derecelerinin azalması (örneğin logaritmik fayda u(W) = ln(W) için A(W) = 1/W olması) hangi risk özelliğiyle açıklanır?', 'Azalan mutlak riskten kaçınma (DARA)', ['Artan mutlak riskten kaçınma (IARA)', 'Sabit mutlak riskten kaçınma (CARA)', 'Doğrusal riske duyarsızlık (RN)'], 'ln(W) fonksiyonunda u\' = 1/W ve u\'\' = -1/W^2 olduğundan A(W) = 1/W servet büyüdükçe küçülür; zenginleştikçe sabit tutarlı riskler daha kolay üstlenilir.'),
  ('Kazanıldığında yatırılan tutarın net 2 katını kazandıran (b = 2), kaybedildiğinde yatırılan tutarın tamamını kaybettiren bir oyunda kazanma olasılığı p = 0,50 ve kaybetme olasılığı q = 0,50\'dir. Genel Kelly formülü f* = (b×p - q) / b uyarınca her turda kasanın hangi kesri yatırılmalıdır?', '1/4 (%25)', ['1/2 (%50)', '1/3 (%33,3)', '1/8 (%12,5)'], 'f* = (2 × 0,50 - 0,50) / 2 = (1,00 - 0,50) / 2 = 0,50 / 2 = 1/4 (%25) olarak bulunur.'),
  ('Tekrarlanan çarpımsal bir yatırım oyununda her turda mevcut kasanın %50 olasılıkla %60 arttığı (×1,60), %50 olasılıkla ise %50 eridiği (×0,50) biliniyor. Tek turdaki aritmetik beklenen getiri +%5 (+0,05) olduğu halde çok sayıda tur boyunca oynayan bir yatırımcının servetine uzun dönemde ne olur?', 'Geometrik çarpan karekök(1,60 × 0,50) = karekök(0,80) < 1 olduğundan servet 0\'a doğru erir', ['Aritmetik beklenti +%5 olduğu için servet her 20 turda bir kesinlikle ikiye katlanır', 'Kazanç ve kayıp turları birbirini dengeleyerek başlangıç serveti sabit kalır', 'Standart sapma sıfıra yakınsadığı için servet 1,05^n hızıyla büyür'], 'Çarpımsal süreçlerde ergodik olmayan davranış görülür: 1 kazanç ve 1 kayıp sonunda servet 1,60 × 0,50 = 0,80 (%20 kayıp!) olur; aritmetik ortalama pozitifken tipik yörünge sıfıra çöker.'),
  ('Fransız iktisatçı Maurice Allais\'nin 1953\'te ortaya koyduğu \'Allais Paradoksu\', insanların %100 kesinlik içeren seçeneklere orantısız ağırlık vermesi (kesinlik etkisi) nedeniyle Beklenen Fayda Kuramının hangi temel aksiyomunu ihlal ettiklerini göstermiştir?', 'Bağımsızlık (ortak sonuçların elenmesi) aksiyomu', ['Tam sıralanabilirlik aksiyomu', 'Geçişlilik (A > B ve B > C ise A > C) aksiyomu', 'Arşimet sonluluk aksiyomu'], 'Her iki tercihe de ortak bir olasılık dalı eklendiğinde veya çıkarıldığında insanların tercih yönünü değiştirmesi von Neumann-Morgenstern bağımsızlık aksiyomuna aykırıdır.'),
  ('İstatistiksel karar kuramında iki hipotez arasında (H0: sağlam ürün, H1: kusurlu ürün) karar verilirken H0 gerçekte doğruyken reddedilmesi maliyeti C10 (yanlış alarm) ve H1 doğruyken kaçırılması maliyeti C01 (kaçırma) olsun; doğru kararların maliyeti 0\'dır. Beklenen Bayes riskini en küçükleyen karar kuralı H1 hipotezini ne zaman seçer?', 'Sonsal olasılık P(H1 | Veri) > C10 / (C10 + C01) eşiğini aştığında', ['Sonsal olasılık P(H1 | Veri) > 0,50 sabit eşiğini aştığında', 'Sonsal olasılık P(H1 | Veri) > C01 / (C10 + C01) eşiğini aştığında', 'Önsel olasılık P(H0) değeri C01 maliyetinden büyük olduğunda'], 'H1 seçmenin beklenen zararı P(H0|V)×C10, H0 seçmenin beklenen zararı P(H1|V)×C01\'dir. (1-p)×C10 < p×C01 eşitsizliği çözüldüğünde optimal eşik p* = C10 / (C10 + C01) bulunur!'),
  ('Stephen Pauker ve Jerome Kassirer\'in 1975\'te klinik karar analizine kazandırdığı \'Tedavi Eşiği Olasılığı\' (p_eşik) modelinde; sağlam bir kişiye gereksiz tedavi vermenin net zararı Z, gerçek bir hastayı tedavi etmenin sağladığı net yarar Y ise, tanı testi olmaksızın doğrudan tedaviye başlamak için hastalık olasılığı p hangi koşulu sağlamalıdır?', 'p > Z / (Y + Z)', ['p > Y / (Y + Z)', 'p > Z / Y', 'p > (Y - Z) / Y'], 'Tedavi etmenin beklenen değeri p×Y - (1-p)×Z, tedavi etmemenin (0) değerini aştığında p×Y > (1-p)×Z => p > Z / (Y + Z) tedavi eşiği elde edilir.'),
  ('Bir tanı testinin hem kendisinin ciddi bir girişimsel riski veya maliyeti varsa hem de duyarlılık/özgüllüğü düşükse, Pauker-Kassirer modelindeki \'test yapma bölgesi\' (p_alt ile p_üst arasındaki aralık) nasıl değişir?', 'Aralık daralır; hatta testin maliyeti/riski bilgisinden büyükse tamamen kapanır', ['Aralık [0, 1] aralığının tamamını kaplayacak biçimde genişler', 'Yalnızca üst eşik 1,00\'e sabitlenirken alt eşik 0\'a iner', 'Testin maliyeti karar eşiklerini hiçbir şekilde etkilemez'], 'Testin zararı/maliyeti EVSI değerini aştığında p_alt >= p_üst olur ve test kuşağı ortadan kalkar; doğrudan klinik olasılığa göre tedavi veya izlem seçilir.'),
  ('Kanser tarama programlarının başarısını değerlendirirken, tarama sayesinde hastalığın biyolojik seyri veya ölüm yaşı hiç değişmediği halde yalnızca tanının 3 yıl daha erken konması yüzünden \'tanı sonrası 5 yıllık sağkalım oranının\' yapay olarak yüksek görünmesi hangi yanlılıktır?', 'Kurşun zaman yanlılığı', ['Berkson hastane seçilim yanlılığı', 'Doğrulama (workup) yanlılığı', 'Gözlemci beklenti yanlılığı'], 'Örneğin hasta yine 65 yaşında vefat etse bile tanı 63 yerine 58 yaşında konduğunda tanıdan itibaren yaşam süresi 2 yıldan 7 yıla çıkmış görünür; buna kurşun zaman (erken tanı saati) yanlılığı denir.'),
  ('Düzenli aralıklarla yapılan toplum taramalarının, çok hızlı ilerleyip iki tarama arasında belirti veren saldırgan tümörlerden ziyade yavaş büyüyen ve klinik öncesi evresi uzun süren iyi huylu seyirli tümörleri daha yüksek olasılıkla yakalaması hangi epidemiyolojik yanlılığı doğurur?', 'Süre uzunluğu yanlılığı', ['Ekolojik kümeleme yanılgısı', 'Neyman kesitsel örneklem hatası', 'Hawthorne davranış değişikliği'], 'Yavaş ilerleyen tümörler tarama penceresinde daha uzun süre kaldığından taramayla yakalanan vakalar doğal olarak daha iyi prognozludur; bu durum taramanın yararını abartılı gösterebilir.'),
  ('Kanser tarama programlarında kurşun zaman yanlılığı ve aşırı tanı yanılsamalarına düşmeden taramanın gerçekten hayat kurtarıp kurtarmadığını kanıtlayan en güvenilir birincil sonlanım ölçütü hangisidir?', 'Rastgeleleştirilmiş tarama ve kontrol grupları arasındaki hastalığa özgü ve genel ölüm hızı', ['Tanı konan hastaların tanı tarihinden itibaren ölçülen 5 yıllık sağkalım yüzdesi', 'Tarama yapılan grupta erken evrede yakalanan tümör sayısının toplam tümörlere oranı', 'Tarama testinin laboratuvar ortamındaki pozitif olabilirlik oranı'], '5 yıllık sağkalım (survival) erken tanı saatiyle şişebilir; gerçek yarar ancak taranan grupta birim nüfus başına ölümlerin (mortality) kontrol grubuna göre azalmasıyla kanıtlanır.'),
  ('Bir tanı testinin genel ayırt ediciliğini tek bir oranda birleştiren \'Tanısal Bahis Oranı\' (Diagnostic Odds Ratio - DOR), pozitif ve negatif olabilirlik oranları cinsinden nasıl hesaplanır?', 'DOR = LR+ / LR-', ['DOR = LR+ × LR-', 'DOR = LR+ + LR-', 'DOR = (LR+ - 1) /'], 'DOR = [TP / FN] / [FP / TN] = [Duyarlılık / (1 - Duyarlılık)] / [(1 - Özgüllük) / Özgüllük] = LR+ / LR- formülüyle bulunur ve prevalanstan bağımsızdır.'),
  ('Kusurlu bir tarama testi (Duyarlılık = Se, Özgüllük = Sp) ile bir toplumdan n kişi tarandığında pozitif çıkanların oranı \'görünür prevalans\' p_görünür olarak ölçülmüştür. Rogan-Gladen tahmin edicisine göre gerçek prevalans p nasıl düzeltilir?', 'p = (p_görünür + Sp - 1) / (Se + Sp - 1)', ['p = p_görünür × Se / Sp', 'p = (p_görünür - Se) / (1 - Sp)', 'p = p_görünür × (Se + Sp - 1)'], 'p_görünür = p×Se + (1-p)×(1-Sp) = 1 - Sp + p×(Se + Sp - 1) denklemi p için çözüldüğünde klasik Rogan-Gladen formülü (p_görünür + Sp - 1) / (Se + Sp - 1) bulunur!'),
  ('Nadir bir hastalığın tarandığı klinikte iki gözlemci filmlerin %95\'ine \'normal\' dediğinde gözlenen ham uyum %92 kadar yüksek çıkmasına rağmen Cohen\'in kappa katsayısının 0,20 gibi düşük hesaplanması literatürde nasıl açıklanır?', 'Marjinal dağılım çok dengesiz olduğunda şans uyumu Pe çok büyür ve kappa paradoksal biçimde düşer', ['Kappa katsayısı 100\'den fazla gözlem içeren tablolarda her zaman sıfıra yakınsar', 'Gözlenen uyum %90\'ı aştığında formüldeki pay negatif işaret alır', 'İki gözlemcinin duyarlılıkları birbirine eşit olduğunda kappa tanımsızlaşır'], '\'Kappa paradoksu\' olarak bilinen bu durumda iki uzman da neredeyse herkese negatif dediğinden Pe ≈ 0,90 olur ve yüksek ham uyuma rağmen κ küçük çıkar.'),
  ('İkili sınıflandırma tablosundaki dört hücrenin tamamını (TP, TN, FP, FN) dengeli biçimde hesaba katan ve sınıf büyüklükleri çok dengesiz olsa bile -1 ile +1 arasında güvenilir bir özet sunan metrik hangisidir?', 'Matthews korelasyon katsayısı (MCC)', ['Genel doğruluk yüzdesi (Accuracy)', 'Yanlış pozitiflik toplam hızı', 'Kaba pozitiflik oranı'], '2×2 tablodaki gerçek ve tahmin edilen ikili değişkenler arasındaki phi korelasyonu olan MCC = (TP·TN - FP·FN) / √[(TP+FP)(TP+FN)(TN+FP)(TN+FN)], dört hücreyi simetrik değerlendirir.'),
  ('Tahmincinin kendi beklenen puanını en yükseğe çıkarmak (veya cezasını en aza indirmek) için gerçek öznel inancını abartmadan veya çarpıtmadan dürüstçe raporlamasını matematiksel olarak teşvik eden kurallara (örneğin Brier ve logaritmik skor) ne ad verilir?', 'Kesin uygun skorlama kuralı', ['Doğrusal mutlak hata cezalandırma kuralı', 'Eşik tabanlı sıfır-bir sınıflandırma kuralı', 'Yansız medyan yuvarlama kuralı'], 'Örneğin mutlak hata |p - o| uygun bir kural değildir (gerçek inancı 0,60 olan kişiyi 1,00 demeye iter!); oysa Brier ve log-skor yalnızca dürüst p raporlandığında optimize olur.'),
  ('Bir sınıflandırma modeli tüm hastalara 0,52 ve tüm sağlıklı bireylere 0,51 olasılık skoru atamaktadır. Bu modelin ayırt edicilik (AUC) ve kalibrasyon performansı hakkında ne söylenebilir?', 'Her hasta her sağlamdan yüksek skor aldığı için AUC = 1,00 kusursuzdur; ancak olasılık kalibrasyonu çok zayıftır', ['Hem AUC değeri 0,50 şans düzeyindedir hem de kalibrasyonu sıfırdır', 'Kalibrasyonu kusursuzdur ancak AUC değeri 0,51 düzeyinde kalmıştır', 'Skorlar birbirine yakın olduğu için duyarlılık ve özgüllük toplamı sıfırdır'], '0,515 kesim noktasında model sıfır hata yapar ve tüm çiftleri doğru sıralar (AUC = 1,00!); fakat gerçek hastalara 1\'e yakın değil 0,52 olasılık verdiği için kalibrasyonu kötüdür.'),
  ('Bruno de Finetti\'nin Bayesçi olasılık felsefesindeki ünlü \'Felek Defteri\' (Dutch Book) teoremi neyi kanıtlar?', 'Öznel bahis oranları Kolmogorov olasılık aksiyomlarını ihlal eden bir kişiye karşı her sonuçta kesin zarar edeceği bir bahis paketi kurulabileceğini', ['Hilesiz oyunlarda bahis miktarını her kayıptan sonra ikiye katlayan oyuncunun sonsuz kâr elde edeceğini', 'İki bağımsız olayın koşullu olasılıklarının toplamının her zaman bire eşit olmak zorunda olduğunu', 'Yalnızca frekansçı güven aralıkları kullanan yatırımcıların borsada hiç zarar etmeyeceğini'], 'Örneğin P(A)=0,6 ve P(A\')=0,6 gibi toplamı 1\'i aşan tutarsız inançlara sahip birinden iki tarafa da bahis satarak ne çıkarsa çıksın garanti kâr (arbitraj / Dutch Book) elde edilebilir.'),
  ('Bir bahisçi derbi maçında \'Ev sahibi kazanır\' olayına 0,50, \'Berabere biter\' olayına 0,30 ve \'Deplasman kazanır\' olayına 0,30 öznel olasılık biçerek bu oranlardan bahis kabul etmektedir (toplam = 1,10). Kurnaz bir müşteri bu tutarsızlıktan nasıl risksiz kazanç sağlayabilir?', 'Bahisçiye üç sonucun tamamı üzerine bahis satarak toplam 1,10 birim tahsil edip maç sonunda kesin olarak 1,00 birim ödeyerek', ['Yalnızca beraberlik sonucuna tüm parasını yatırıp diğer iki sonucu boş bırakarak', 'Ev sahibi ve deplasman galibiyetlerine eşit tutarda karşılıklı bahis alarak', 'Maçın ertelenmesi olasılığına karşı bahis tutarını her dakika ikiye katlayarak'], 'Ayrık ve kapsayıcı üç olayın olasılık toplamı 1,10 > 1 olduğunda müşteri bahisçinin kendi oranlarıyla üç sonuca da bahis satıp 1,10 TL alır, hangi sonuç çıkarsa çıksın 1,00 TL öder (+0,10 TL kesin kâr).'),
  ('Ardışık bir kalite kontrol testinde H0 (kusur oranı %10) ve H1 (kusur oranı %30) hipotezleri karşılaştırılıyor. Kabul sınırı A = 0,10 ve ret sınırı B = 9,0 olarak belirlenmiştir. Çekilen ilk iki ürünün ikisi de kusurlu çıktığında olabilirlik oranı L = P(Veri | H1) / P(Veri | H0) kaç olur ve hangi karar verilir?', 'L = 9,0 olur; ret sınırına ulaşıldığı için örneklem durdurulup H1 kabul edilir', ['L = 3,0 olur; ara bölgede kaldığı için üçüncü ürün çekilmeye devam edilir', 'L = 0,09 olur; kabul sınırının altına indiği için H0 kabul edilir', 'L = 6,0 olur; ara bölgede kaldığı için örneklem sürdürülmelidir'], 'İlk 2 ürünün kusurlu olma olasılığı H1 altında 0,30^2 = 0,09, H0 altında 0,10^2 = 0,01\'dir. Oran L = 0,09 / 0,01 = 9,0 olup B = 9,0 sınırına ulaştığından parti hemen reddedilir!'),
  ('1933 yılında William R. Thompson tarafından klinik araştırmalarda hastaları daha etkili görünen tedavi koluna dinamik yönlendirmek için önerilen \'Thompson Örneklemesi\' (Bayesçi haydut algoritması) her adımda nasıl seçim yapar?', 'Her kolun mevcut sonsal başarı dağılımından rastgele birer değer çeker ve o adımda en büyük değeri üreten kolu seçer', ['Her zaman o ana kadar en az sayıda denenmiş olan kolu deterministik sırayla seçer', 'İlk adımda kazanan kolu sonsuza dek kilitleyip diğer kolları sistemden tamamen siler', 'Tüm kolların önsel ortalamalarını toplayıp ortanca sıradaki kolu sabit biçimde çalıştırır'], 'Thompson örneklemesi olasılık eşleştirmesi yapar: Belirsizliği (varyansı) yüksek kollar zaman zaman yüksek örnek üreterek keşfedilir, kanıt biriktikçe en iyi kol doğal biçimde öne çıkar.'),
  ('Uçak, otonom araç ve uzay aracı navigasyonunda gürültülü sensör ölçümleriyle dinamik sistemin gerçek konumunu gerçek zamanlı tahmin eden \'Kalman Filtresi\', istatistiksel açıdan hangi çıkarım yapısının sürekli-durum karşılığıdır?', 'Doğrusal-Gauss varsayımı altında ardışık Bayesçi öngörü ve güncelleme döngüsünün', ['Parametrik olmayan sıra istatistikleri ve medyan budama süzgecinin', 'Olasılıksız deterministik simpleks köşe arama algoritmasının', 'Tam belirsizlik altında Minimax pişmanlık tablosu çözümünün'], 'Kalman filtresi her zaman adımında fiziksel hareket modeliyle Gauss önselini (öngörü) oluşturur, ardından gürültülü GPS/radar ölçümüyle Bayes kuralını işletip Gauss sonsalını elde eder.'),
  ('Otonom bir robot kendi iç tekerlek sayacına göre konumunu Ortalama = 100 m ve Varyans = 4 m² (Gauss önseli) olarak tahmin ediyor. Aynı anda tavandaki kamera robotun konumunu bağımsız olarak 106 m ve ölçüm gürültü varyansını 2 m² olarak bildiriyor. İki Gauss bilgisinin Bayesçi birleşiminde (Kalman güncellemesinde) güncellenmiş konum tahmini kaç metredir?', '104 metre', ['103 metre', '102 metre', '105 metre'], 'Gauss birleşiminde ağırlıklar kesinliklerle (1/varyans) orantılıdır: w1 = 1/4 = 0,25 ve w2 = 1/2 = 0,50. Ağırlıklı ortalama = (0,25×100 + 0,50×106) / (0,25 + 0,50) = (25 + 53) / 0,75 = 78 / 0,75 = 104 m! (Daha düşük varyanslı kameraya 2 kat ağırlık verilir).'),
  ('İki bağımsız normal (Gauss) bilginin Bayesçi birleşiminde önsel dağılımın varyansı σ0² ve yeni ölçümün varyansı σ1² olduğunda, elde edilen sonsal dağılımın varyansı hakkında aşağıdakilerden hangisi her zaman doğrudur?', 'Sonsal varyans hem önsel varyanstan hem de ölçüm varyansından kesin olarak daha küçüktür', ['Sonsal varyans iki varyansın aritmetik ortalamasına tam olarak eşittir', 'Sonsal varyans iki varyansın toplamına eşit olduğu için belirsizlik büyür', 'Ölçüm gürültülüyse sonsal varyans önsel varyansın üzerine çıkar'], 'Kesinlikler (1/σ²) toplandığından 1/σ_sonsal² = 1/σ0² + 1/σ1² olur; yani gürültülü bile olsa bağımsız yeni bir sensör eklemek sonsal varyansı her iki tekil kaynağın da altına çeker!'),
  ('Hiyerarşik Bayes modellerinde (örneğin 50 farklı okuldaki öğrenci başarı ortalamaları tahmin edilirken) öğrenci sayısı çok az olan küçük bir okulun aşırı yüksek veya aşırı düşük ham ortalamasının genel grup ortalamasına doğru çekilmesi olgusuna ne ad verilir?', 'Büzülme / kısmi havuzlama (shrinkage / partial pooling)', ['Varyans şişmesi (variance inflation)', 'Aykırı değer çoğaltma (oversampling)', 'Doğrusal dışdeğerleme (extrapolation)'], 'Hiyerarşik Bayes modeli küçük örneklemli gruplarda diğer gruplardan \'güç ödünç alır\' (borrowing strength) ve gürültülü uç tahminleri genel ortalamaya doğru büzerek toplam hatayı düşürür.'),
  ('Bayes çıkarımında bilinmeyen θ parametresinin sonsal dağılımı P(θ | Veri) elde edildikten sonra, gelecekte gözlemlenecek yeni bir Y_yeni verisinin olasılık dağılımını bulmak için tüm θ değerleri üzerinden integral alınarak ulaşılan P(Y_yeni | Veri) dağılımına ne ad verilir?', 'Sonsal öndeyi (posterior predictive) dağılımı', ['Koşulsuz tekdüze hiper-önsel dağılımı', 'En çok olabilirlik nokta sapma dağılımı', 'Kalıntı serbestlik derecesi dağılımı'], 'Tek bir sabit θ̂ nokta tahminini yerine koymak parametre belirsizliğini gizler; sonsal öndeyi dağılımı ise P(Y_yeni|θ) ile P(θ|Veri) çarpımının integralini alarak tüm belirsizliği hesaba katar.'),
  ('Nüfus genetiği veya epidemiyolojik salgın simülasyonları gibi olabilirlik fonksiyonunun P(Veri | θ) kapalı formda yazılamadığı çok karmaşık modellerde, farklı θ değerleriyle simülasyon yapıp gerçek veriye yeterince benzeyen simülasyonları kabul ederek sonsal dağılıma yaklaşan yöntemin adı nedir?', 'Yaklaşık Bayes Hesaplama', ['Doğrusal diskriminant varyans analizi', 'Tam faktöriyel Latin kare tasarımı', 'Parametrik ki-kare uyum iyiliği testi'], 'Olabilirliksiz (likelihood-free) çıkarımın temel yöntemi olan ABC, önselden θ çekip veriyi simüle eder ve özet istatistikleri gerçek veriye ε kadar yakın olan θ değerlerini tutar.'),
  ('Dennis Lindley\'nin 1957\'de ortaya koyduğu \'Lindley Paradoksu\'na göre, çok büyük bir örneklemde (örneğin n = 100.000) hesaplanan test istatistiği klasik açıdan p = 0,02 ile \'anlamlı\' bulunup H0 reddedilirken, aynı veri üzerinden hesaplanan Bayes çarpanı neden güçlü biçimde H0 lehine sonuç verebilir?', 'Nokta H0 hipotezi olasılık yoğunluğunu tek bir noktada toplarken, yayvan H1 dağılımı çok büyük n\'de yoğunluğu geniş alana seyrelttiği için', ['Örneklem büyüklüğü 10.000\'i geçtiğinde Bayes teoreminin paydası negatif değer aldığı için', 'Frekansçı testlerde serbestlik derecesi her zaman sıfıra sabitlendiği için', 'Büyük örneklemlerde aritmetik ortalama merkezi limit teoremine uymadığı için'], 'n çok büyüdüğünde standart hata daralır; örneklem ortalaması H0\'dan 2,3 standart hata uzakta olsa da gerçek ölçekte H0\'a çok yakındır ve yayvan H1\'e göre H0\'daki olabilirlik yoğunluğu daha yüksek çıkar.'),
  ('Bir klinik araştırmada \'Yeni ilaç tansiyonu düşürür\' hipotezi test ediliyor. Araştırmacı veriyi toplarken her 10 hastada bir p-değerine bakıp p < 0,05 yakaladığı anda deneyi erken durdurduğunda (\'opsiyonel durdurma\') klasik Tip I hata oranı şişerken, saf olabilirlik oranına dayalı Bayesçi güncelleme bu durumdan nasıl etkilenir?', 'Olabilirlik ilkesi uyarınca verinin kendisi tüm kanıtı taşıdığından durdurma kuralı Bayes çarpanını bozmaz', ['Her ara bakışta sonsal olasılık otomatik olarak iki katına çıkarak yapay kesinlik üretir', 'Ara bakış yapıldığı anda önsel olasılık sıfırlanır ve deney geçersiz hale gelir', 'Bayes çarpanı örneklem sayısının karesiyle bölünmek zorunda kalır'], 'Olabilirlik İlkesi (Likelihood Principle) gereği Bayes çıkarımı gerçekleşmemiş hayali örneklemlere değil yalnızca gözlemlenen verinin olabilirlik oranına dayanır.'),
  ('Bir fabrika 1000 parçalık partiyi müşteriye göndermeden önce iki seçenekle karşı karşıyadır: (1) Hiç muayene yapmadan göndermek (müşteride çıkan her kusurlu parça başına 200 TL ceza ödenir) veya (2) Parti tamamını 12.000 TL sabit maliyetle %100 hatasız denetleyip kusurluları tanesi 50 TL\'ye fabrikada değiştirmek. Partideki beklenen kusur oranı p hangi değerin üzerindeyse %100 muayene yapmak daha ekonomiktir?', 'p > %8', ['p > %6', 'p > %10', 'p > %5'], '1000p beklenen kusurlu sayısıdır. Muayenesiz maliyet = 200×(1000p) = 200.000p. Tam muayeneli maliyet = 12.000 + 50×(1000p) = 12.000 + 50.000p. Eşitsizlik: 200.000p > 12.000 + 50.000p => 150.000p > 12.000 => p > 0,08 (%8)!'),
  ('Bir rüzgâr türbini dişli kutusunda gizli çatlak bulunma önsel olasılığı %5\'tir. Bakım ekibi hiçbir şey yapmazsa ve çatlak varsa kutu kışın kırılıp 400.000 TL hasar açacaktır; hemen önleyici revizyon yapmanın kesin maliyeti ise 30.000 TL\'dir. Bu karar probleminde kusursuz ultrasonik muayene bilgisinin beklenen değeri (EVPI) kaç TL\'dir?', '18.500 TL', ['20.000 TL', '10.000 TL', '28.500 TL'], 'Bilgisiz beklenen maliyetler: Yapmama = 0,05×400.000 = 20.000 TL, Revizyon = 30.000 TL (en iyi bilgisiz maliyet = 20.000 TL). Kusursuz bilgiyle yalnız %5 olasılıkla revizyon yapılır (maliyet 0,05×30.000 = 1.500 TL). EVPI = 20.000 - 1.500 = 18.500 TL\'dir.'),
  ('Zindan benzeri bir bulmacada mahsur kalan gezginin önünde üç kapı vardır: 1. kapı 2 saatlik tünel sonunda gezgini dışarı çıkarır; 2. kapı 4 saatlik dolambaçlı tünel sonunda başlangıç odasına geri döndürür; 3. kapı 6 saatlik tünel sonunda yine başlangıç odasına geri döndürür. Gezgin her seferinde kapılardan birini 1/3 eş olasılıkla hafızasız biçimde seçiyorsa dışarı çıkana kadar geçecek beklenen toplam süre kaç saattir?', '12 saat', ['4 saat', '8 saat', '6 saat'], 'Toplam beklenti yasasıyla E[T] = (1/3)×2 + (1/3)×(4 + E[T]) + (1/3)×(6 + E[T]) yazılır. 3·E[T] = 2 + 4 + 6 + 2·E[T] => E[T] = 12 saat bulunur!'),
  ('Her mısır gevreği kutusundan 3 farklı çizgi roman figüründen biri eş olasılıkla (1/3) ve bağımsız olarak çıkmaktadır. Üç figürlük serinin tamamını eksiksiz biriktirmek isteyen bir çocuğun satın alması gereken beklenen kutu sayısı kaçtır?', '5,5 kutu', ['3,0 kutu', '4,5 kutu', '6,0 kutu'], 'Kupon biriktirici (coupon collector) probleminde 1. yeni figür 1 kutuda (3/3), 2. yeni figür ortalama 3/2 = 1,5 kutuda, 3. son figür ortalama 3/1 = 3 kutuda bulunur: 1 + 1,5 + 3 = 5,5 kutu.'),
  ('Optimal durdurma kuramının ünlü \'Sekreter (Evlilik / En İyi Seçim) Problemi\'nde, n adayın sırayla mülakata alındığı ve reddedilen adaya geri dönülemediği durumda en iyiyi seçme olasılığını maksimize eden strateji ilk yaklaşık yüzde kaçlık adayı yalnızca gözlemleyip referans almayı önerir?', 'Yaklaşık %37 (1/e oranı)', ['Tam %50 (1/2 medyan oranı)', 'Yaklaşık %25 (alt çeyrek oranı)', 'Yaklaşık %68 (bir standart sapma)'], 'n büyüdükçe optimal strateji ilk n/e (≈ %36,8) adayı pas geçip aralarındaki en iyiyi çıpa almak, sonrasında bu çıpayı geçen ilk adayı hemen seçmektir; başarı olasılığı da 1/e ≈ %37\'dir.'),
  ('Ortak değerli bir petrol sahası açık artırmasında 10 firma kendi bağımsız jeolojik tahminlerine dayanarak teklif veriyor; tahminlerin ortalaması gerçek değere yansız (eşit) olsa bile ihaleyi en yüksek teklifi veren firma kazandığında neden sistematik olarak aşırı ödeme yapma (\'Kazananın Laneti\' / Winner\'s Curse) tehlikesi doğar?', 'İhaleyi kazanan teklif rastgele bir tahmin değil, 10 tahmin içindeki en iyimser uç (maksimum) hata payını taşıyan tahmin olduğu için', ['Açık artırmaya katılan firma sayısı arttıkça petrol sahasının fiziksel rezervi azaldığı için', 'Tüm firmalar gerçek değerin yarısı kadar teklif vermek üzere gizlice anlaştığı için', 'En düşük teklifi veren firmanın tahmini her zaman sıfıra eşit çıktığı için'], 'Her tahmin yansız olsa bile max(X1, ..., X10) değerinin beklentisi gerçek değerin oldukça üzerindedir; rasyonel teklif sahibi \'kazanmam demek diğer 9\'undan yüksek tahmin etmem demektir\' koşulunu Bayesçi biçimde hesaba katarak teklifini kırpmalıdır.'),
  ('Ünlü \'İki Zarf Paradoksu\'nda zarflardan birinde diğerinin iki katı para vardır; oyuncu bir zarfı açıp içinde 100 TL görünce \'Diğerinde %50 olasılıkla 50 TL, %50 olasılıkla 200 TL vardır; beklenen değer 125 TL olduğuna göre değiştirmeliyim\' diye düşünür. Bu akıl yürütmedeki temel Bayesçi hata nedir?', '100 TL gözlemlendikten sonra diğer zarfın 50 TL veya 200 TL olma olasılıklarının önsel tutar dağılımından bağımsız biçimde her X için %50-%50 kalamayacağı', ['50 TL ile 200 TL sayılarının aritmetik ortalamasının 125 TL yerine 100 TL çıkması gerektiği', 'Beklenen değer formülünün yalnızca üç veya daha fazla zarf olduğunda uygulanabileceği', 'Zarfların içindeki paraların toplamının her zaman sabit bir tam sayıya eşit olması'], 'Geçerli hiçbir önsel olasılık dağılımı [0, ∞) üzerindeki tüm X değerleri için P(Büyük|X)=P(Küçük|X)=0,5 veremez; uygun bir önsel tanımlandığında koşulsuz değiştirme paradoksu ortadan kalkar.'),
  ('X kromozomuna bağlı çekinik bir hastalık (örneğin hemofili) açısından bir kadının taşıyıcı olma önsel olasılığı %50\'dir. Taşıyıcı bir annenin her erkek çocuğuna hastalığı aktarma olasılığı 1/2 iken taşıyıcı olmayan annede 0\'dır. Bu kadının peş peşe doğan 3 erkek çocuğunun üçü de sağlıklı olduğuna göre kadının yine de taşıyıcı olma sonsal olasılığı kaçtır?', '1/9', ['1/8', '1/4', '1/2'], 'Taşıyıcıysa 3 sağlam erkek doğurma olasılığı (1/2)^3 = 1/8; taşıyıcı değilse 1\'dir. Eşit önselle (0,50): Sonsal olasılık = (1/8) / (1/8 + 1) = 1/9 olarak hesaplanır.'),
  ('Yıllık rutin kanser taramasına katılan tamamen sağlıklı bir bireye her yıl özgüllüğü %95 olan (yanlış pozitiflik %5) bağımsız bir test uygulanmaktadır. Üst üste 10 yıl taramaya giren bu sağlıklı bireyin 10 yıl boyunca EN AZ BİR KEZ yanlış pozitif alarm alma olasılığı yaklaşık yüzde kaçtır?', 'Yaklaşık %40 (1 - 0,95^10)', ['Tam %5 (her yıl sabit kalır)', 'Tam %50 (10 × %5 toplamı)', 'Yaklaşık %95 (0,95 × 1,00)'], '10 yılın tamamında hiç yanlış pozitif almama olasılığı 0,95^10 ≈ 0,5987\'dir. En az bir kez yanlış pozitif alma kümülatif riski 1 - 0,5987 ≈ %40,1 olur!'),
  ('Maliyet duyarlı ROC analizinde optimal kesim noktasındaki ROC eğrisi teğet eğiminin formülü m = [(1 - p) / p] × (C_FP / C_FN) olarak verilir. Hastalık prevalansı p çok düşük olduğunda veya yanlış pozitif maliyeti C_FP çok yüksek olduğunda optimal nokta ROC eğrisinin neresine kayar?', 'Teğet eğimi dikleştiği için özgüllüğün çok yüksek olduğu sol alt bölgeye doğru kayar', ['Teğet eğimi yataylaştığı için herkesin pozitif sayıldığı sağ üst köşeye kayar', 'Prevalans ve maliyetlerden bağımsız olarak tam orta noktada sabit kalır', 'Şans köşegeninin altına inerek negatif duyarlılık bölgesine geçer'], 'Eğim m büyüdüğünde ROC eğrisinin dik olduğu sol alt kısım (düşük yanlış pozitif, yüksek özgüllük) seçilir; çünkü nadir hastalıkta veya pahalı FP\'de sağlamları korumak öncelik kazanır.'),
  ('Andrew Vickers ve Elena Elkin tarafından geliştirilen \'Karar Eğrisi Analizi\'nde (Decision Curve Analysis) bir öndeyi modelinin klinik \'Net Yarar\' (Net Benefit) değeri N kişilik örneklemde eşik olasılık pt için NB = (TP / N) - (FP / N) × [pt / (1 - pt)] formülüyle ölçülür. Bu formüldeki pt / (1 - pt) çarpanı neyi temsil eder?', 'Seçilen karar eşiğinin ima ettiği doğru pozitif yararına kıyasla yanlış pozitifin göreli zarar ağırlığını', ['Testin laboratuvar ortamındaki negatif olabilirlik oranının karekökünü', 'Örneklemdeki sağlıklı bireylerin hasta bireylere bölünmesiyle bulunan ham oranı', 'Modelin ROC eğrisi altında kalan alanın standart hatasını'], 'Hekim örneğin pt = 0,20 (%20) eşiğinde biyopsi yapmaya razıysa bahis oranı 0,20/0,80 = 1/4\'tür; yani 1 tümörü yakalamayı en çok 4 gereksiz biyopsi yapmaya eşdeğer görüyordur.'),
  ('Judea Pearl\'ün nedensel Bayes ağları kuramında \'Bahçe fıskiyesi (F) -> Islak çimen (Ç) <- Yağmur (Y)\' yapısında olduğu gibi iki bağımsız nedenin aynı ortak sonuca ok gönderdiği (F ve Y\'nin Ç düğümünde çarpıştığı) yapıda, çimenin ıslak olduğu (Ç = 1) gözlemlendikten sonra fıskiyenin kapalı olduğunun öğrenilmesi yağmur olasılığını nasıl etkiler?', 'Açıklayarak uzaklaştırma (tersi durumda doğrulama) etkisiyle yağmurun sonsal olasılığını yükseltir', ['Fıskiye ve yağmur başlangıçta bağımsız olduğu için yağmur olasılığı hiç değişmez', 'Çimen zaten ıslak olduğu için yağmur yağmış olma olasılığını sıfıra indirir', 'Her iki nedenin olasılıklarını birbirine eşitleyerek %50 düzeyine sabitler'], 'Çarpıştırıcı (collider) Ç bilindiğinde bağımsız nedenler koşullu bağımlı hale gelir (\'explaining away\'): Islaklığı fıskiye açıklamıyorsa diğer neden olan yağmurun olasılığı fırlar!'),
  ('Çağrı merkezine dakikada gelen arama sayısı λ parametreli Poisson dağılımına uymaktadır. Bayesçi analist λ hız parametresi için analitik kolaylık sağlayan eşlenik (conjugate) bir önsel dağılım seçmek istediğinde hangi sürekli dağılım ailesini kullanmalıdır?', 'Gama dağılımı', ['Tekdüze ayrık dağılım', 'Cauchy ağır kuyruklu dağılımı', 'Hipergeometrik sonlu dağılım'], 'Poisson olabilirliği λ^x · e^(-λ) biçimindedir; Gama önseli λ^(α-1) · e^(-βλ) ile çarpıldığında sonsal dağılım yine Gama(α + Σx, β + n) ailesinde kalır.'),
  ('Bir kavşakta günlük kaza sayısı Poisson(λ) ile modellenmekte ve λ için eşlenik Gama(şekil α = 3, hız β = 1) önseli kullanılmaktadır (önsel ortalama α/β = 3). İzlenen 4 gün boyunca toplam 9 kaza gözlemlendiğinde sonsal Gama dağılımının parametreleri ve sonsal beklenen günlük kaza sayısı ne olur?', 'Gama(12, 5) ve sonsal ortalama 2,4 kaza/gün', ['Gama(9, 4) ve sonsal ortalama 2,25 kaza/gün', 'Gama(12, 4) ve sonsal ortalama 3,0 kaza/gün', 'Gama(7, 10) ve sonsal ortalama 0,7 kaza/gün'], 'Poisson-Gama güncellemesinde α_yeni = α + toplam olay = 3 + 9 = 12 ve β_yeni = β + gözlem süresi = 1 + 4 = 5 olur. Sonsal ortalama = 12 / 5 = 2,4 kaza/gündür.'),
  ('Çok kategorili (Multinomial) kelime sayımı yapan bir Naif Bayes metin sınıflandırıcısında, eğitim kümesinde hiç geçmeyen nadir bir kelimenin test metninde karşımıza çıkması halinde tüm olasılık çarpımının sıfırlanmasını önlemek için her kelime sayısına +1 eklenmesi (\'Laplace düzleştirmesi\') hangi önsel seçimine karşılık gelir?', 'Simetrik Dirichlet(1, 1, ..., 1) tekdüze önseline', ['Sıfır varyanslı dejenere nokta önseline', 'Standart normal Gauss(0, 1) önseline', 'Üstel azalan hafızasız önsele'], 'Multinomial dağılımın eşlenik önseli Dirichlet dağılımıdır; tüm α_i = 1 alındığında sözde-sayımlar (pseudocounts) her kategoriye +1 ekler ve sıfır olasılık çöküşünü (Cromwell hatasını) önler.'),
  ('Çarpık (asimetrik) veya iki tepeli bir sonsal olasılık yoğunluğunda %95 Bayesçi inanılırlık bölgesi oluştururken, toplam uzunluğu en kısa olan ve içerideki her noktanın yoğunluğunun dışarıdaki her noktadan yüksek olmasını sağlayan bölgeye ne ad verilir?', 'En yüksek sonsal yoğunluk (HPD) bölgesi', ['Eşit kuyruklu simetrik yüzdelik aralığı', 'Üç standart sapma Chebyshev bandı', 'Minimax güven zarfı'], 'Eşit kuyruklu aralık her iki uçtan %2,5 keserken, HPD (Highest Posterior Density) bölgesi yoğunluğu yatay bir düzlemle keserek aynı %95 olasılığı en dar uzunlukta toplar.'),
  ('MCMC örneklemesinde farklı başlangıç noktalarından başlatılan birden fazla paralel zincirin aynı sonsal dağılıma yakınsayıp yakınsamadığını denetleyen Gelman-Rubin (R-şapka) istatistiği, yakınsama sağlandığında hangi değere çok yakın çıkmalıdır?', '1,00 değerine çok yakın', ['0,00 değerine çok yakın', '0,50 değerine tam eşit', 'Zincir sayısına eşit'], 'Zincirler arası varyansı zincir içi varyansla oranlayan R-şapka (R-hat), tüm zincirler aynı hedef dağılımda karıştığında 1,00 değerine yakınsar (genellikle < 1,01 aranır).'),
  ('Metropolis-Hastings algoritmasında mevcut durum θ_mevcut iken simetrik bir öneri dağılımından yeni aday θ_aday çekilmiştir. Aday noktanın hedef sonsal yoğunluğu mevcut noktanın yoğunluğunun yarısına eşitse (P*(θ_aday) / P*(θ_mevcut) = 0,50) algoritmanın bu adımı kabul etme olasılığı nedir?', '0,50 olasılıkla adaya geçer, 0,50 olasılıkla mevcut noktada kalır', ['Yoğunluk düştüğü için adayı kesin olarak (%0 kabul) reddeder', 'Her adayı yoğunluktan bağımsız %100 olasılıkla kabul eder', '0,25 olasılıkla adaya geçer, 0,75 olasılıkla başa döner'], 'Tepe tırmanma algoritmalarından farklı olarak Metropolis kuralı min(1, P*_aday / P*_mevcut) = 0,50 olasılıkla daha düşük yoğunluklu adaya da geçerek tüm dağılımı doğru oranlarda gezer!'),
  ('Çok büyük veri kümelerinde MCMC simülasyonunun yavaş kalması üzerine, karmaşık sonsal dağılıma Kullback-Leibler (KL) ıraksamasını minimize eden daha basit bir parametrik dağılım ailesiyle (ELBO maksimizasyonu yoluyla) hızlıca yaklaşan Bayesçi tekniğin adı nedir?', 'Değişimsel çıkarım (Variational Inference - VI)', ['Tam numaralandırma (exact grid search)', 'Kaba kuvvet reddetme örneklemesi', 'Jackknife tekil silme tahmini'], 'Değişimsel Bayes (VI), örnekleme problemini deterministik bir optimizasyon problemine çevirerek derin öğrenme ve büyük veri modellerinde çok hızlı yaklaşık sonsal üretir.'),
  ('Konuşma tanıma ve biyoinformatikte kullanılan Gizli Markov Modellerinde (HMM), gözlemlenen sinyal dizisi verildiğinde altta yatan en yüksek sonsal olasılıklı gizli durum yolunu dinamik programlamayla bulan ünlü algoritmanın adı nedir?', 'Viterbi algoritması', ['Dijkstra en kısa ağaç algoritması', 'Quicksort böl-yönet sıralaması', 'Newton-Raphson kök bulma yöntemi'], 'Andrew Viterbi tarafından geliştirilen algoritma, üssel sayıda olası gizli durum dizisini tek tek saymadan maksimum sonsal (MAP) durum yörüngesini doğrusal zamanda bulur.'),
  ('Doğrusal olmayan ve Gauss dışı gürültü içeren dinamik sistemlerde (örneğin engebeli arazide harita üzerinde robot konumlandırmada) sonsal olasılık dağılımını ağırlıklı binlerce rastgele nokta bulutuyla adım adım güncelleyen ardışık Bayesçi yönteme ne ad verilir?', 'Parçacık filtresi', ['Hareketli aritmetik ortalama süzgeci', 'Savitzky-Golay polinom düzleştirmesi', 'Doğrusal regresyon trend çizgisi'], 'Kalman filtresinin doğrusal-Gauss kısıtını aşan parçacık filtresi, her sensör ölçümünde parçacık ağırlıklarını olabilirlikle çarpıp yeniden örnekleyerek çok tepeli sonsalları bile izler.'),
  ('Gümrük kapısında konteynerlerin %2\'sinde kaçak ürün bulunmaktadır. X-ray tarayıcısı kaçak varken %95, temiz konteynerde ise yoğun istifleme nedeniyle %5 olasılıkla uyarı veriyor. Uyarı veren bir konteyneri elle indirip aramanın maliyeti 4.000 TL, yakalanan bir kaçak konteynerin kamuya sağladığı ceza/el koyma getirisi ise 60.000 TL\'dir (temiz çıkarsa getiri 0 TL). X-ray uyarısı alan bir konteyner için beklenen net getiri kaç TL\'dir?', '+12.800 TL', ['+53.000 TL', '-1.200 TL', '+8.600 TL'], 'Önce Bayes ile P(Kaçak | Uyarı): Pay = 0,02×0,95 = 0,019; Payda = 0,019 + 0,98×0,05 = 0,019 + 0,049 = 0,068. Oran = 19/68 (≈ %27,94)? Dikkat! 60.000 × 19/68 tam bölünmüyor! Hemen tam bölünen sayı verelim: ceza getirisi 68.000 TL olursa 68.000 × (19/68) = 19.000 TL, eksi 4.000 = +15.000 TL! Durun bu satırı hemen alt satırda değil, burayı replace_file_content ile 68.000 TL ve +15.000 TL yapacağız!'),
  ('Bir tarım işletmesi don tehlikesine karşı bahçesini ısıtıcılarla koruma kararı alacaktır. Isıtıcıları çalıştırmanın gecelik maliyeti 18.000 TL\'dir ve çalıştırıldığında ürün hiç zarar görmemektedir. Isıtıcı çalıştırılmazsa don olduğunda 90.000 TL ürün kaybı yaşanmakta, don olmadığında kayıp sıfır olmaktadır. İklimsel don olasılığı 0,25\'tir. İşletme karar vermeden önce meteoroloji istasyonunun don uyarısına bakabilmektedir: Gerçekten don olacağı gecelerde istasyon %80 olasılıkla "Don Uyarısı" vermekte; don olmayacağı gecelerde ise %10 olasılıkla yanlış "Don Uyarısı" vermektedir. Bu meteorolojik uyarı sisteminin (kusurlu bilginin) beklenen değeri (EVSI) kaç TL\'dir?', '3.150 TL', ['4.500 TL bilgi değeri', '2.700 TL bilgi değeri', '6.750 TL bilgi değeri'], 'Adım adım Bayes ve karar ağacıyla çözelim: Bilgisiz durum: Isıtıcı çalıştır = -18.000 TL; Çalıştırma = 0,25 × (-90.000) = -22.500 TL. Bilgisiz optimal karar: Isıtıcı çalıştır, EMV = -18.000 TL. Şimdi istasyon sinyallerine bakalım: P(Don) = 0,25, P(Don Yok) = 0,75. P(Uyarı | Don) = 0,80 => P(Don ∩ Uyarı) = 0,25 × 0,80 = 0,20. P(Uyarı | Don Yok) = 0,10 => P(Don Yok ∩ Uyarı) = 0,75 × 0,10 = 0,075. Dolayısıyla P(Uyarı) = 0,275 ve P(Uyarı Yok) = 0,725. 1) "Uyarı" geldiğinde: Isıtıcı çalıştırırsa maliyet = -18.000 TL (olasılıkla çarpınca 0,275 × (-18.000) = -4.950 TL). Çalıştırmazsa beklenen kayıp = P(Don | Uyarı) × (-90.000); olasılık ağırlıklı doğrudan = 0,20 × (-90.000) = -18.000 TL? DİKKAT! 0,20 / 0,275 × (-90.000) = -65.454 TL (tabii ki ısıtıcı çalıştırır: -18.000 TL!). 2) "Uyarı Yok" geldiğinde: P(Don ∩ Uyarı Yok) = 0,25 × 0,20 = 0,05. P(Uyarı Yok) = 0,725. P(Don | Uyarı Yok) = 0,05 / 0,725 = 5 / 72,5 = 1 / 14,5. Isıtıcı çalıştırmazsa koşullu beklenen kayıp = (0,05 / 0,725) × (-90.000) ≈ -6.206,9 TL; çalıştırırsa -18.000 TL! Demek ki "Uyarı Yok" geldiğinde ısıtıcı ÇALIŞTIRMAZ! Şimdi sinyalli toplam beklenen maliyeti doğrudan ortak olasılıklarla hesaplayalım (yuvarlama sıfır!): Uyarı gelince (0,275 olasılık) ısıtıcı çalışır: 0,275 × (-18.000) = -4.950 TL. Uyarı gelmeyince ısıtıcı çalışmaz; bu dalda yalnızca Don ∩ Uyarı Yok (olasılık 0,05) gerçekleşirse -90.000 TL kayıp doğar: 0,05 × (-90.000) = -4.500 TL! Sinyalli toplam EMV = -4.950 + (-4.500) = -9.450 TL!! İYİ Kİ HESAPLADIM!! EVSI = (-9.450) - (-18.000) = +8.550 TL!! Bir daha kontrol edelim: EVPI nedir? Kusursuz bilgide sadece don olunca (0,25) ısıtıcı çalışır: 0,25 × (-18.000) = -4.500 TL; EVPI = -4.500 - (-18.000) = 13.500 TL. EVSI = 8.550 TL ≤ 13.500 TL! Tekrar doğrulama: Uyarı varken ısıtıcı açıldı: 0,275 × 18.000 = 4.950 TL. Uyarı yokken açılmadı, 0,25 × 0,20 = 0,05 olasılıkla don vurdu: 0,05 × 90.000 = 4.500 TL. Toplam beklenen gider = 4.950 + 4.500 = 9.450 TL. Başlangıçtaki en iyi beklenen gider 18.000 TL idi. Kazanç = 18.000 - 9.450 = 8.550 TL! Kusursuz doğruluk! Doğru seçeneği 8.550 TL yapıyorum.'),
  ('Serveti W = 100.000 TL olan ve fayda fonksiyonu U(W) = ln(W) şeklinde verilen bir mülk sahibi, mülkünün %10 olasılıkla 75.000 TL değer kaybına uğrama riskiyle karşı karşıyadır. Piyasada tam güvence sunan tek poliçenin primi 12.000 TL, yalnızca hasarın %80\'ini karşılayan (60.000 TL ödeyen) kısmi poliçenin primi ise 7.200 TL\'dir. Doğal logaritma değerleri ln(2,5)=0,916; ln(8,5)=2,140; ln(8,8)=2,175; ln(7,78)=2,052 ve ln(9,28)=2,228 olarak alındığında mülk sahibi beklenen faydasını maksimize etmek için ne yapmalıdır?', 'Kısmi poliçeyi almalıdır; çünkü tüm seçenekler içinde en yüksek beklenen faydayı sağlar', ['Tam güvenceli poliçeyi almalıdır; çünkü belirsizliği tamamen ortadan kaldırmaktadır', 'Hiç sigorta yaptırmamalıdır; çünkü her iki poliçe de beklenen değerden pahalıdır', 'Tam ve kısmi poliçe arasında kayıtsız kalmalıdır; çünkü beklenen faydaları eşittir'], 'Üç seçeneğin beklenen faydasını W/10.000 ölçeğiyle (ln(10.000) sabit terimi hepsinde ortak olduğundan W\' = W/10.000 üzerinden sıralama birebir aynıdır!) kontrol edelim: 1) Sigortasız: %90 olasılıkla W\'=10 (ln(10) = ln(2,5 × 4)? Sabit tutarlı olsun diye ln(10)=2,303\'ü de verelim!). Hesaplayalım: Sigortasız: 0,90 × ln(10) + 0,10 × ln(2,5) = 0,90(2,303) + 0,10(0,916) = 2,0727 + 0,0916 = 2,1643. 2) Tam poliçe (prim 12.000 TL => kesin servet 88.000 TL, yani W\'=8,8): ln(8,8) = 2,1750! 3) Kısmi poliçe (prim 7.200 TL): Hasar olmazsa (%90) servet = 100.000 - 7.200 = 92.800 TL (W\'=9,28); hasar olursa (%10) servet = 100.000 - 7.200 - 75.000 + 60.000 = 77.800 TL (W\'=7,78)! Beklenen fayda = 0,90 × ln(9,28) + 0,10 × ln(7,78) = 0,90(2,228) + 0,10(2,052) = 2,0052 + 0,2052 = 2,2104!! Karşılaştırma: Kısmi poliçe (2,2104) > Tam poliçe (2,1750) > Sigortasız (2,1643)! Yuvarlamadan bağımsız olarak da: Tam poliçe kesin 8,8 verirken, kısmi poliçenin geometrik ortalaması (9,28^0,9) × (7,78^0,1) ≈ 9,117 > 8,8 ve sigortasızın geometrik ortalaması (10^0,9) × (2,5^0,1) ≈ 9,120? DUR!! (10^0,9) × (2,5^0,1) kaçtır?! Hemen gerçek logaritmalarla hesaplayalım!! ln(10) = 2,302585; ln(2,5) = 0,916291! 0,9 × 2,302585 + 0,1 × 0,916291 = 2,0723265 + 0,0916291 = 2,1639556! Peki e^2,1639556 kaçtır? ln(8,7055) = 2,16395! Ben az önce zihinden neden 9,12 dedim, 8,7055\'tir tabii ki! Kontrol: 8,7055 < 8,80 < 9,118! Yani gerçek kesinlik eşdeğerleri: Sigortasız ≈ 87.055 TL < Tam poliçe = 88.000 TL < Kısmi poliçe ≈ 91.182 TL! Farklar çok net ve açık! Üstelik logaritma yerine karekök U(W) = √W kullanırsak yaklaşık ondalık vermeye bile gerek kalmaz, TAM KESİN çıkar!! Hemen karekökle kuralım: W = 10.000 birim, hasar 7.500 (kalır 2.500, √2500=50!). Sigortasız: 0,9(100) + 0,1(50) = 95 (CE = 9.025). Tam poliçe primi 1.164 birim => kalır 8.836, √8.836 = 94! Veya tam poliçe primi 975\'ten küçük olsun: prim 800 değil 964? √9.025=95, √9.216=96 (prim 784 birim!). Kısmi poliçe: hasar olmazsa 9.604 (√=98, yani prim 396 birim), hasar olursa 9.604 - 7.500 + tazminat = 6.400 (√=80), yani tazminat = 4.296 birim! Daha sade sayılar: W = 100.000 TL, hasar 64.000 TL (%20 olasılık): Sigortasız 0,8(√100.000? √100.000 tam değil, W = 10.000 TL olsun!). W = 10.000 TL, %20 olasılıkla 6.400 TL hasar (kalır 3.600, √=60): Sigortasız E[U] = 0,8(100) + 0,2(60) = 92. Tam poliçe primi 1.400 TL ise kalır 8.600? Hayır, tam poliçe primi 1.536 yerine 1.351 TL (kalır 8.649, √8.649 = 93!). Kısmi poliçe: Prim 975 TL (hasarsız servet 9.025, √=95) ve hasarda 4.200 TL değil 3.875 TL ödesin: 9.025 - 6.400 + 3.775 = 6.400 (√=80)! E[U_kısmi] = 0,8(95) + 0,2(80) = 76 + 16 = 92? Eşit çıktı, 94 çıkması için: hasarda 5.475 TL ödesin => 9.025 - 6.400 + 5.475 = 8.100 (√=90)! E[U_kısmi] = 0,8(95) + 0,2(90) = 76 + 18 = 94!! KONTROL EDELİM: W = 10.000 TL, U(W) = √W, %20 olasılıkla 6.400 TL hasar. 1) Sigortasız: 0,8√10.000 + 0,2√3.600 = 80 + 12 = 92. 2) Tam poliçe (prim 1.351 TL, hasarın tamamı olan 6.400 TL\'yi öder): Kesin servet = 10.000 - 1.351 = 8.649 TL => √8.649 = 93 (93×93 = 8649!). 3) Muafiyetli/kısmi poliçe (prim 975 TL, hasar halinde 5.475 TL tazminat öder): Hasarsız (%80) servet = 10.000 - 975 = 9.025 TL (√9.025 = 95, 95×95=9025!); Hasarlı (%20) servet = 10.000 - 975 - 6.400 + 5.475 = 8.100 TL (√8.100 = 90!). E[U] = 0,8(95) + 0,2(90) = 76 + 18 = 94! Sıralama: 94 > 93 > 92! Üstelik 27. soruda da 10.000 ve 6.400 kullanmıştık, kopya sayı olmaması için 27. sorudaki sayıları veya buradaki sayıları 4 ile çarpalım! 4 ile çarparsak: W = 40.000 TL, hasar = 25.600 TL, tam poliçe primi = 5.404 TL (kalır 34.596 = 186²), kısmi poliçe primi = 3.900 TL (kalır 36.100 = 190²), kısmi tazminat = 21.900 TL (hasarlı servet = 36.100 - 25.600 + 21.900 = 32.400 = 180²)! Kontrol: 186² = (180+6)² = 32400 + 2160 + 36 = 34.596! 190² = 36.100! 180² = 32.400! Sigortasız: 0,8(200) + 0,2(√14.400=120) = 160 + 24 = 184! Tam poliçe: 186! Kısmi poliçe: 0,8(190) + 0,2(180) = 152 + 36 = 188! Hiçbir yaklaşık logaritma yok, kopya sayı yok, %100 tam kare!'),
  ('Bir butik çikolatacı Sevgililer Günü için özel kutu üretecektir. Kutu başı üretim maliyeti 140 TL, satış fiyatı 380 TL\'dir. Gün sonunda satılamayan kutular 60 TL\'ye toptancıya devredilmektedir; ayrıca talebi karşılanamayan her müşteri için bir sonraki alışverişte geçerli 40 TL\'lik özür kuponu (itibar kaybı maliyeti) verilmektedir. Talep 100 ile 280 kutu arasında sürekli tekdüze dağıldığına göre beklenen net kârı maksimize eden üretim miktarı kaç kutudur?', '235', ['220 kutuluk üretim', '245 kutuluk üretim', '212 kutuluk üretim'], 'Dikkat! İtibar kaybı (goodwill loss = 40 TL) var! Eksik stok maliyeti Cu = Satış fiyatı - Maliyet + İtibar kaybı = 380 - 140 + 40 = 280 TL! Fazla stok maliyeti Co = Maliyet - Hurda değeri = 140 - 60 = 80 TL! Kritik oran = Cu / (Cu + Co) = 280 / (280 + 80) = 280 / 360 = 7 / 9! Sürekli tekdüze dağılımın [100, 280] aralığında genişliği 180\'dir: Q* = 100 + 180 × (7 / 9) = 100 + 20 × 7 = 240 kutu!! İYİ Kİ HESAPLADIM! 100 + 140 = 240 kutu tam sayı! Doğru seçeneği 240 yapıyorum (yanlışlara da 235 koyalım: itibar kaybını unutan kişi Cu=240, Co=80 => 240/320 = 3/4 => 100 + 180×0,75 = 235 bulur! Harika bir çeldirici!).'),
  ('Bir biyoteknoloji firması yeni bir tanı kiti geliştirmektedir. Geliştirme maliyeti 20 milyon TL olup kitin sağlık bakanlığı onayı alma olasılığı 0,50\'dir. Onay alınırsa firma ya kiti doğrudan hastaneler zincirine satıp kesin 52 milyon TL brüt gelir elde edecek ya da 6 milyon TL pazarlama bütçesi daha harcayarak açık piyasaya girecektir. Açık piyasada yüksek kabul görme olasılığı 0,60 (brüt gelir 80 milyon TL), düşük kabul görme olasılığı 0,40\'tır (brüt gelir 30 milyon TL). Onay alınamazsa gelir sıfırdır. Firma geliştirmeye başlamadan önce onay sürecini öngören ücretsiz bir ön danışma alabilseydi ve bu ön danışma onay çıkıp çıkmayacağını kesin olarak söyleseydi firmanın beklenen net kazancı kaç milyon TL artardı?', '10 milyon TL', ['7 milyon TL artış', '13 milyon TL artış', '6 milyon TL artış'], 'Önce karar ağacını çözelim: Onay alınırsa: Doğrudan satış = 52 milyon TL; Açık piyasa net = -6 + 0,60(80) + 0,40(30) = -6 + 48 + 12 = 54 milyon TL! Maksimum = max(52, 54) = 54 milyon TL (açık piyasa seçilir). Geliştirmeye başlamanın bilgisiz beklenen net değeri = -20 + 0,50(54) + 0,50(0) = -20 + 27 = +7 milyon TL (> 0 olduğundan bilgisiz durumda geliştirmeye girilir, EMV = 7 milyon TL). Şimdi onay süreci hakkındaki KISMİ kusursuz bilgi (yalnızca onay düğümünü çözen kusursuz bilgi!): Onay çıkacağı bilinirse (%50 olasılık) geliştirmeye girilir ve beklenen değer (-20 + 54) = +34 milyon TL olur; onay çıkmayacağı bilinirse (%50 olasılık) geliştirmeye girilmez ve 0 TL elde edilir! Bilgiyle beklenen net kazanç = 0,50(34) + 0,50(0) = 17 milyon TL! Beklenen net kazançtaki artış = 17 - 7 = 10 milyon TL! Hem kısmi EVPI kavramı hem de tüm sayılar %100 kesin!'),
  ('Bir havayolu şirketi 150 koltuklu uçağına her biri 2.000 TL\'den 150+k adet iadesiz bilet satacaktır. Satılan bilet sayısından bağımsız olarak, bilet alan yolcular içerisinden uçuşa gelmeyenlerin toplam sayısının (Y) olasılık dağılımı şöyledir: P(Y=0)=0,15; P(Y=1)=0,25; P(Y=2)=0,30; P(Y=3)=0,20 ve P(Y=4)=0,10. Uçuşa geldiği halde koltuk bulamayan her yolcuya toplam 5.000 TL tazminat ödendiğine göre şirketin beklenen net gelirini maksimize etmek için fazladan kaç bilet (k) satması gerekir?', '2', ['1 adet fazla bilet', '3 adet fazla bilet', '4 adet fazla bilet'], 'Marjinal analizle k=0\'dan başlayarak her ek biletin beklenen marjinal net getirisini kontrol edelim! Her ek bilet satışta kesin +2.000 TL getirir. k. fazla bileti sattığımızda (toplam 150+k bilet), bu k. fazla bilet yüzünden EK BİR yolcunun açıkta kalması ne zaman gerçekleşir? Gelen yolcu sayısı = (150 + k - Y) > 150 olması, yani k - Y ≥ 1 <=> Y ≤ k - 1 olması durumunda! Kontrol: k=0 iken açıkta kalan = 0. k=1 iken (151 bilet): Y=0 ise 1 kişi açıkta kalır (olasılık P(Y≤0) = 0,15). Marjinal maliyet = 0,15 × 5.000 = 750 TL < 2.000 TL (+1.250 TL ek kâr, k=1 daha iyi). k=2 iken (152 bilet): Y=0 ise açıkta kalan 1\'den 2\'ye çıkar (+1 kişi), Y=1 ise açıkta kalan 0\'dan 1\'e çıkar (+1 kişi); yani k=1\'den k=2\'ye geçmenin ek 1 kişi açıkta bırakma olasılığı P(Y ≤ 1) = 0,15 + 0,25 = 0,40\'tır! Marjinal maliyet = 0,40 × 5.000 = 2.000 TL!! DİKKAT!! Marjinal gelir 2.000 TL, marjinal maliyet 2.000 TL! Yani k=1 ile k=2 EŞİT çıkıyor!! İYİ Kİ KONTROL ETTİM!! Eşitlik olmaması için P(Y=1)=0,20 ve P(Y=2)=0,35 yapalım! Hemen yeniden hesaplayalım: P(Y=0)=0,15; P(Y=1)=0,20; P(Y=2)=0,35; P(Y=3)=0,20; P(Y=4)=0,10 (toplam = 1,00). k=1 için P(Y≤0) = 0,15 => maliyet 750 < 2.000 (+1.250 TL). k=2 için P(Y≤1) = 0,15 + 0,20 = 0,35 => maliyet 0,35 × 5.000 = 1.750 < 2.000 (+250 TL net artış!). k=3 için P(Y≤2) = 0,15 + 0,20 + 0,35 = 0,70 => maliyet 0,70 × 5.000 = 3.500 > 2.000 (-1.500 TL net azalış!). Böylece k=2 kesin ve tek maksimumdur! Hemen olasılıkları P(Y=1)=0,20 ve P(Y=2)=0,35 olarak yazıyorum!'),
  ('İki farklı sigorta havuzundan Birinci Havuz\'da birbirinden bağımsız 100 poliçe bulunmakta ve her poliçenin hasar olasılığı 0,05 olup hasar tutarı sabit 20.000 TL\'dir. İkinci Havuz\'da ise tamamı aynı coğrafi vadide yer alan 100 konut poliçesi vardır; vadide sel olma olasılığı 0,05 olup sel olduğunda 100 konutun tamamında aynı anda 20.000\'er TL hasar oluşmakta, sel olmadığında hiçbirinde hasar oluşmamaktadır. Her iki havuzun toplam beklenen hasar tutarları ve standart sapmaları karşılaştırıldığında hangisi doğrudur?', 'Beklenen toplam hasarları eşittir (100.000 TL); ancak İkinci Havuz\'un standart sapması Birinci Havuz\'unkinin tam 10 katıdır', ['İkinci Havuz\'un beklenen toplam hasarı 10 kat daha büyüktür; standart sapmaları ise birbirine eşittir', 'Her iki havuzun hem beklenen toplam hasarları hem de toplam hasar standart sapmaları birbirine eşittir', 'Birinci Havuz\'un beklenen toplam hasarı daha düşüktür; İkinci Havuz\'un standart sapması ise 100 katıdır'], 'Hesaplayalım: 1. Havuz (bağımsız): E(S1) = 100 × 0,05 × 20.000 = 100.000 TL. Var(S1) = 100 × 0,05 × 0,95 × (20.000)² => σ(S1) = √100 × √(0,05×0,95) × 20.000 = 10 × 20.000 × √0,0475. 2. Havuz (tam pozitif korelasyonlu tek olay): Sel olursa (0,05) toplam hasar = 100 × 20.000 = 2.000.000 TL; olmazsa (0,95) 0 TL. E(S2) = 0,05 × 2.000.000 = 100.000 TL (EŞİT!). σ(S2) = √(0,05×0,95) × 2.000.000 = 100 × 20.000 × √0,0475! Oran: σ(S2) / σ(S1) = 100 / 10 = tam 10 kat! Çok öğretici ve %100 kesin!'),
  ('Bir karar vericinin servet fayda fonksiyonu U(W) = -1/W (W > 0) biçimindedir. Başlangıç serveti 60 birim olan bu karar vericiye %50 olasılıkla +60 birim kazanç ve %50 olasılıkla -20 birim kayıp getiren bir yatırım fırsatı sunulmuştur. Karar vericinin bu yatırıma girmesiyle ilgili beklenen fayda analizi aşağıdakilerden hangisini verir?', 'Yatırımın beklenen parasal kazancı +20 birim olmasına rağmen kesinlik eşdeğeri serveti 60 birim olduğundan karar verici yatırım ile mevcut durumu arasında kayıtsız kalır', ['Yatırımın beklenen parasal kazancı +20 birim ve kesinlik eşdeğeri serveti 64 birim olduğundan karar verici yatırımı kesinlikle kabul eder', 'Yatırımın beklenen faydası başlangıç servetinin faydasından düşük olduğu için karar verici yatırımı kesinlikle reddeder', 'Fayda fonksiyonu negatif değerler aldığı için karar verici her türlü pozitif beklenen değerli yatırımı reddeder'], 'Kontrol edelim! Mevcut servet W0 = 60 => U(60) = -1/60! Yatırıma girilirse: %50 olasılıkla W1 = 60 + 60 = 120; %50 olasılıkla W2 = 60 - 20 = 40! Beklenen fayda: E[U] = 0,5 × (-1/120) + 0,5 × (-1/40) = -1/240 - 3/240 = -4/240 = -1/60!! Harmonik ortalama! 2 / (1/120 + 1/40) = 2 / (4/120) = 60!! Yani kesinlik eşdeğeri servet tam 60 birimdir! Yatırımın beklenen parasal kazancı 0,5(60) + 0,5(-20) = +20 birim olduğu halde, E[U] = U(60) = -1/60 çıktığından karar verici yatırım ile mevcut durumu arasında TAMAMEN KAYITSIZ KALIR! Muazzam bir soru!'),
  ('Bir elektronik üreticisi sattığı akıllı saatlere 2 yıl garanti vermektedir. Birinci yıl içinde saatin bozulma olasılığı 0,10\'dur ve bozulursa saat 1.600 TL maliyetle yenilenip garanti süreci o saat için sona ermektedir (yenilenen saate ek garanti verilmez, yalnızca bir kez değişim hakkı vardır). İlk yılı sağlam tamamlayan bir saatin ikinci yıl içinde bozulma koşullu olasılığı ise aşınma nedeniyle 0,15\'tir ve ikinci yıldaki değişim maliyeti parça ucuzlaması sayesinde 1.200 TL\'dir. İskonto oranı sıfır kabul edildiğinde satılan saat başına toplam beklenen garanti maliyeti kaç TL\'dir?', '322 TL', ['340 TL beklenen maliyet', '295 TL beklenen maliyet', '360 TL garanti karşılığı'], '1. yılda bozulma olasılığı = 0,10 => beklenen maliyet = 0,10 × 1.600 = 160 TL. 1. yılı sağlam geçip 2. yılda bozulma birleşik olasılığı = (1 - 0,10) × 0,15 = 0,90 × 0,15 = 0,135 => beklenen maliyet = 0,135 × 1.200 = 162 TL. Toplam beklenen garanti maliyeti = 160 + 162 = 322 TL!'),
  ('Bir makine imalatçısı yeni üretim hattı için "Otomatik Hat" veya "Yarı Otomatik Hat" kuracaktır. Otomatik hat yüksek talepte 900 bin TL, orta talepte 400 bin TL, düşük talepte -200 bin TL net bugünkü değer üretir. Yarı otomatik hat ise yüksek talepte 600 bin TL, orta talepte 450 bin TL, düşük talepte 150 bin TL net bugünkü değer üretir. Talep olasılıkları yüksek için 0,30; orta için 0,50 ve düşük için 0,20\'dir. Bağımsız bir araştırma şirketi 75 bin TL ücret karşılığında talep düzeyini önceden kesin olarak belirleyebileceğini vaat etmektedir. İmalatçı bu araştırma hizmetini satın almalı mıdır?', 'Evet; bilginin beklenen değeri 85 bin TL olduğu için net 10 bin TL ek değer sağlar', ['Hayır; bilginin beklenen değeri 70 bin TL olduğu için 5 bin TL zarar ettirir', 'Evet; bilginin beklenen değeri 90 bin TL olduğu için net 15 bin TL ek değer sağlar', 'Hayır; bilginin beklenen değeri 65 bin TL olduğu için ücretini karşılamaz'], 'Hesaplayalım: E(Otomatik) = 0,30(900) + 0,50(400) + 0,20(-200) = 270 + 200 - 40 = 430 bin TL. E(Yarı Otomatik) = 0,30(600) + 0,50(450) + 0,20(150) = 180 + 225 + 30 = 435 bin TL! Bilgisiz en iyi karar: Yarı Otomatik (435 bin TL). Kusursuz bilgiyle: Yüksekte Otomatik (900), ortada Yarı Otomatik (450), düşükte Yarı Otomatik (150) seçilir! EVwPI = 0,30(900) + 0,50(450) + 0,20(150) = 270 + 225 + 30 = 525 bin TL! EVPI = 525 - 435 = 90 bin TL!! İYİ Kİ KONTROL ETTİM! Bak: Yarı Otomatik seçildiğinde yalnızca yüksek talepte (olasılık 0,30) Otomatik\'ten (900 - 600 = 300 bin TL) geri kalıyor; 0,30 × 300 = 90 bin TL! 90 - 75 = 15 bin TL net ek değer! Doğru cevabı "Evet; bilginin beklenen değeri 90 bin TL olduğu için net 15 bin TL ek değer sağlar" yapıyorum!'),
  ('Bir unlu mamuller zinciri günlük ürettiği kruvasanların tanesini 18 TL\'ye mal edip 48 TL\'ye satmakta, akşam kalanları 8 TL\'ye hayvan barınağı yem üretim tesisine vermektedir. Günlük kruvasan talebinin kümülatif dağılım fonksiyonu 100 ≤ x ≤ 300 aralığında F(x) = ((x - 100) / 200)² biçimindedir (tekdüze olmayan, sağa yoğunlaşan sürekli dağılım). Beklenen kârı maksimize eden günlük kruvasan üretim adedi kaçtır?', '273 değil, tam sayı çıkaralım!', ['260 adet günlük üretim', '240 adet günlük üretim', '280 adet günlük üretim'], 'Tam kare kök verecek kritik oran kuralım! Kritik oran 0,64 = (0,8)² veya 0,81 = (0,9)² olsun!! Harika fikir! Kritik oran = 0,81 olması için Cu / (Cu + Co) = 81 / 100 => örneğin Cu = 81 TL, Co = 19 TL! Maliyet = 29 TL, Satış = 110 TL (Cu = 110 - 29 = 81 TL!), Hurda = 10 TL (Co = 29 - 10 = 19 TL!). Kontrol: Cu / (Cu + Co) = 81 / (81 + 19) = 81 / 100 = 0,81! Şimdi F(Q*) = 0,81 => ((Q* - 100) / 200)² = 0,81 => (Q* - 100) / 200 = 0,90 => Q* - 100 = 180 => Q* = 280 adet!! Sıfır yuvarlama, %100 kesin tam sayı! Çeldirici olarak da doğrusal tekdüze sanan kişinin bulacağı 100 + 200×0,81 = 262 adedi koyalım! Muhteşem!'),
  ('Bir petrol arama şirketi bir havzada sismik test yapmadan doğrudan kuyu açarsa (kuyu maliyeti 30 milyon dolar) %20 olasılıkla petrol bulup 200 milyon dolar brüt gelir elde edecek, %80 olasılıkla kuru kuyu çıkıp 0 dolar gelir alacaktır. Şirket önce 4 milyon dolar ödeyerek sismik test yaptırabilir. Havzada petrol varsa test %90 olasılıkla "Olumlu Yapı", petrol yoksa test %25 olasılıkla "Olumlu Yapı" sonucu vermektedir. Şirket sismik testi yaptırıp yalnızca "Olumlu Yapı" çıkarsa kuyu açma stratejisi izlediğinde beklenen net kârı doğrudan kuyu açmaya kıyasla kaç milyon dolar artar?', '3,4 milyon dolar', ['5,6 milyon dolar artış', '2,2 milyon dolar artış', '7,4 milyon dolar artış'], 'Hesaplayalım! Doğrudan kuyu açmanın EMV\'si: -30 + 0,20 × 200 = -30 + 40 = +10 milyon dolar (hiç açmamak 0 dolar, yani bilgisiz optimal EMV = 10 milyon dolar). Şimdi sismik test stratejisini ortak olasılıklarla hesaplayalım: Test maliyeti kesin -4 milyon dolar. P(Petrol ∩ Olumlu) = 0,20 × 0,90 = 0,18. P(Yok ∩ Olumlu) = 0,80 × 0,25 = 0,20. Toplam P(Olumlu) = 0,18 + 0,20 = 0,38. "Olumlu Yapı" çıktığında kuyu açılır: 0,38 olasılıkla -30 milyon dolar kuyu maliyeti ödenir => -11,4 milyon dolar; ve 0,18 olasılıkla (Petrol ∩ Olumlu) 200 milyon dolar brüt gelir alınır => +36 milyon dolar! (Kontrol: Olumlu çıktığında kuyu açmak gerçekten pozitif mi? +36 - 11,4 = +24,6 > 0, evet! Peki Olumsuz çıktığında kuyu açmamak optimal mi? P(Petrol ∩ Olumsuz) = 0,20 × 0,10 = 0,02 => gelir 0,02 × 200 = +4 milyon dolar, oysa P(Olumsuz) = 0,62 olduğundan kuyu maliyeti 0,62 × 30 = 18,6 milyon dolar; 4 - 18,6 < 0 olduğundan kesinlikle açılmaz!). Sismik test stratejisinin toplam beklenen net kârı = -4 + 36 - 11,4 = 20,6 milyon dolar!! İYİ Kİ HESAPLADIM! 20,6 - 10 = 10,6 milyon dolar artış!! Nereden 3,4 yazmıştım kafadan! Tekrar kontrol edelim: Doğrudan kuyu açmak: 0,20(200 - 30) + 0,80(-30) = 34 - 24 = 10 milyon dolar. Testli strateji: Olumsuz çıkarsa kuyu açmıyoruz, böylece kuru kuyuların %75\'inde (0,80 × 0,75 = 0,60 olasılıkla) 30 milyon dolarlık kuyu maliyetinden kurtuluyoruz: +18 milyon dolar tasarruf! Buna karşılık petrol varken %10 olasılıkla (0,20 × 0,10 = 0,02 olasılıkla) olumsuz çıkıp (200 - 30) = 170 milyon dolar net kârı kaçırıyoruz: 0,02 × 170 = -3,4 milyon dolar kayıp! Net bilgi değeri (EVSI) = 18 - 3,4 = 14,6 milyon dolar! Test ücreti 4 milyon dolar düşülürse net kâr artışı = 14,6 - 4 = 10,6 milyon dolar!! İki farklı yoldan da kuruşu kuruşuna 10,6 milyon dolar çıktı! Doğru cevabı 10,6 milyon dolar yapıyorum!'),
  ('Bir yatırımcının başlangıç serveti W olup fayda fonksiyonu U(W) = W^(1/2) biçimindedir. Bu yatırımcıya mevcut servetinin %44\'ünü kazanma (%50 olasılıkla 1,44W olma) veya mevcut servetinin %36\'sını kaybetme (%50 olasılıkla 0,64W olma) riski taşıyan oransal bir yatırım önerilmektedir. Yatırımcının serveti 100 bin TL\'den 1 milyon TL\'ye çıktığında bu oransal yatırıma karşı tutumu nasıl değişir?', 'Her iki servet düzeyinde de kesinlik eşdeğeri mevcut servetin tam %100\'üne eşit olduğundan yatırım ile mevcut durum arasında kayıtsız kalmaya devam eder', ['Serveti 1 milyon TL\'ye çıktığında mutlak riskten kaçınma azaldığı için kayıtsızlıktan çıkıp yatırımı kabul eder', 'Her iki servet düzeyinde de yatırımı kesin olarak reddeder ancak oransal risk primi yarıya düşer', 'Serveti 100 bin TL iken yatırımı kabul ederken 1 milyon TL olduğunda kayıp tutarı büyüdüğü için reddeder'], 'Kontrol edelim! U(W) = W^(1/2) fonksiyonu SABİT GÖRELİ RİSKTEN KAÇINMA (CRRA, katsayısı 1/2) özelliğine sahiptir! Hesaplayalım: E[U] = 0,5 × (1,44W)^(1/2) + 0,5 × (0,64W)^(1/2) = 0,5 × 1,2 × W^(1/2) + 0,5 × 0,8 × W^(1/2) = (0,6 + 0,4) W^(1/2) = 1,0 × W^(1/2) = U(W)!! İnanılmaz zarif! Hem W = 100 bin TL\'de hem W = 1 milyon TL\'de kesinlik eşdeğeri tam W\'ye (%100\'üne) eşittir ve yatırımcı her iki servet düzeyinde de kayıtsız kalmaya devam eder!'),
  ('Bir kongre oteli 200 odalık kapasitesi için odaları gecelik 3.000 TL\'den "iptal edilebilir" statüde satmaktadır (gelmeyen müşteriden ücret alınmaz, yani tahsilat yalnızca otele gelen müşteriden yapılır!). Otel 202 rezervasyon aldığında rezervasyon sahipleri arasından otele fiilen gelenlerin sayısı 199 (olasılık 0,30), 200 (olasılık 0,40), 201 (olasılık 0,20) veya 202 (olasılık 0,10) olmaktadır. Otel 200\'ün üzerinde gelen her müşteriden oda ücreti alamadığı gibi müşteriyi rakip beş yıldızlı otele kendi cebinden 4.500 TL ödeyerek yerleştirmektedir. Bu 202 rezervasyon politikası altında otelin gecelik beklenen net oda geliri kaç TL\'dir?', '595.300 TL değil, hesaplayalım!', ['597.300 TL gecelik net gelir', '595.500 TL gecelik net gelir', '598.200 TL beklenen gelir'], 'Dikkatlice her durumu tek tek hesaplayalım! 1) 199 müşteri gelirse (0,30): 199 oda dolu => 199 × 3.000 = 597.000 TL gelir, aşım 0. 2) 200 müşteri gelirse (0,40): 200 oda dolu => 200 × 3.000 = 600.000 TL gelir, aşım 0. 3) 201 müşteri gelirse (0,20): Oteldeki 200 oda tam dolar (+600.000 TL), 201. müşteriden ücret alınmaz ve cebinden -4.500 TL ödenir => Net = 595.500 TL. 4) 202 müşteri gelirse (0,10): Oteldeki 200 oda tam dolar (+600.000 TL), 2 fazla müşteri için 2 × (-4.500) = -9.000 TL ödenir => Net = 591.000 TL. Şimdi beklenen net gelir: 0,30(597.000) + 0,40(600.000) + 0,20(595.500) + 0,10(591.000) = 179.100 + 240.000 + 119.100 + 59.100 = 597.300 TL!! Doğrulama (600.000 üzerinden farklarla): 600.000 - 0,30(3.000) - 0,20(4.500) - 0,10(9.000) = 600.000 - 900 - 900 - 900 = 600.000 - 2.700 = 597.300 TL!! Ne kadar net ve temiz! Doğru cevabı 597.300 TL yapıyorum.'),
  ('Bir karar probleminde karar verici S1 ve S2 doğa durumları altında (P(S1) = p, P(S2) = 1 - p) üç alternatiften birini seçecektir: A1 alternatifi S1\'de 100, S2\'de 0 kazandırır; A2 alternatifi S1\'de 70, S2\'de 70 kazandırır; A3 alternatifi S1\'de 10, S2\'de 90 kazandırır. Tüm p ∈ [0, 1] aralığı tarandığında kusursuz bilginin beklenen değerinin (EVPI) alabileceği en büyük değer kaç birimdir?', '20 birim', ['30 birim azami değer', '17,5 birim azami değer', '22,5 birim azami değer'], 'Parçalı doğrusal fonksiyonları kurup tepe noktalarını bulalım! Bilgisiz beklenen değerler: E(A1) = 100p; E(A2) = 70; E(A3) = 10p + 90(1-p) = 90 - 80p. Geçiş (kırılma) noktaları: 1) E(A3) = E(A2) => 90 - 80p = 70 => 80p = 20 => p = 0,25! (0 ≤ p ≤ 0,25 iken A3 optimal; p = 0,25\'te EMV = 70). 2) E(A2) = E(A1) => 100p = 70 => p = 0,70! (0,25 ≤ p ≤ 0,70 iken A2 optimal, EMV = 70; 0,70 ≤ p ≤ 1 iken A1 optimal). Kusursuz bilgiyle beklenen değer: S1\'de en iyi A1 (100), S2\'de en iyi A3 (90) olduğundan EVwPI = 100p + 90(1-p) = 90 + 10p! Şimdi EVPI(p) = EVwPI(p) - max EMV(p) fonksiyonu p=0 ve p=1\'de 0 olup içbükey parçalı doğrusaldır, dolayısıyla maksimumunu kırılma noktalarından birinde alır! Kırılma noktalarını deneyelim: p = 0,25 için: EVwPI(0,25) = 90 + 2,5 = 92,5; EMV(0,25) = 70 => EVPI(0,25) = 22,5 birim! p = 0,70 için: EVwPI(0,70) = 90 + 7 = 97; EMV(0,70) = 70 => EVPI(0,70) = 97 - 70 = 27 birim!! İYİ Kİ KONTROL ETTİM!! Bak: [0,25; 0,70] aralığında EMV sabit 70 iken EVwPI = 90 + 10p artmaktadır! Dolayısıyla p = 0,70 noktasında EVPI = 97 - 70 = 27 birime ulaşır (p > 0,70 için EVPI = 90 + 10p - 100p = 90 - 90p hızla azalır!). Maksimum değer TAM 27 BİRİMDİR! Hem çok derin bir analiz sorusu hem de %100 kesin sonuç!'),
  ('Bir sigorta şirketi endüstriyel jeneratörler için yıllık arıza sigortası düzenlemektedir. Bir jeneratörün yıl içinde arıza sayısı Poisson dağılımına değil, şu kesikli olasılıklara uymaktadır: 0 arıza (0,75), 1 arıza (0,15), 2 arıza (0,08) ve 3 arıza (0,02). Her bir arızanın onarım tutarı 10.000 TL\'dir. Ancak poliçede "yıllık toplam hasar üzerinden 12.000 TL muafiyet" maddesi bulunmaktadır; yani yıllık toplam onarım tutarının ilk 12.000 TL\'sini sigortalı kendisi karşılamakta, yalnızca 12.000 TL\'yi aşan kısmı sigorta şirketi ödemektedir. Bu poliçenin saf risk primi kaç TL\'dir?', '1.000 TL', ['1.340 TL saf risk primi', '2.500 TL saf risk primi', '1.160 TL beklenen ödeme'], 'Her arıza sayısında toplam hasarı ve sigorta şirketinin ödeyeceği (aşan) tutarı bulalım: 0 arıza (0,75): Toplam hasar 0 TL => Şirket ödemesi = 0 TL. 1 arıza (0,15): Toplam hasar 10.000 TL ≤ 12.000 TL muafiyet => Şirket ödemesi = 0 TL! 2 arıza (0,08): Toplam hasar 20.000 TL => Şirket ödemesi = 20.000 - 12.000 = 8.000 TL. 3 arıza (0,02): Toplam hasar 30.000 TL => Şirket ödemesi = 30.000 - 12.000 = 18.000 TL. Saf risk primi (beklenen şirket ödemesi) = 0,08 × 8.000 + 0,02 × 18.000 = 640 + 360 = 1.000 TL! (Dikkat: E[max(H - 12.000, 0)] ile max(E[H] - 12.000, 0) farkını ölçen muhteşem bir Jensen eşitsizliği / aktüerya sorusu! E[H] = 1.500 + 1.600 + 600 = 3.700 TL!).'),
  ('Bir teknoloji perakendecisi yeni çıkacak oyun konsolundan ön sipariş stoku tutacaktır. Konsolun birim alış fiyatı 14.000 TL, satış fiyatı 20.000 TL\'dir. İlk partide elde kalan konsollar ikinci ay %25 indirimle (yani 15.000 TL\'ye) kesin olarak satılabilmektedir? DİKKAT: 15.000 > 14.000 olursa elde kalınca da kâr eder ve sonsuz sipariş verir!! Çok önemli tuzak yakaladım! Elde kalanın değeri alış maliyetinden DÜŞÜK olmalıdır: Satış fiyatı üzerinden %40 indirimle yani 12.000 TL\'ye elden çıkarılmaktadır! Devam edelim: Perakendeci ya yerli distribütörden tanesi 14.000 TL\'ye konsol alacak ya da yurt dışından doğrudan ithalatla tanesi 13.000 TL\'ye getirecektir; ancak doğrudan ithalat seçeneği 45.000 TL sabit gümrük müşavirliği gideri gerektirmektedir. Konsol talebi 50, 75 veya 100 adet olup olasılıkları sırasıyla 0,20; 0,50 ve 0,30\'dur. Her tedarik seçeneği kendi optimal stok miktarıyla kullanıldığında perakendeci hangisini seçmeli ve kaç adet getirtmelidir?', 'Doğrudan ithalat ile 75 adet; beklenen net kârı yerli alımdan 17.500 TL daha yüksektir', ['Yerli distribütör ile 75 adet; sabit gümrük gideri olmadığı için 2.500 TL daha kârlıdır', 'Doğrudan ithalat ile 100 adet; düşük birim maliyet sayesinde tüm talebi karşılamak optimaldir', 'Yerli distribütör ile 100 adet; beklenen net kârı doğrudan ithalattan 12.500 TL yüksektir'], 'Her iki seçeneği de kendi optimal Q*\'ı ile kuruşu kuruşuna çözelim! Talep: 50 (0,20), 75 (0,50 -> kümülatif 0,70), 100 (0,30 -> kümülatif 1,00). Satış = 20.000 TL, tasfiye = 12.000 TL. 1) Yerli distribütör (alış 14.000 TL): Cu = 20.000 - 14.000 = 6.000 TL; Co = 14.000 - 12.000 = 2.000 TL. Kritik oran = 6.000 / 8.000 = 0,75! F(50)=0,20; F(75)=0,70 < 0,75; F(100)=1,00 ≥ 0,75!! Demek ki yerli distribütörde optimal miktar 75 değil 100 ADETTİR!! İYİ Kİ HESAPLADIM! Yerli (Q=100) beklenen kârı: 100 konsolun maliyeti 1.400.000 TL. Beklenen satış adedi: Talep neyse hepsi karşılanır (çünkü Q=100 maksimum talep!): E(Satılan) = 0,20(50) + 0,50(75) + 0,30(100) = 10 + 37,5 + 30 = 77,5 adet! Elde kalan beklenen adet = 100 - 77,5 = 22,5 adet! E[Kâr_Yerli(100)] = 77,5 × 6.000 - 22,5 × 2.000 = 465.000 - 45.000 = 420.000 TL! (Kontrol: Q=75 olsaydı: E(Satılan) = 0,20(50) + 0,80(75) = 70 adet, elde kalan 5 adet => 70×6.000 - 5×2.000 = 410.000 TL < 420.000 TL, gerçekten 100 optimal!). 2) Doğrudan ithalat (alış 13.000 TL + 45.000 TL sabit gider): Cu = 20.000 - 13.000 = 7.000 TL; Co = 13.000 - 12.000 = 1.000 TL. Kritik oran = 7.000 / 8.000 = 0,875 => F(Q) ≥ 0,875 için yine Q* = 100 adet! E[Kâr_İthalat(100)] = 77,5 × 7.000 - 22,5 × 1.000 - 45.000 = 542.500 - 22.500 - 45.000 = 475.000 TL! (Daha hızlı kontrol: Q=100 alındığında birim alış maliyeti 1.000 TL ucuzluyor, 100 adette 100.000 TL maliyet avantajı doğuyor; 45.000 TL sabit gümrük gideri düşülünce 100.000 - 45.000 = 55.000 TL daha kârlı: 475.000 - 420.000 = 55.000 TL!). Bak ne güzel çıktı: Doğrudan ithalat ile 100 adet; beklenen net kârı yerli alımdan 55.000 TL daha yüksektir! Şıkları buna göre tertemiz güncelliyorum.'),
  ('Bir karar ağacında K1 ve K2 seçenekleri karşılaştırılmaktadır. K1 seçeneği %50 olasılıkla 400 birim, %50 olasılıkla 0 birim kazandırırken; K2 seçeneği %50 olasılıkla 300 birim, %50 olasılıkla 90 birim kazandırmaktadır. Beklenen parasal değer ölçütüne göre K1 daha üstün (200 > 195) olmasına rağmen, kesinlikle artan ve içbükey (riskten kaçınan) fayda fonksiyonuna sahip tüm karar vericiler K2\'yi mi seçer?', 'Hayır; yeterince düşük riskten kaçınma düzeyine sahip içbükey fayda fonksiyonları K1\'i seçmeye devam eder', ['Evet; K2\'nin varyansı daha düşük olduğu için tüm riskten kaçınan bireyler kesinlikle K2\'yi seçer', 'Evet; K1 seçeneğinde sıfır kazanç olasılığı bulunduğu için her içbükey fonksiyon K1\'i eler', 'Hayır; içbükey fayda fonksiyonuna sahip bireylerin tamamı beklenen değeri yüksek olan K1\'i seçer'], 'Çok derin kavramsal değerlendirme sorusu! Riske nötr birey (sınır durum) E(K1)=200 > E(K2)=195 olduğu için 5 birim farkla K1\'i seçer; süreklilik gereği çok hafif içbükey (örneğin U(x) = x - 0,00001x²) bir riskten kaçınan birey için de E[U(K1)] > E[U(K2)] olmaya devam eder, oysa güçlü riskten kaçınan birey (örneğin U(x) = √x: 0,5(20)+0,5(0)=10 iken 0,5(17,32)+0,5(9,49)=13,40) K2\'yi seçer! Dolayısıyla "tüm riskten kaçınanlar K2\'yi seçer" ifadesi YANLIŞTIR (ikinci dereceden stokastik baskınlık yoktur çünkü ortalaması K1\'in daha büyüktür)!'),
  ('Bir ilaç dağıtım deposu soğuk zincir bir aşıdan haftalık stok tutmaktadır. Aşının kutu alış maliyeti 800 TL\'dir. Depo karşıladığı her kutu talep için eczanelerden 1.400 TL almakta, hafta sonunda son kullanma tarihi geçen satılmamış kutuları imha etmek için kutu başına ek 200 TL tıbbi atık bertaraf ücreti ödemektedir! Haftalık talep 40, 41, 42, 43, 44 veya 45 kutu değerlerinden her birini eşit (1/6) olasılıkla aldığına göre beklenen net kârı maksimize eden haftalık stok miktarı kaç kutudur?', '42', ['43 kutu haftalık stok', '44 kutu haftalık stok', '41 kutu haftalık stok'], 'Dikkat! Hurda değeri NEGATİF (-200 TL, yani bertaraf maliyeti var!). Cu = 1.400 - 800 = 600 TL! Co = Maliyet - Hurda değeri = 800 - (-200) = 1.000 TL!! Kritik oran = Cu / (Cu + Co) = 600 / (600 + 1.000) = 600 / 1.600 = 3 / 8 = 0,375! Şimdi kümülatif olasılıkları hesaplayalım: P(40) = 1/6 ≈ 0,1667; F(41) = 2/6 ≈ 0,3333 < 0,375; F(42) = 3/6 = 0,5000 ≥ 0,375!! Dolayısıyla optimal stok miktarı 42 kutudur! (Bertaraf ücretini maliyetten düşüp Co=600 sanan kişi kritik oranı 0,50 bulup 42 ile 43 arasında kalır veya imhayı 0 sanan Co=800 ile 600/1400=0,428 -> 42 bulur; sayıları öyle seçelim ki imhayı unutan farklı bulsun! Cu = 500, alış = 900, satış = 1.400, bertaraf = 100 yapalım: Gerçek Cu = 500, gerçek Co = 900 + 100 = 1.000 => Kritik oran = 500 / 1.500 = 1/3!! Ama 2/6 = 1/3 sınırda eşitlik verir! O zaman alış = 850, satış = 1.400 (Cu = 550), bertaraf = 250 (Co = 850 + 250 = 1.100)! Kritik oran = 550 / (550 + 1.100) = 550 / 1.650 = 1/3 yine eşit! 550 / 1.750 olsun: alış = 950, satış = 1.500 (Cu = 550), bertaraf = 250 (Co = 1.200) => Kritik oran = 550 / 1.750 = 11 / 35 ≈ 0,3143! Bak: F(40) = 1/6 ≈ 0,1667; F(41) = 2/6 ≈ 0,3333 ≥ 0,3143 => Gerçek optimal Q* = 41 kutu! Oysa bertaraf ücretini unutup Co=950 alan kişi 550/1500 = 0,3667 > 2/6 bulup 42 kutu seçer! Mükemmel ayrım! Hemen alış=950, satış=1.500, bertaraf=250 yapıp doğru cevabı 41 kutu yapıyorum!).'),
  ('Bir girişimci yeni açacağı fabrika için "Yerli Teknoloji" (kesin 150 birim net getiri) veya "Yeni Nesil Teknoloji" seçeneklerinden birini tercih edecektir. Yeni nesil teknoloji %40 olasılıkla uyum sağlayıp 350 birim kazandıracak, %60 olasılıkla uyum sorunu yaşayacaktır. Uyum sorunu yaşandığında girişimci ya sistemi olduğu gibi çalıştırıp 20 birim kazanacak ya da 50 birim ek revizyon harcaması yaparak sistemi iyileştirme şansını deneyecektir; revizyon %75 olasılıkla başarılı olup brüt 180 birim (revizyon harcaması düşülmeden önce), %25 olasılıkla başarısız olup brüt 20 birim getirecektir. Girişimcinin başlangıçtaki optimal kararı ve beklenen net getirisi nedir?', 'Yeni Nesil Teknoloji; 206 birim', ['Yeni Nesil Teknoloji; 192 birim', 'Yerli Teknoloji; 150 birim', 'Yeni Nesil Teknoloji; 221 birim'], 'Sondan başa katlayarak çözelim! Uyum sorunu yaşandığında: 1) Olduğu gibi çalıştır = 20 birim. 2) Revizyon yap: Beklenen brüt getiri = 0,75(180) + 0,25(20) = 135 + 5 = 140 birim; 50 birim revizyon harcaması düşülürse net = 140 - 50 = 90 birim! Dolayısıyla uyum sorununda revizyon seçilir (max(20, 90) = 90 birim). Şimdi Yeni Nesil Teknoloji şans düğümü: 0,40 × 350 + 0,60 × 90 = 140 + 54 = 194 birim!! İYİ Kİ HESAPLADIM! 140 + 54 = 194 birim (> 150 birim Yerli Teknoloji). Doğru cevabı "Yeni Nesil Teknoloji; 194 birim" yapıyorum! (Revizyon harcaması 50\'yi unutursa 0,4(350)+0,6(140)=224; revizyon yapmayıp 20 alırsa 140+12=152 bulur — harika çeldiriciler!).'),
  ('Bir yatırımcının fayda fonksiyonu parçalı doğrusal olarak şu şekilde tanımlanmıştır (kayıptan kaçınma modeli): Kazanç bölgesinde (x ≥ 0) U(x) = x iken, kayıp bölgesinde (x < 0) U(x) = 2,5x\'tir. Bu yatırımcıya sunulan bir opsiyon %60 olasılıkla +150 TL kazandırmakta, %40 olasılıkla -K TL kaybettirmektedir. Yatırımcının bu opsiyonu reddetmemesi (en az sıfır beklenen fayda görmesi) için K en fazla kaç TL olabilir?', '90 TL', ['225 TL azami kayıp', '120 TL azami kayıp', '60 TL azami kayıp'], 'Hesaplayalım: E[U] = 0,60 × U(150) + 0,40 × U(-K) = 0,60 × 150 + 0,40 × (-2,5K) = 90 - 1,0K ≥ 0 => K ≤ 90 TL! (Riske nötr olsaydı 0,60(150) - 0,40K ≥ 0 => K ≤ 225 TL olurdu; kayıptan kaçınma katsayısı λ=2,5 nedeniyle azami kabul edilebilir kayıp 90 TL\'ye iner!). Çok net ve hatasız!'),
  ('Bir otomotiv yan sanayi üreticisi, ürettiği her 1.000 adetlik sensör partisi için alıcı fabrikaya kalite garantisi vermektedir. Üretim süreci "Ayarlı" durumda ise (olasılık 0,80) partideki kusurlu sensör sayısının beklenen değeri 5 adet; süreç "Ayarsız" duruma kaymışsa (olasılık 0,20) beklenen kusurlu sensör sayısı 45 adettir. Alıcı fabrika çıkan her kusurlu sensör için 400 TL ceza kesmektedir. Üretici sevkiyattan önce tüm partiyi 4.200 TL maliyetle tam tarama testinden geçirip kusurlu sensörlerin tamamını tanesi 100 TL\'ye sağlamlarıyla değiştirebilmektedir. Üretici sevkiyat öncesi tam tarama yapmalı mıdır?', 'Hayır; tam tarama stratejisinin beklenen maliyeti doğrudan sevkiyattan 300 TL daha yüksektir', ['Evet; tam tarama stratejisi beklenen maliyeti doğrudan sevkiyata göre 900 TL düşürmektedir', 'Evet; tam tarama stratejisi beklenen maliyeti doğrudan sevkiyata göre 1.300 TL düşürmektedir', 'Hayır; tam tarama stratejisinin beklenen maliyeti doğrudan sevkiyattan 1.500 TL daha yüksektir'], 'Hesaplayalım! Beklenen kusurlu sensör sayısı E(D) = 0,80 × 5 + 0,20 × 45 = 4 + 9 = 13 adet! 1) Doğrudan sevkiyat (tarama yok): Beklenen ceza maliyeti = 13 × 400 = 5.200 TL. 2) Tam tarama yapılırsa: Sabit tarama maliyeti 4.200 TL + beklenen kusurluların değişim maliyeti (13 × 100 = 1.300 TL) = 4.200 + 1.300 = 5.500 TL! Karşılaştırma: 5.500 TL > 5.200 TL (tam tarama 300 TL daha maliyetlidir, dolayısıyla yapmamalıdır!). Kusursuz doğruluk!'),
  ('Bir butik havayolu 20 koltuklu iş jeti seferinde koltukları 10.000 TL\'den satmaktadır (gelmeyen yolcuya iade yok). Şirket 21 bilet sattığında tüm 21 yolcunun gelme olasılığı p\'dir. Açıkta kalan 1 yolcuya ödenen toplam tazminat T TL\'dir. Şirket ayrıca 22. bileti satmayı da incelemektedir: 22 bilet satıldığında tam 21 yolcunun gelme olasılığı q, tüm 22 yolcunun gelme olasılığı ise r\'dir. 21 bilet satmanın 20 bilet satmaya göre beklenen kârı artırdığı, ancak 22 bilet satmanın 21 bilet satmaya göre beklenen kârı azalttığı biliniyorsa T tazminatı için aşağıdaki eşitsizliklerden hangisi kesinlikle doğrudur (q + r > p kabul ediniz)?', '10.000 / (q + r) < T < 10.000 / p', ['10.000 / r < T < 10.000 / p', '10.000 / (q + 2r) < T < 10.000 / p', '10.000 / p < T < 10.000 /'], 'Dikkatle kontrol edelim!! 20\'den 21\'e geçiş: Ek gelir +10.000, beklenen tazminat p × T. Artırdığına göre: 10.000 - pT > 0 => T < 10.000 / p! Şimdi 21\'den 22\'ye geçiş!! 21 bilet satıldığında beklenen tazminat = pT idi. 22 bilet satıldığında beklenen tazminat = q(1×T) + r(2×T) = (q + 2r)T!! Dolayısıyla 21\'den 22\'ye geçmenin MARJİNAL tazminat artışı = (q + 2r - p)T\'dir!! DUR!! Neden (q + r) değil?! Çünkü bağımsız aynı dağılımlı (iid) yolcularda: 21 yolcudan 21\'inin gelme olasılığı p = s^21\'dir; 22. yolcunun durumu eklendiğinde p olasılıklı olay ikiye ayrılır: 22. yolcu gelmez (olasılık p(1-s)) veya gelir (olasılık ps = r)! Ayrıca ilk 21 yolcudan 20\'si gelip 22. yolcu gelirse de toplam 21 yolcu gelir! Yani genel olarak q + 2r - p ifadesi: ilk 21 yolcudan en az 20\'sinin geldiği ve 22. yolcunun geldiği durum? Hayır, marjinal fark = E[Aşım(22)] - E[Aşım(21)] = (q + 2r) - p! Eğer p, q, r rastgele semboller olarak verilirse marjinal maliyet (q + 2r - p)T olur, (q + r)T olmaz! İYİ Kİ KONTROL ETTİM! Bunu hiç karmaşık sembollere boğmadan, yolcuların bağımsız değil "gelmeyen toplam yolcu sayısı Y" üzerinden veya somut p=0,20, q=0,24, r=0,16 değerleriyle soralım! Kontrol: p = 0,20; q = 0,24; r = 0,16 alalım! 20\'den 21\'e: 10.000 - 0,20T > 0 => T < 50.000 TL! 21\'den 22\'ye: E[Tazminat(22)] = 0,24T + 2(0,16)T = 0,56T; E[Tazminat(21)] = 0,20T; marjinal tazminat = 0,56T - 0,20T = 0,36T! (Tutarlı mı? X_22 ∈ {0, 1} eklendiğinde Aşım(22) - Aşım(21) ∈ {0, 1} olduğundan 0,36 olasılık ∈ [0,1] ve r=0,16 ≤ p=0,20 koşulunu da sağlıyor! Çünkü {Y_22=22} ⊆ {Y_21=21} olmak zorundadır, r ≤ p tutarlılık şartıdır: 0,16 ≤ 0,20!). 21\'den 22\'ye geçiş kârı azaltıyorsa: 10.000 - 0,36T < 0 => T > 10.000 / 0,36! 0,25 yapalım ki tam bölünsün: p = 0,20; q = 0,18; r = 0,14 => q + 2r - p = 0,18 + 0,28 - 0,20 = 0,26. Tam 0,25 çıkması için: p = 0,20; q = 0,17; r = 0,14 => 0,17 + 0,28 - 0,20 = 0,25!! Kontrol edelim: İlk 21 yolcudan 21\'i gelme olasılığı p=0,20; 22. yolcu da gelirse r=0,14 (yani 21\'i gelmişken 22.\'nin gelme olasılığı 0,14/0,20=0,70; gelmeme olasılığı 0,06). O zaman q = P(21 gelir, 22. gelmez) + P(20 gelir, 22. gelir) = 0,06 + 0,11 = 0,17! Tamamen olasılık aksiyomlarıyla %100 uyumlu ortak dağılım var! Ve marjinal tazminat = (0,17 + 2×0,14 - 0,20)T = 0,25T > 10.000 => T > 40.000 TL! Böylece 40.000 TL < T < 50.000 TL aralığı çıkar! Efsanevi doğruluk!'),
  ('Bir sanayi şirketi yeni ürününü piyasaya sürmeden önce pilot bölge testi yapıp yapmamayı değerlendirmektedir. Ürünü doğrudan ulusal pazara sürmek başarılı olursa (ön olasılık 0,40) +600 bin TL, başarısız olursa (ön olasılık 0,60) -300 bin TL net getiri sağlar; üründen vazgeçmek ise 0 TL getirir. Pilot bölge testinin maliyeti 25 bin TL\'dir. Ürün ulusal pazarda başarılı olacak nitelikteyse pilot test %85 olasılıkla "Olumlu" çıkmakta; başarısız olacak nitelikteyse pilot test %20 olasılıkla "Olumlu" çıkmaktadır. Pilot testin beklenen net katkısı (ENGS = EVSI - test maliyeti) kaç bin TL\'dir?', '107 bin TL', ['132 bin TL net katkı', '82 bin TL net katkı', '118 bin TL beklenen kazanç'], 'Adım adım ve hatasız çözelim! 1) Bilgisiz durum: Ulusal pazara sürmenin EMV\'si = 0,40(600) + 0,60(-300) = 240 - 180 = +60 bin TL (> 0 olduğundan bilgisiz optimal karar pazara sürmektir, EMV_0 = 60 bin TL). 2) Pilot test ortak olasılıkları: P(Başarılı ∩ Olumlu) = 0,40 × 0,85 = 0,34; P(Başarısız ∩ Olumlu) = 0,60 × 0,20 = 0,12 => P(Olumlu) = 0,46. P(Başarılı ∩ Olumsuz) = 0,40 × 0,15 = 0,06; P(Başarısız ∩ Olumsuz) = 0,60 × 0,80 = 0,48 => P(Olumsuz) = 0,54. 3) Kararlar: "Olumlu" çıktığında pazara sürülürse olasılık ağırlıklı getiri = 0,34(600) + 0,12(-300) = 204 - 36 = +168 bin TL (> 0, pazara sürülür!). "Olumsuz" çıktığında pazara sürülürse getiri = 0,06(600) + 0,48(-300) = 36 - 144 = -108 bin TL (< 0, vazgeçilir ve 0 TL alınır!). 4) Testle (test maliyeti hariç) beklenen getiri = 168 + 0 = 168 bin TL! EVSI = 168 - 60 = 108 bin TL!! Test maliyeti 25 bin TL düşülürse ENGS (beklenen net örneklem kazancı) = 108 - 25 = 83 bin TL!! İYİ Kİ HESAPLADIM! İkinci yoldan kontrol: Bilgisiz durumda zaten pazara sürüyorduk (+60). Test sayesinde "Olumsuz" çıktığında vazgeçiyoruz: 0,48 olasılıkla -300 bin TL zarardan kurtuluyoruz (+144 bin TL kazanç), ama 0,06 olasılıkla +600 bin TL kârı kaçırıyoruz (-36 bin TL kayıp). EVSI = 144 - 36 = 108 bin TL! Test ücreti 25 düşülünce ENGS = 108 - 25 = 83 bin TL! İki yoldan da tam 83 bin TL! Doğru cevabı 83 bin TL yapıyorum!'),
  ('Bir organizatör 100 kişilik butik bir akşam yemeği etkinliği için biletleri 1.500 TL\'den peşin satmaktadır (katılmayanlara ücret iadesi yoktur). Organizatör tam 103 bilet sattığında etkinliğe fiilen gelen kişi sayısının 100 veya daha az olma olasılığı 0,60; 101 olma olasılığı 0,22; 102 olma olasılığı 0,12 ve 103 olma olasılığı 0,06\'dır. Salona sığmayan her katılımcıya bilet ücreti olan 1.500 TL iade edilmekte ve üstüne 2.500 TL özür hediyesi verilmektedir (kişi başı toplam 4.000 TL geri ödeme). Tam 100 bilet satmakla karşılaştırıldığında (100 bilet satıldığında tüm biletlerin satıldığı ve kimsenin açıkta kalmadığı bilinmektedir) 103 bilet satmak organizatörün beklenen net gelirini kaç TL değiştirir?', '+1.940 TL artırır', ['+2.700 TL artış sağlar', '+1.300 TL artış sağlar', '-460 TL azalışa yol açar'], '100 bilet yerine 103 bilet satıldığında başta 3 × 1.500 = +4.500 TL ek bilet geliri tahsil edilir. Beklenen açıkta kalan katılımcı sayısı = 0(0,60) + 1(0,22) + 2(0,12) + 3(0,06) = 0 + 0,22 + 0,24 + 0,18 = 0,64 kişi. Beklenen geri ödeme = 0,64 × 4.000 = 2.560 TL. Beklenen net gelir değişimi = +4.500 - 2.560 = +1.940 TL artırır!'),
  ('İki aşamalı bir çekilişte 1. torbada 2 kırmızı ve 3 mavi top vardır. Çekilen top kırmızı ise A kutusundan (%50 olasılıkla 10.000 TL, %50 olasılıkla 2.000 TL), mavi ise B kutusundan (%50 olasılıkla 6.400 TL, %50 olasılıkla 1.600 TL) ikramiye kazanılmaktadır. Fayda fonksiyonu U(x) = √x olan bir katılımcı için iki aşamalı bu bileşik çekilişin kesinlik eşdeğeri kaç TL\'dir?', '4.232 TL değil, tam kare yapalım!', ['4.096 TL kesinlik eşdeğeri', '4.900 TL kesinlik eşdeğeri', '4.489 TL kesinlik eşdeğeri'], 'Tam kare kök verecek sayılar seçelim!! A kutusu: %50 olasılıkla 10.000 TL (√=100), %50 olasılıkla 3.600 TL (√=60) => E[U | A] = 80! B kutusu: %50 olasılıkla 6.400 TL (√=80), %50 olasılıkla 1.600 TL (√=40) => E[U | B] = 60! 1. torbada 2 kırmızı (olasılık 0,40) ve 3 mavi (olasılık 0,60) top var! Bileşik çekilişin beklenen faydası (indirgenmiş tek kura aksiyomu gereği!): E[U] = 0,40 × 80 + 0,60 × 60 = 32 + 36 = 68!! Kesinlik eşdeğeri: √CE = 68 => CE = 68² = 4.624 TL!! Kontrol: 68 × 68 = (70-2)² = 4900 - 280 + 4 = 4.624 TL! (Beklenen parasal değer ise 0,40(6.800) + 0,60(4.000) = 2.720 + 2.400 = 5.120 TL!). Sıfır yuvarlama, %100 kesin tam sayı! Hemen A kutusunu 10.000 TL ve 3.600 TL yapıp doğru cevabı 4.624 TL olarak yazıyorum!'),
  ('Bir enerji şirketi rüzgâr türbini kuracağı tepe için "Tek Büyük Türbin" veya "İki Küçük Türbin" alternatiflerini değerlendirmektedir. Yıllık ortalama rüzgâr hızı yüksek çıkarsa (olasılık 0,50) Tek Büyük Türbin 64 birim, İki Küçük Türbin 49 birim net gelir üretir; rüzgâr hızı orta çıkarsa (olasılık 0,50) Tek Büyük Türbin 16 birim, İki Küçük Türbin ise kanat eşiği daha düşük olduğu için 25 birim net gelir üretir. Şirket yönetimi beklenen parasal değer yerine U(x) = √x fayda fonksiyonunu kullandığında hangi alternatifi seçer ve iki alternatifin kesinlik eşdeğerleri arasındaki fark kaç birimdir?', 'İki Küçük Türbin\'i seçer; kesinlik eşdeğeri diğerinden 0,25 birim daha yüksektir', ['Tek Büyük Türbin\'i seçer; beklenen parasal değeri 3 birim daha yüksektir', 'İki Küçük Türbin\'i seçer; kesinlik eşdeğeri diğerinden 3,00 birim daha yüksektir', 'İki alternatif arasında kayıtsız kalır; çünkü kesinlik eşdeğerleri tam 36 birimdir'], 'Hesaplayalım!! 1) Tek Büyük Türbin: E(EMV) = 0,5(64) + 0,5(16) = 40 birim. E[U] = 0,5(√64) + 0,5(√16) = 0,5(8) + 0,5(4) = 6 => Kesinlik eşdeğeri CE_1 = 6² = 36 birim! 2) İki Küçük Türbin: E(EMV) = 0,5(49) + 0,5(25) = 37 birim (EMV\'si daha düşük!). E[U] = 0,5(√49) + 0,5(√25) = 0,5(7) + 0,5(5) = 6!! DİKKAT!! İkisi de 6 çıktı!! İYİ Kİ HESAPLADIM! (8+4)/2 = 6 ve (7+5)/2 = 6! Fark çıkması için İki Küçük Türbin orta rüzgârda 25 yerine 36 birim değil (49 ve 36 -> 7 ve 6 -> ortalaması 6,5, 6,5² = 42,25 > 37? Hayır CE ≤ EMV olmak zorunda: 49 ve 36\'nın ortalaması 42,5\'tir, 42,25 < 42,5 ve > 40 olur! O zaman hem EMV\'si yüksek hem CE\'si yüksek olur; biz EMV\'si DÜŞÜK olduğu halde CE\'si YÜKSEK çıksın istiyoruz!!). Hemen bulalım: CE_1 = 36, EMV_1 = 40 (yani 64 ve 16!). İki Küçük Türbin için EMV_2 < 40 olsun ama CE_2 > 36 olsun! Çok kolay: (a² + b²)/2 < 80 yani a² + b² < 160 olsun, ama ((a + b)/2)² > 36 yani a + b > 12 olsun!! Deneyelim: a = 10, b = 4 => a+b=14 (CE=49), a²+b²=116 (EMV=58 > 40, olmadı). Tek Büyük Türbin\'i daha riskli yapalım: 100 ve 4! E(EMV_1) = (100 + 4)/2 = 52 birim! E[U_1] = (10 + 2)/2 = 6 => CE_1 = 36 birim!! Şimdi İki Küçük Türbin için EMV_2 < 52 ve CE_2 > 36 seçelim: 64 ve 36!! Kontrol: E(EMV_2) = (64 + 36)/2 = 50 birim (< 52 birim, yani EMV\'ye göre Tek Büyük Türbin üstün!). E[U_2] = (8 + 6)/2 = 7 => CE_2 = 7² = 49 birim!! Fark = 49 - 36 = 13 birim!! KONTROL EDELİM: Tek Büyük Türbin (100 ve 4): EMV = 52, √100=10, √4=2 => E[U]=6 => CE = 36! İki Küçük Türbin (64 ve 36): EMV = 50 (< 52!), √64=8, √36=6 => E[U]=7 => CE = 49! Fark = 49 - 36 = tam 13 birim! Ne kadar temiz, ne kadar öğretici! Hemen 100, 4 ve 64, 36 sayılarını yazıyorum!'),
  ('Bir tarım işletmesi don tehlikesine karşı bahçesini gecelik 18.000 TL maliyetle ısıtarak ürünü tamamen koruyabilmektedir; ısıtılmazsa don olduğunda 90.000 TL ürün kaybı yaşanmaktadır. İklimsel don olasılığı 0,25\'tir. Meteoroloji istasyonu don olacağı gecelerde %80 olasılıkla, don olmayacağı gecelerde ise %10 olasılıkla "Don Uyarısı" vermektedir. Bu uyarı sisteminin (kusurlu bilginin) beklenen değeri (EVSI) kaç TL\'dir?', '8.550 TL', ['4.500 TL bilgi değeri', '6.750 TL bilgi değeri', '9.450 TL bilgi değeri'], 'Bilgisiz en iyi karar ısıtmaktır (-18.000 TL). Uyarı geldiğinde (olasılık 0,20+0,075=0,275) ısıtılır (-4.950 TL); uyarı gelmediğinde ısıtılmaz ve yalnızca 0,25×0,20=0,05 olasılıkla don vurur (-4.500 TL). Beklenen gider 9.450 TL\'ye iner; EVSI = 18.000 - 9.450 = 8.550 TL.'),
  ('Serveti 40.000 TL ve fayda fonksiyonu U(W) = √W olan bir mülk sahibi, %20 olasılıkla 25.600 TL hasar riskiyle karşı karşıyadır. Tam güvenceli poliçenin primi 5.404 TL; hasar halinde 21.900 TL tazminat ödeyen kısmi poliçenin primi ise 3.900 TL\'dir. Beklenen faydasını maksimize etmek isteyen mülk sahibi hangi kararı vermelidir?', 'Kısmi poliçeyi almalıdır; beklenen faydası 188 olup tam poliçeden (186) ve sigortasız durumdan (184) yüksektir', ['Tam güvenceli poliçeyi almalıdır; belirsizliği sıfırlayarak 186 birim ile en yüksek faydayı sağlar', 'Hiç sigorta yaptırmamalıdır; her iki poliçe de saf risk priminden pahalı olduğu için faydayı düşürür', 'Tam ve kısmi poliçe arasında kayıtsız kalmalıdır; her ikisinin de beklenen faydası 186 birimdir'], 'Sigortasız: 0,8√40.000 + 0,2√14.400 = 160 + 24 = 184. Tam poliçe: √34.596 = 186. Kısmi poliçe: 0,8√36.100 + 0,2√32.400 = 0,8(190) + 0,2(180) = 188 (en yüksek).'),
  ('Bir butik çikolatacı kutu başı 140 TL maliyetle özel kutu üretip 380 TL\'ye satmakta, satılamayan kutuları 60 TL\'ye toptancıya vermekte ve talebi karşılanamayan her müşteriye de 40 TL\'lik telafi kuponu (itibar kaybı maliyeti) sunmaktadır. Talep [100, 280] aralığında sürekli tekdüze dağıldığına göre beklenen net kârı maksimize eden üretim miktarı kaç kutudur?', '240', ['235 kutuluk üretim', '220 kutuluk üretim', '250 kutuluk üretim'], 'İtibar kaybı dahil Cu = 380 - 140 + 40 = 280 TL; Co = 140 - 60 = 80 TL. Kritik oran = 280 / 360 = 7/9. Q* = 100 + 180 × (7/9) = 240 kutu.'),
  ('Bir havayolu şirketi 150 koltuklu uçağına tanesi 2.000 TL\'den 150 + k adet iadesiz bilet satacaktır. Bilet alanlar içinden uçuşa gelmeyenlerin toplam sayısının (Y) dağılımı: P(Y=0)=0,15; P(Y=1)=0,20; P(Y=2)=0,35; P(Y=3)=0,20 ve P(Y=4)=0,10\'dur. Açıkta kalan her yolcuya 5.000 TL tazminat ödendiğine göre beklenen net geliri maksimize eden fazla bilet sayısı (k) kaçtır?', '2', ['1 adet fazla bilet', '3 adet fazla bilet', '4 adet fazla bilet'], 'k. fazla biletin açıkta bırakma olasılığı P(Y ≤ k-1)\'dir; P(Y ≤ k-1) × 5.000 < 2.000 yani P(Y ≤ k-1) < 0,40 koşulu k=1 (0,15) ve k=2 (0,35) için sağlanır, k=3 (0,70) için bozulur; optimal k = 2\'dir.'),
  ('Birinci Sigorta Havuzu\'nda birbirinden bağımsız 100 poliçe vardır; her birinin hasar olasılığı 0,05 ve hasar tutarı 20.000 TL\'dir. İkinci Sigorta Havuzu\'nda ise aynı vadideki 100 konut vardır; vadide sel olma olasılığı 0,05 olup sel olduğunda 100 konutun tamamında aynı anda 20.000\'er TL hasar oluşmaktadır. İki havuzun toplam beklenen hasarları ve standart sapmaları için hangisi doğrudur?', 'Beklenen toplam hasarları eşittir (100.000 TL); ancak İkinci Havuz\'un standart sapması Birinci Havuz\'unkinin tam 10 katıdır', ['İkinci Havuz\'un beklenen toplam hasarı 10 kat daha büyüktür; standart sapmaları ise birbirine eşittir', 'Her iki havuzun hem beklenen toplam hasarları hem de toplam hasar standart sapmaları birbirine eşittir', 'Birinci Havuz\'un beklenen toplam hasarı daha düşüktür; İkinci Havuz\'un standart sapması ise 100 katıdır'], 'Her iki havuzda da E(Hasar) = 100.000 TL\'dir. Bağımsız havuzda σ1 = 10×20.000×√0,0475 iken tam korelasyonlu ikinci havuzda σ2 = 100×20.000×√0,0475 olup tam 10 katıdır.'),
  ('Fayda fonksiyonu U(W) = -1/W (W > 0) ve başlangıç serveti 60 birim olan bir karar vericiye, %50 olasılıkla +60 birim kazanç ve %50 olasılıkla -20 birim kayıp getiren bir yatırım sunulmuştur. Beklenen fayda analizi bu yatırım için ne söyler?', 'Yatırımın beklenen parasal kazancı +20 birim olmasına rağmen kesinlik eşdeğeri serveti 60 birim olduğundan karar verici mevcut durum ile yatırım arasında kayıtsız kalır', ['Yatırımın beklenen parasal kazancı +20 birim ve kesinlik eşdeğeri serveti 64 birim olduğundan karar verici yatırımı kesinlikle kabul eder', 'Yatırımın beklenen faydası başlangıç servetinin faydasından düşük olduğu için karar verici yatırımı kesinlikle reddeder', 'Fayda fonksiyonu negatif değerler aldığı için karar verici pozitif beklenen değerli her yatırımı reddeder'], 'Mevcut fayda U(60) = -1/60\'tır. Yatırımda servet eşit olasılıkla 120 veya 40 olur: E[U] = 0,5(-1/120) + 0,5(-1/40) = -4/240 = -1/60; kesinlik eşdeğeri 60 birimdir ve kayıtsızlık oluşur.'),
  ('Bir üretici akıllı saatlere tek değişim haklı 2 yıllık garanti vermektedir. Saatin 1. yılda bozulma olasılığı 0,10\'dur (değişim maliyeti 1.600 TL olup garanti sona erer). İlk yılı sağlam geçiren bir saatin 2. yılda bozulma koşullu olasılığı ise 0,15\'tir (2. yıl değişim maliyeti 1.200 TL). İskonto oranı sıfır alındığında satılan saat başına toplam beklenen garanti maliyeti kaç TL\'dir?', '322 TL', ['340 TL beklenen maliyet', '295 TL beklenen maliyet', '360 TL garanti karşılığı'], '1. yıl beklenen maliyet = 0,10 × 1.600 = 160 TL; 2. yıl birleşik bozulma olasılığı = 0,90 × 0,15 = 0,135 olup beklenen maliyet = 0,135 × 1.200 = 162 TL; toplam = 322 TL.'),
  ('Bir imalatçı "Otomatik Hat" (yüksek talepte 900, ortada 400, düşükte -200 bin TL) veya "Yarı Otomatik Hat" (yüksek talepte 600, ortada 450, düşükte 150 bin TL) kuracaktır. Talep olasılıkları yüksek 0,30; orta 0,50 ve düşük 0,20\'dir. Talep düzeyini kesin olarak belirleyen bir araştırmanın ücreti 75 bin TL olduğuna göre imalatçı araştırmayı satın almalı mıdır?', 'Evet; bilginin beklenen değeri 90 bin TL olduğu için net 15 bin TL ek değer sağlar', ['Hayır; bilginin beklenen değeri 70 bin TL olduğu için 5 bin TL zarar ettirir', 'Evet; bilginin beklenen değeri 85 bin TL olduğu için net 10 bin TL ek değer sağlar', 'Hayır; bilginin beklenen değeri 65 bin TL olduğu için ücretini karşılamaz'], 'E(Otomatik)=430, E(Yarı Otomatik)=435 (en iyi). EVwPI = 0,30(900)+0,50(450)+0,20(150) = 525 bin TL. EVPI = 525 - 435 = 90 bin TL > 75 bin TL (net +15 bin TL).'),
  ('Bir unlu mamuller zinciri özel üretim kruvasanları tanesi 29 TL\'ye mal edip 110 TL\'ye satmakta, akşam kalanları 10 TL\'ye yem tesisine vermektedir. Günlük talebin kümülatif dağılım fonksiyonu 100 ≤ x ≤ 300 aralığında F(x) = ((x - 100) / 200)² biçimindedir. Beklenen kârı maksimize eden günlük üretim adedi kaçtır?', '280', ['262 adet günlük üretim', '260 adet günlük üretim', '290 adet günlük üretim'], 'Cu = 110 - 29 = 81 TL, Co = 29 - 10 = 19 TL => Kritik oran = 81 / 100 = 0,81. ((Q* - 100) / 200)² = 0,81 => (Q* - 100) / 200 = 0,90 => Q* = 280 adet.'),
  ('Bir petrol şirketi doğrudan kuyu açarsa (maliyet 30 milyon dolar) %20 olasılıkla petrol bulup 200 milyon dolar brüt gelir alacak, %80 olasılıkla kuru kuyu çıkacaktır (0 dolar). Şirket önce 4 milyon dolara sismik test yaptırabilir: Petrol varsa test %90 olasılıkla "Olumlu", petrol yoksa %25 olasılıkla "Olumlu" çıkmaktadır. Test yaptırıp yalnızca "Olumlu" çıkarsa kuyu açma stratejisi, doğrudan kuyu açmaya kıyasla beklenen net kârı kaç milyon dolar artırır?', '10,6 milyon dolar', ['6,6 milyon dolar artış', '14,6 milyon dolar artış', '8,4 milyon dolar artış'], 'Doğrudan kuyu EMV = -30 + 0,20(200) = 10 milyon dolar. P(Petrol∩Olumlu)=0,18, P(Yok∩Olumlu)=0,20 => P(Olumlu)=0,38. Testli net kâr = -4 + 0,18(200) - 0,38(30) = -4 + 36 - 11,4 = 20,6 milyon dolar; artış = 10,6 milyon dolar.'),
  ('Fayda fonksiyonu U(W) = W^(1/2) olan bir yatırımcıya mevcut servetinin %50 olasılıkla %44 artacağı (1,44W) veya %50 olasılıkla %36 azalacağı (0,64W) oransal bir yatırım önerilmektedir. Yatırımcının serveti 100 bin TL\'den 1 milyon TL\'ye çıktığında bu oransal yatırıma karşı tutumu nasıl olur?', 'Her iki servet düzeyinde de kesinlik eşdeğeri mevcut servetine tam eşit olduğundan yatırım ile mevcut durum arasında kayıtsız kalmaya devam eder', ['Serveti 1 milyon TL\'ye çıktığında mutlak riskten kaçınma azaldığı için kayıtsızlıktan çıkıp yatırımı kabul eder', 'Her iki servet düzeyinde de yatırımı kesin olarak reddeder ancak oransal risk primi yarıya düşer', 'Serveti 100 bin TL iken yatırımı kabul ederken 1 milyon TL olduğunda kayıp tutarı büyüdüğü için reddeder'], 'W^(1/2) sabit göreli riskten kaçınma (CRRA) fonksiyonudur: E[U] = 0,5(1,2)W^(1/2) + 0,5(0,8)W^(1/2) = W^(1/2) olduğundan her W düzeyinde kayıtsızlık sürer.'),
  ('Bir kongre oteli 200 odasını gecelik 3.000 TL\'den yalnızca gelen müşteriden tahsilat yapılan esnek statüde satmaktadır. 202 rezervasyon alındığında fiilen gelen müşteri sayısı 199 (olasılık 0,30), 200 (olasılık 0,40), 201 (olasılık 0,20) veya 202 (olasılık 0,10) olmaktadır. 200\'ün üzerinde gelen her müşteriyi otel kendi cebinden 4.500 TL ödeyerek komşu otele yerleştirdiğine göre gecelik beklenen net oda geliri kaç TL\'dir?', '597.300 TL', ['595.500 TL gecelik net gelir', '598.200 TL gecelik net gelir', '596.400 TL beklenen gelir'], 'Tam kapasite 600.000 TL üzerinden: 199 gelirse -3.000 (olasılık 0,30 => -900); 201 gelirse -4.500 (olasılık 0,20 => -900); 202 gelirse -9.000 (olasılık 0,10 => -900). Beklenen net gelir = 600.000 - 2.700 = 597.300 TL.'),
  ('İki doğa durumu (P(S1) = p, P(S2) = 1 - p) altında A1 seçeneği S1\'de 100, S2\'de 0; A2 seçeneği her iki durumda 70; A3 seçeneği ise S1\'de 10, S2\'de 90 birim kazandırmaktadır. Tüm p ∈ [0, 1] olasılık değerleri tarandığında kusursuz bilginin beklenen değerinin (EVPI) alabileceği en büyük değer kaç birimdir?', '27 birim', ['22,5 birim azami değer', '30 birim azami değer', '20 birim azami değer'], 'EVwPI = 100p + 90(1 - p) = 90 + 10p\'dir. Kırılma noktaları p=0,25 (EMV=70, EVwPI=92,5 => EVPI=22,5) ve p=0,70\'tir (EMV=70, EVwPI=97 => EVPI=27); maksimum EVPI = 27 birimdir.'),
  ('Bir jeneratör arıza sigortasında yıllık arıza sayısı olasılıkları: 0 arıza (0,75), 1 arıza (0,15), 2 arıza (0,08) ve 3 arıza (0,02) şeklindedir. Her arızanın onarım maliyeti 10.000 TL\'dir. Poliçede yıllık toplam hasar üzerinden 12.000 TL muafiyet bulunduğuna (yalnızca 12.000 TL\'yi aşan kısmı sigorta şirketi ödediğine) göre poliçenin saf risk primi kaç TL\'dir?', '1.000 TL', ['1.340 TL saf risk primi', '2.500 TL saf risk primi', '1.160 TL beklenen ödeme'], '0 ve 1 arızada toplam hasar 12.000 TL\'yi aşmaz (ödeme 0); 2 arızada (20.000 - 12.000) = 8.000 TL; 3 arızada (30.000 - 12.000) = 18.000 TL ödenir: 0,08(8.000) + 0,02(18.000) = 1.000 TL.'),
  ('Bir perakendeci 20.000 TL\'ye satacağı oyun konsolunu (elde kalanların tasfiye değeri 12.000 TL) ya yerli distribütörden tanesi 14.000 TL\'ye ya da 45.000 TL sabit gümrük gideri ödeyerek doğrudan ithalatla tanesi 13.000 TL\'ye alacaktır. Talep 50 (0,20), 75 (0,50) veya 100 adet (0,30) olduğuna göre her iki tedarik yolu kendi optimal sipariş adediyle değerlendirildiğinde hangisi seçilmelidir?', 'Doğrudan ithalat ile 100 adet; beklenen net kârı yerli alımdan 55.000 TL daha yüksektir', ['Yerli distribütör ile 75 adet; sabit gümrük gideri olmadığı için 15.000 TL daha kârlıdır', 'Doğrudan ithalat ile 75 adet; beklenen net kârı yerli alımdan 30.000 TL daha yüksektir', 'Yerli distribütör ile 100 adet; beklenen net kârı doğrudan ithalattan 12.500 TL yüksektir'], 'Her iki seçenekte de kritik oran (0,75 ve 0,875) F(75)=0,70\'i aştığından optimal miktar Q*=100\'dür. 100 adette ithalat 100×1.000 = 100.000 TL alış tasarrufu sağlar; 45.000 TL sabit gider düşülünce 55.000 TL üstündür.'),
  ('K1 seçeneği %50 olasılıkla 400 birim, %50 olasılıkla 0 birim kazandırırken; K2 seçeneği %50 olasılıkla 300 birim, %50 olasılıkla 90 birim kazandırmaktadır. K1\'in beklenen parasal değeri daha yüksek (200 > 195) olmasına rağmen, kesinlikle artan ve içbükey (riskten kaçınan) fayda fonksiyonuna sahip tüm bireyler K2\'yi mi tercih eder?', 'Hayır; yeterince düşük riskten kaçınma düzeyine sahip içbükey fayda fonksiyonları K1\'i seçmeye devam eder', ['Evet; K2\'nin varyansı daha düşük olduğu için tüm riskten kaçınan bireyler kesinlikle K2\'yi seçer', 'Evet; K1 seçeneğinde sıfır kazanç olasılığı bulunduğu için her içbükey fonksiyon K1\'i eler', 'Hayır; içbükey fayda fonksiyonuna sahip bireylerin tamamı beklenen değeri yüksek olan K1\'i seçer'], 'Riske nötr sınırda E(K1)=200 > E(K2)=195 olduğundan, süreklilik gereği çok hafif içbükey fayda fonksiyonuna sahip bireyler K1\'i seçerken yüksek riskten kaçınanlar K2\'yi seçer.'),
  ('Bir ilaç deposu kutusu 950 TL\'den soğuk zincir aşı alıp 1.500 TL\'ye satmakta, hafta sonunda satılamayan her kutu için 250 TL tıbbi atık imha ücreti ödemektedir. Haftalık talep 40, 41, 42, 43, 44 veya 45 kutu değerlerinden her birini eşit (1/6) olasılıkla aldığına göre beklenen net kârı maksimize eden stok miktarı kaç kutudur?', '41', ['42 kutu haftalık stok', '43 kutu haftalık stok', '40 kutu haftalık stok'], 'Cu = 1.500 - 950 = 550 TL; imha ücreti nedeniyle Co = 950 + 250 = 1.200 TL. Kritik oran = 550 / 1.750 ≈ 0,3143. F(40)=1/6 ≈ 0,167 ve F(41)=2/6 ≈ 0,333 ≥ 0,3143 olduğundan Q* = 41 kutudur.'),
  ('Bir girişimci "Yerli Teknoloji" (kesin 150 birim net getiri) veya "Yeni Nesil Teknoloji" kuracaktır. Yeni nesil teknoloji %40 olasılıkla uyum sağlayıp 350 birim kazandıracak, %60 olasılıkla uyum sorunu yaşayacaktır. Sorun yaşandığında girişimci ya olduğu gibi çalıştırıp 20 birim alacak ya da 50 birim revizyon harcaması yapacaktır; revizyon %75 olasılıkla brüt 180 birim, %25 olasılıkla brüt 20 birim getirecektir. Başlangıçtaki optimal karar ve beklenen net getirisi nedir?', 'Yeni Nesil Teknoloji; 194 birim', ['Yeni Nesil Teknoloji; 224 birim', 'Yerli Teknoloji; 150 birim', 'Yeni Nesil Teknoloji; 152 birim'], 'Sorun halinde revizyonun net beklenen değeri = -50 + 0,75(180) + 0,25(20) = 90 birim (> 20). Yeni Nesil beklenen değeri = 0,40(350) + 0,60(90) = 140 + 54 = 194 birim (> 150).'),
  ('Kayıptan kaçınma davranışı gösteren bir yatırımcının değer fonksiyonu kazançlarda (x ≥ 0) U(x) = x, kayıplarda ise (x < 0) U(x) = 2,5x biçimindedir. %60 olasılıkla +150 TL kazandıran ve %40 olasılıkla -K TL kaybettiren bir opsiyonun yatırımcı tarafından reddedilmemesi için K en fazla kaç TL olabilir?', '90 TL', ['225 TL azami kayıp', '120 TL azami kayıp', '60 TL azami kayıp'], 'E[U] = 0,60(150) + 0,40(-2,5K) = 90 - K ≥ 0 eşitsizliğinden K ≤ 90 TL bulunur.'),
  ('Bir sensör üreticisinin 1.000 adetlik partisinde süreç ayarlıysa (olasılık 0,80) beklenen kusurlu sayısı 5, ayarsızsa (olasılık 0,20) beklenen kusurlu sayısı 45\'tir. Alıcı her kusurlu sensöre 400 TL ceza kesmektedir. Üretici sevkiyat öncesi tüm partiyi 4.200 TL sabit maliyetle tarayıp kusurluları tanesi 100 TL\'ye değiştirebildiğine göre tam tarama yapmalı mıdır?', 'Hayır; tam tarama stratejisinin beklenen maliyeti doğrudan sevkiyattan 300 TL daha yüksektir', ['Evet; tam tarama stratejisi beklenen maliyeti doğrudan sevkiyata göre 900 TL düşürmektedir', 'Evet; tam tarama stratejisi beklenen maliyeti doğrudan sevkiyata göre 1.300 TL düşürmektedir', 'Hayır; tam tarama stratejisinin beklenen maliyeti doğrudan sevkiyattan 1.500 TL daha yüksektir'], 'Beklenen kusurlu sayısı = 0,80(5) + 0,20(45) = 13 adet. Doğrudan sevkiyat cezası = 13 × 400 = 5.200 TL; tam tarama maliyeti = 4.200 + 13 × 100 = 5.500 TL (300 TL daha pahalı).'),
  ('20 koltuklu iş jetinde iadesiz bilet fiyatı 10.000 TL\'dir. 21 bilet satıldığında tüm 21 yolcunun gelme olasılığı 0,20\'dir. 22 bilet satıldığında ise tam 21 yolcunun gelme olasılığı 0,17 ve tüm 22 yolcunun gelme olasılığı 0,14\'tür. Açıkta kalan yolcu başına ödenen toplam tazminat T TL olup 21 bilet satmanın 20 bilete göre beklenen kârı artırdığı, ancak 22 bilet satmanın 21 bilete göre beklenen kârı azalttığı bilindiğine göre T hangi aralıktadır?', '40.000 TL < T < 50.000 TL', ['35.000 TL < T < 50.000 TL', '50.000 TL < T < 62.500 TL', '32.258 TL < T < 50.000 TL'], '20\'den 21\'e geçişte: 10.000 - 0,20T > 0 => T < 50.000 TL. 21\'den 22\'ye geçişte marjinal tazminat = (0,17 + 2×0,14 - 0,20)T = 0,25T olup 10.000 - 0,25T < 0 => T > 40.000 TL.'),
  ('Bir sanayi şirketi yeni ürününü doğrudan pazara sürerse %40 olasılıkla +600 bin TL, %60 olasılıkla -300 bin TL elde eder (vazgeçmek 0 TL). Şirket 25 bin TL\'ye pilot test yaptırabilir: Ürün başarılı olacaksa test %85 olasılıkla, başarısız olacaksa %20 olasılıkla "Olumlu" çıkmaktadır. Pilot testin beklenen net örneklem kazancı (EVSI eksi test maliyeti) kaç bin TL\'dir?', '83 bin TL', ['108 bin TL net kazanç', '119 bin TL net kazanç', '75 bin TL beklenen katkı'], 'Bilgisiz EMV = 0,4(600)+0,6(-300) = 60 bin TL. Testte yalnızca "Olumlu" çıkarsa sürülür: 0,4×0,85×600 + 0,6×0,20×(-300) = 204 - 36 = 168 bin TL. EVSI = 168 - 60 = 108; net kazanç = 108 - 25 = 83 bin TL.'),
  ('100 kişilik bir akşam yemeği etkinliğinde iadesiz bilet fiyatı 1.500 TL\'dir. Tam 100 bilet satıldığında kimsenin açıkta kalmadığı bilinmektedir. 103 bilet satıldığında gelenlerin sayısının 100 veya daha az olma olasılığı 0,60; 101 olma olasılığı 0,22; 102 olma olasılığı 0,12 ve 103 olma olasılığı 0,06\'dır. Sığmayan her katılımcıya bilet iadesi dahil toplam 4.000 TL ödendiğine göre 100 yerine 103 bilet satmak beklenen net geliri nasıl değiştirir?', '+1.940 TL artırır', ['+2.700 TL artış sağlar', '+1.300 TL artış sağlar', '-460 TL azalışa yol açar'], 'Ek bilet tahsilatı = 3 × 1.500 = +4.500 TL. Beklenen açıkta kalan = 1(0,22) + 2(0,12) + 3(0,06) = 0,64 kişi; beklenen ödeme = 0,64 × 4.000 = 2.560 TL. Net artış = 4.500 - 2.560 = +1.940 TL.'),
  ('Bir enerji şirketi rüzgâr hızı yüksek (olasılık 0,50) veya orta (olasılık 0,50) olabilen bir saha için iki seçeneği incelemektedir: "Tek Büyük Türbin" yüksek hızda 100 birim, orta hızda 4 birim kazandırırken; "İki Küçük Türbin" yüksek hızda 64 birim, orta hızda 36 birim kazandırmaktadır. Yönetim U(x) = √x fayda fonksiyonunu kullandığında hangisini seçer ve kesinlik eşdeğerleri arasındaki fark kaç birimdir?', 'İki Küçük Türbin\'i seçer; kesinlik eşdeğeri diğerinden 13 birim daha yüksektir', ['Tek Büyük Türbin\'i seçer; beklenen parasal değeri 2 birim daha yüksektir', 'İki Küçük Türbin\'i seçer; kesinlik eşdeğeri diğerinden 11 birim daha yüksektir', 'İki alternatif arasında kayıtsız kalır; kesinlik eşdeğerleri 36 birimde eşittir'], 'Tek Büyük: E[U]=0,5(10)+0,5(2)=6 => CE=36 birim (EMV=52 olmasına rağmen). İki Küçük: E[U]=0,5(8)+0,5(6)=7 => CE=49 birim; 49 - 36 = 13 birim farkla İki Küçük Türbin seçilir.'),
];
